/// Changes' range hint wraps inside its column, clear of the body's scrollbar gutter, with
/// the renamed `docs/review/界面-guide.md` open in a 461 × 490 window at 18 pt as at 13 pt:
/// its box ends where the body's content does, before the gutter, and every line it draws
/// lies inside the box. Its second phrase, alone wider than the line, was laid out on one
/// line, 649 px wide in a 344 px box at 18 pt and 468 px in 350 px at 13 pt, and drawn
/// under the scrollbar to the body's edge, natively cut there at "selects a s" (QA-106d).
#[gpui::test]
async fn the_range_hint_wraps_inside_its_column(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let scroll = panel.read_with(cx, |panel, _| panel.review.body_scroll.clone());
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let mark = gpui_kit::Background::from(crate::width_walk::text_mark());
    for interface in [13, 18] {
        let at = format!("{interface} pt");
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(461.), px(490.)));
        cx.update(|window, cx| {
            panel.update(cx, |panel, cx| {
                panel.pull = Some(pull.clone());
                panel.review.show_list = false;
                panel.review.section = Section::Files;
                panel.review.files = files.clone();
                panel.review.selected_file = None;
                panel.select_review_file(1, window, cx);
            })
        });
        settle_panel(&app, cx).await;
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        assert_eq!(
            panel.read_with(cx, |panel, _| panel.review.files[1].filename.clone()),
            "docs/review/界面-guide.md"
        );
        // The body scrolled until the hint's foot is in view, as a person reads it.
        let (hint, body) = (
            cx.debug_bounds("github-range-hint").expect("the hint"),
            cx.debug_bounds("github-panel").expect("the body"),
        );
        let below = hint.bottom() - (body.bottom() - room);
        if below > px(0.) {
            scroll.set_offset(point(px(0.), scroll.offset().y - below));
            for _ in 0..3 {
                crate::width_walk::frame(cx);
            }
        }
        let (hint, body) = (
            cx.debug_bounds("github-range-hint").expect("the hint"),
            cx.debug_bounds("github-panel").expect("the body"),
        );
        // Where the body's content ends: its gutter and the room its rings take lie past it.
        let edge = body.right() - room - crate::tags::ScrollCue::gutter();
        assert!(
            hint.right() <= edge + px(0.5),
            "{at}: the hint's box {hint:?} ends before the gutter at {edge:?}"
        );
        let lines: Vec<Bounds<Pixels>> = cx.update(|window, _| {
            let scale = window.scale_factor();
            let logical = |value: gpui_kit::ScaledPixels| px(value.0 / scale);
            window
                .painted_quads()
                .into_iter()
                .filter(|quad| quad.background == mark)
                .map(|quad| {
                    Bounds::from_corners(
                        point(logical(quad.bounds.left()), logical(quad.bounds.top())),
                        point(logical(quad.bounds.right()), logical(quad.bounds.bottom())),
                    )
                })
                // The hint's own, starting inside its box: a row of the patch above it,
                // which the patch's box clips, runs below that box's foot.
                .filter(|line| {
                    line.top() >= hint.top() - px(0.5)
                        && line.top() < hint.bottom()
                        && line.left() >= hint.left() - px(0.5)
                })
                .collect()
        });
        assert!(lines.len() > 1, "{at}: the hint draws lines {lines:?}");
        for line in &lines {
            assert!(
                line.right() <= hint.right() + px(0.5) && line.bottom() <= hint.bottom() + px(0.5),
                "{at}: the hint's line {line:?} runs past its box {hint:?}"
            );
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Reopened from the header's Pull requests, by a click or by the keyboard, at 13 and
/// 18 pt, the panel gives focus back to the control that held it as Escape closed it where
/// a frame draws that control inside the body's view, revealed whole, and otherwise to the
/// shown section's first stop, revealed whole: in a 461 × 490 window Files' patch, which
/// Tab had moved onto, takes focus back whole, and in a 461 × 360 one Files' changed-file
/// list, focused with the body scrolled past it, is shown whole as it takes focus, each
/// with its ring after a click as after the keyboard. The panel gave focus to the
/// changed-file list wherever the body had last scrolled it, above the body's top at both
/// sizes after a click, drawn nowhere in view, and Tab went on to Changes below it
/// (QA-106d); reopened by a click, it gave the patch back with no ring.
#[gpui::test]
async fn reopening_focuses_only_what_the_body_shows_whole(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let (list, patch, scroll) = panel.read_with(cx, |panel, _| {
        (
            panel.review.file_focus.clone(),
            panel.review.line_focus.clone(),
            panel.review.body_scroll.clone(),
        )
    });
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    let focused = |cx: &mut VisualTestContext, focus: &FocusHandle| {
        cx.update(|window, _| focus.is_focused(window))
    };
    // Whether `selector` lies whole inside the body with its ring's room.
    let whole = |cx: &mut VisualTestContext, selector: &'static str| {
        let body = cx.debug_bounds("github-panel").expect("the body");
        let shown = cx.debug_bounds(selector).expect(selector);
        let whole = shown.top() - room >= body.top() - px(0.5)
            && shown.bottom() + room <= body.bottom() + px(0.5);
        (whole, format!("{shown:?} in the body {body:?}"))
    };
    for interface in [13, 18] {
        for keyboard in [false, true] {
            let at = format!(
                "{interface} pt, reopened by {}",
                if keyboard { "the keyboard" } else { "a click" }
            );
            // Escape closes the panel, and the header's Pull requests opens it again: Return
            // on the button, which Escape gave focus back to, or a click on it.
            let reopen = async |cx: &mut VisualTestContext| {
                escape(cx);
                assert!(
                    !cx.update(|window, cx| window.has_active_dialog(cx)),
                    "{at}: Escape closes the panel"
                );
                let header =
                    cx.update(|window, cx| app.read(cx).pull_requests_focus.is_focused(window));
                if keyboard {
                    // Return goes down and comes up: outside a dialog, GPUI presses the
                    // focused Button as the key comes up.
                    let keystroke = gpui::Keystroke::parse("enter").unwrap();
                    cx.simulate_event(gpui::KeyDownEvent {
                        keystroke: keystroke.clone(),
                        is_held: false,
                        prefer_character_input: false,
                    });
                    cx.simulate_event(gpui::KeyUpEvent { keystroke });
                } else {
                    crate::copy_feedback::tests::click(cx, "pull-requests");
                }
                settle_panel(&app, cx).await;
                assert!(
                    cx.update(|window, cx| window.has_active_dialog(cx)),
                    "{at}: the header's Pull requests opens the panel (focused: {header})"
                );
                frames(cx);
            };
            crate::focus_ring::sweep::interface_size(cx, interface);
            cx.simulate_resize(size(px(461.), px(490.)));
            cx.update(|window, cx| {
                panel.update(cx, |panel, cx| {
                    panel.pull = Some(pull.clone());
                    panel.review.show_list = false;
                    panel.review.section = Section::Files;
                    panel.review.files = files.clone();
                    panel.review.selected_file = None;
                    panel.select_review_file(1, window, cx);
                })
            });
            settle_panel(&app, cx).await;
            frames(cx);

            // Tab from the changed-file list onto the patch, which the body shows whole.
            for _ in 0..12 {
                if focused(cx, &patch) {
                    break;
                }
                cx.simulate_keystrokes("tab");
                frames(cx);
            }
            assert!(focused(cx, &patch), "{at}: Tab reaches the patch");
            let (shown, place) = whole(cx, "github-patch");
            assert!(shown, "{at}: Tab shows the patch whole: {place}");
            reopen(cx).await;
            assert!(
                focused(cx, &patch),
                "{at}: the patch, whole in view as the panel closed, takes focus back"
            );
            let (shown, place) = whole(cx, "github-patch");
            assert!(shown, "{at}: the patch is whole: {place}");
            // Its ring, the accent outline it lays over its rows inside its own edge.
            let pane = cx.debug_bounds("github-patch").expect("the patch");
            let accent = cx.update(|_, cx| Hsla::from(rgb(palette(cx).accent)));
            let ring = quads(cx).into_iter().any(|(bounds, quad)| {
                quad.border_color == accent
                    && [
                        (bounds.left(), pane.left()),
                        (bounds.top(), pane.top()),
                        (bounds.right(), pane.right()),
                        (bounds.bottom(), pane.bottom()),
                    ]
                    .into_iter()
                    .all(|(a, b)| (a - b).abs() <= px(1.01))
            });
            assert!(
                ring,
                "{at}: the patch draws its ring, reopened by a click as by the keyboard"
            );

            // The changed-file list, focused with the body scrolled past it, in a window
            // short enough for the body to scroll it out of view.
            cx.simulate_resize(size(px(461.), px(360.)));
            cx.update(|window, cx| window.focus(&list, cx));
            frames(cx);
            let (body, shown) = (
                cx.debug_bounds("github-panel").expect("the body"),
                cx.debug_bounds("github-file-focus").expect("the list"),
            );
            let offset = scroll.offset().y - (shown.bottom() - body.top());
            assert!(
                -offset <= scroll.max_offset().y,
                "{at}: the body can scroll the list out of view"
            );
            scroll.set_offset(point(px(0.), offset));
            frames(cx);
            let shown = cx.debug_bounds("github-file-focus").expect("the list");
            assert!(
                focused(cx, &list) && shown.bottom() <= body.top() + px(0.5),
                "{at}: the focused list {shown:?} lies above the body {body:?}"
            );
            reopen(cx).await;
            assert!(
                focused(cx, &list),
                "{at}: Files' first stop, the changed-file list, takes focus"
            );
            let (shown, place) = whole(cx, "github-file-focus");
            assert!(shown, "{at}: the list is whole: {place}");
            assert!(
                outlined(cx, "github-file-focus"),
                "{at}: the list draws its ring, reopened by a click as by the keyboard"
            );
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Opened for the first time by a click on the header's Pull requests, at 13 and 18 pt, the
/// panel marks the window's keyboard ring on the focus it lands on, its destination field,
/// whose ring is drawn whole, as a reopen does and as Settings opens: a pane focus then
/// moves onto before the next pointer press draws its ring. A first open by a click left
/// the window's ring unmarked.
#[gpui::test]
async fn a_first_open_by_a_click_marks_the_ring_on_its_focus(cx: &mut TestAppContext) {
    let (_fixture, app, cx) = crate::views::tests::styled_history_window(
        cx,
        b"commit refs/heads/main\ncommitter Fixture <fixture@example.invalid> 1700000000 +0000\ndata 13\nfixture notes\nM 100644 inline notes.txt\ndata 6\nnotes\n\ndone\n",
        |root| root,
    )
    .await;
    crate::focus_ring::sweep::prepare(&app, cx);
    cx.simulate_resize(size(px(1480.), px(973.)));
    let accent = cx.update(|_, cx| Hsla::from(rgb(palette(cx).accent)));
    for interface in [13, 18] {
        let at = format!("{interface} pt");
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.update(|_, cx| cx.default_global::<WarmPanels>().0.clear());
        crate::copy_feedback::tests::click(cx, "pull-requests");
        settle_panel(&app, cx).await;
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        assert!(
            cx.update(|window, cx| window.has_active_dialog(cx)),
            "{at}: a click on the header's Pull requests opens the panel"
        );
        let (focused, marked) = cx.update(|window, cx| {
            let focused = window.focused(cx).expect("the panel takes focus");
            let marked = app.read(cx).focus_ring.shows(&focused);
            (focused, marked)
        });
        assert!(
            marked,
            "{at}: the window's ring is on the focus the panel opens with"
        );
        let field = cx.debug_bounds("github-destination").expect("the field");
        let ring = crate::focus_ring::painted_outlines(cx, accent)
            .into_iter()
            .any(|ring| ring.whole && ring.bounds.contains(&field.center()));
        assert!(
            ring,
            "{at}: the destination field {field:?} draws its ring whole"
        );
        escape(cx);
        let destination = cx.update(|_, cx| {
            let warm = cx.default_global::<WarmPanels>();
            let panel = warm.0.last().expect("the closed panel").panel.clone();
            panel.read(cx).destination.read(cx).focus_handle(cx)
        });
        assert!(
            focused == destination,
            "{at}: the panel opens with focus on its destination field"
        );
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Enter on Next PR page reaching the last page leaves focus on the Button, now disabled and
/// no Tab stop. Closed from there, the panel holds no control, so the reopen puts focus on
/// the destination field, its first stop, before any frame. The reopen once gave focus back
/// to the disabled Button, where only the next Tab could move it on.
#[gpui::test]
async fn reopening_passes_over_a_button_disabled_as_the_panel_closed(cx: &mut TestAppContext) {
    let (_fixture, app, panel, _pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let next = next_pressed_to_the_last_page(&app, &panel, cx).await;
    escape(cx);
    assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
    let field = panel.read_with(cx, |panel, cx| panel.destination.read(cx).focus_handle(cx));
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    assert!(
        cx.update(|window, _| field.is_focused(window) && !next.is_focused(window)),
        "the reopened panel puts focus on the destination field before any frame"
    );
    settle_panel(&app, cx).await;
    four_frames(cx);
    assert!(
        cx.update(|window, _| field.is_focused(window)),
        "focus stays on the destination field"
    );
}

/// Four frames of the window, each drawn.
fn four_frames(cx: &mut VisualTestContext) {
    for _ in 0..4 {
        crate::width_walk::frame(cx);
    }
}

/// Enter on Next PR page reaching the last page, with no PR open, at 13 pt in a
/// 1,480 × 800 window: focus stays on the now disabled Button, whose handle this returns.
async fn next_pressed_to_the_last_page(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    cx: &mut VisualTestContext,
) -> FocusHandle {
    crate::focus_ring::sweep::interface_size(cx, 13);
    cx.simulate_resize(size(px(1480.), px(800.)));
    cx.update(|_, cx| {
        panel.update(cx, |panel, cx| {
            panel.pull = None;
            panel.create = false;
            panel.review.show_list = true;
            panel.has_next = true;
            panel.page = 1;
            cx.notify();
        })
    });
    cx.executor().run_until_parked();
    four_frames(cx);
    let next = panel
        .read_with(cx, |panel, _| panel.review.buttons.kept("github-next"))
        .expect("Next PR page is drawn");
    cx.update(|window, cx| next.focus(window, cx));
    four_frames(cx);
    cx.simulate_keystrokes("enter");
    settle_panel(app, cx).await;
    four_frames(cx);
    assert!(
        cx.update(|window, _| next.is_focused(window))
            && panel.read_with(cx, |panel, _| panel.page == 2 && !panel.has_next),
        "Enter reaches the last page with focus on the now disabled Button"
    );
    next
}

/// A Button disabled only by a read in flight keeps the person's place. Escape cancels the
/// read, so the Button is enabled again as a click on the header's Pull requests reopens the
/// panel, and it takes focus back, whole in every frame with its ring in the last, at 13 and
/// 18 pt in a 461 × 490 window: Refresh PRs, with the body where it closed, and a PR's
/// Refresh conversations and Next conversations. Held only where it was a Tab stop as the
/// panel closed, each gave focus to the section's first stop, and with no PR open the body
/// went back to its top.
#[gpui::test]
async fn reopening_gives_focus_back_to_a_button_a_read_disabled(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let scroll = panel.read_with(cx, |panel, _| panel.review.body_scroll.clone());
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let accent: Hsla = cx.read(|cx| rgb(palette(cx).accent).into());
    let whole = |part: Bounds<Pixels>, view: Bounds<Pixels>| {
        part.top() - room >= view.top() - px(0.5) && part.bottom() + room <= view.bottom() + px(0.5)
    };
    let focused = |cx: &mut VisualTestContext, id: &'static str| {
        let focus = panel.read_with(cx, |panel, _| panel.review.buttons.kept(id));
        cx.update(|window, _| focus.is_some_and(|focus| focus.is_focused(window)))
    };
    let tab_stop = |cx: &mut VisualTestContext| {
        cx.update(|window, cx| window.focused(cx).is_some_and(|focus| focus.tab_stop))
    };
    let mut scrolled = 0;
    for interface in [13u8, 18] {
        for (id, part, selector) in [
            ("github-refresh", "refresh", "github-part-refresh"),
            (
                "github-threads-refresh",
                "conversations-header",
                "github-part-conversations-header",
            ),
            (
                "github-threads-next",
                "conversations-pager",
                "github-part-conversations-pager",
            ),
        ] {
            let at = format!("{id} at {interface} pt in 461 × 490");
            let open = id != "github-refresh";
            crate::focus_ring::sweep::interface_size(cx, interface);
            cx.simulate_resize(size(px(461.), px(490.)));
            cx.update(|window, cx| {
                panel.update(cx, |panel, cx| {
                    panel.pull = open.then(|| pull.clone());
                    panel.create = false;
                    panel.review.show_list = !open;
                    panel.review.section = Section::Overview;
                    panel.review.connection_open = !open;
                    panel.conversations.next_cursor =
                        (id == "github-threads-next").then(|| "next".to_owned());
                    panel.review.body_scroll.set_offset(point(px(0.), px(0.)));
                    panel
                        .conversations
                        .list_scroll
                        .set_offset(point(px(0.), px(0.)));
                    panel.focus_visible_section(window, cx);
                    cx.notify();
                })
            });
            settle_panel(&app, cx).await;
            four_frames(cx);
            for _ in 0..40 {
                if focused(cx, id) {
                    break;
                }
                cx.simulate_keystrokes("tab");
                four_frames(cx);
            }
            assert!(focused(cx, id), "{at}: Tab reaches the Button");
            if !open {
                // On as far as keeps the Button whole with its ring's room, so the body has
                // somewhere to go back from.
                let body = cx.debug_bounds("github-panel").expect("the body");
                let button = cx.debug_bounds(id).expect(id);
                let y = (scroll.offset().y - (button.top() - room - body.top()))
                    .clamp(-scroll.max_offset().y, px(0.));
                scroll.set_offset(point(px(0.), y));
                four_frames(cx);
            }
            // Enter starts the read, held as a slow request is. It goes down and comes up: a
            // dialog opened while it is down takes no Enter until it does, which the next
            // case's press would be.
            let read = app.read_with(cx, |app, _| app.operations.hold());
            let keystroke = gpui::Keystroke::parse("enter").unwrap();
            cx.simulate_event(gpui::KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(gpui::KeyUpEvent { keystroke });
            four_frames(cx);
            assert!(
                panel.read_with(cx, |panel, _| panel.pending),
                "{at}: the read is under way"
            );
            assert!(
                focused(cx, id) && !tab_stop(cx),
                "{at}: the Button holds focus, disabled and no Tab stop"
            );
            let closed = scroll.offset().y;
            if !open && closed < px(0.) {
                scrolled += 1;
            }
            escape(cx);
            assert!(
                !cx.update(|window, cx| window.has_active_dialog(cx)),
                "{at}: Escape closes the panel"
            );
            assert!(
                panel.read_with(cx, |panel, _| !panel.pending && panel.review.held.is_some()),
                "{at}: closing cancels the read and holds the Button"
            );
            // The cancelled read ends before the click, which the header refuses until then.
            drop(read);
            settle_panel(&app, cx).await;
            four_frames(cx);
            review::BODY_FRAMES.set(Some(Vec::new()));
            crate::copy_feedback::tests::click(cx, "pull-requests");
            settle_panel(&app, cx).await;
            four_frames(cx);
            let drawn = review::BODY_FRAMES.take().expect("watched");
            assert!(
                cx.update(|window, cx| window.has_active_dialog(cx)),
                "{at}: the header's Pull requests opens the panel"
            );
            assert!(
                focused(cx, id) && tab_stop(cx),
                "{at}: the Button, enabled again, takes focus back as a Tab stop"
            );
            assert!(
                drawn.len() >= 2,
                "{at}: the reopened panel drew {} frames",
                drawn.len()
            );
            for (index, frame) in drawn.iter().enumerate() {
                let (_, shown) = frame
                    .parts
                    .iter()
                    .find(|(name, _)| name == part)
                    .unwrap_or_else(|| panic!("{at}: frame {index} draws {part}: {frame:?}"));
                assert!(
                    whole(*shown, frame.view),
                    "{at}: frame {index} draws {part} {shown:?} whole in {:?}",
                    frame.view
                );
            }
            if !open {
                assert_eq!(
                    scroll.offset().y,
                    closed,
                    "{at}: the body stays where it closed"
                );
            }
            let body = cx.debug_bounds("github-panel").expect("the body");
            let shown = cx.debug_bounds(selector).expect(selector);
            let ring = crate::focus_ring::painted_outlines(cx, accent)
                .into_iter()
                .any(|ring| ring.whole && shown.contains(&ring.bounds.center()));
            assert!(
                whole(shown, body) && ring,
                "{at}: {part} {shown:?} is whole in the body {body:?} with the Button's ring"
            );
        }
    }
    assert_eq!(scrolled, 2, "Refresh PRs closes with the body scrolled");
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Next PR page on the last page, with a read in flight as Escape closes the panel: the read
/// disabled it too, so closing holds it, but the last page keeps it disabled as the panel
/// reopens. The frames that find it drawn find no Tab stop, so focus goes to the destination
/// field, as it does with no read in flight
/// (`reopening_passes_over_a_button_disabled_as_the_panel_closed`).
#[gpui::test]
async fn reopening_passes_over_a_held_button_the_last_page_keeps_disabled(cx: &mut TestAppContext) {
    let (_fixture, app, panel, _pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let next = next_pressed_to_the_last_page(&app, &panel, cx).await;
    // A read from elsewhere, as a click on Refresh PRs starts, which leaves focus where it is.
    let read = app.read_with(cx, |app, _| app.operations.hold());
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.refresh(2, window, cx)));
    four_frames(cx);
    assert!(
        panel.read_with(cx, |panel, _| panel.pending)
            && cx.update(|window, _| next.is_focused(window)),
        "the read is under way with focus on Next PR page"
    );
    escape(cx);
    assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
    assert!(
        panel.read_with(cx, |panel, _| panel.review.held.is_some()),
        "closing during the read holds the Button"
    );
    // The cancelled read ends before the click, which the header refuses until then.
    drop(read);
    settle_panel(&app, cx).await;
    four_frames(cx);
    let field = panel.read_with(cx, |panel, cx| panel.destination.read(cx).focus_handle(cx));
    crate::copy_feedback::tests::click(cx, "pull-requests");
    settle_panel(&app, cx).await;
    four_frames(cx);
    assert!(
        cx.update(|window, cx| window.has_active_dialog(cx)),
        "the header's Pull requests opens the panel"
    );
    assert!(
        cx.update(|window, _| field.is_focused(window) && !next.is_focused(window)),
        "the Button, still disabled, gives way to the destination field"
    );
    assert_eq!(
        panel.read_with(cx, |panel, _| panel.review.body_scroll.offset().y),
        px(0.),
        "the destination field shows the body from its top"
    );
    let shown = cx.debug_bounds("github-destination").expect("the field");
    let accent: Hsla = cx.read(|cx| rgb(palette(cx).accent).into());
    let ring = crate::focus_ring::painted_outlines(cx, accent)
        .into_iter()
        .any(|ring| ring.whole && ring.bounds.contains(&shown.center()));
    assert!(ring, "the field {shown:?} draws its ring whole");
}

/// The busy row's Cancel goes with the read closing cancels, so it is no place to come back
/// to: closed from it, every frame of the reopened panel draws focus on the destination
/// field. Held, focus sat on a control no frame drew until the fallback moved it two frames
/// later.
#[gpui::test]
async fn reopening_gives_no_focus_to_the_cancel_closing_takes_away(cx: &mut TestAppContext) {
    let (_fixture, app, panel, _pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    crate::focus_ring::sweep::interface_size(cx, 13);
    cx.simulate_resize(size(px(1480.), px(800.)));
    cx.update(|_, cx| {
        panel.update(cx, |panel, cx| {
            panel.pull = None;
            panel.create = false;
            panel.review.show_list = true;
            cx.notify();
        })
    });
    cx.executor().run_until_parked();
    four_frames(cx);
    let read = app.read_with(cx, |app, _| app.operations.hold());
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.refresh(1, window, cx)));
    four_frames(cx);
    let cancel = panel.read_with(cx, |panel, _| panel.cancel_request.handle().clone());
    cx.update(|window, cx| cancel.focus(window, cx));
    four_frames(cx);
    assert!(
        cx.debug_bounds("github-cancel").is_some()
            && cx.update(|window, _| cancel.is_focused(window)),
        "the busy row's Cancel holds focus, drawn in the body"
    );
    escape(cx);
    assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
    // The cancelled read ends before the reopen, which is refused until then.
    drop(read);
    settle_panel(&app, cx).await;
    four_frames(cx);
    let field = panel.read_with(cx, |panel, cx| panel.destination.read(cx).focus_handle(cx));
    review::BODY_FRAMES.set(Some(Vec::new()));
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    settle_panel(&app, cx).await;
    four_frames(cx);
    let drawn = review::BODY_FRAMES.take().expect("watched");
    assert!(
        drawn.len() >= 2,
        "the reopened panel drew {} frames",
        drawn.len()
    );
    for (index, frame) in drawn.iter().enumerate() {
        assert_eq!(
            frame.focused.as_ref(),
            Some(&field),
            "frame {index} draws focus on the destination field"
        );
    }
    assert!(
        cx.debug_bounds("github-cancel").is_none(),
        "the reopened panel draws no busy row"
    );
}

/// Files' patch, whole in a 461 × 490 window at 13 pt as Escape closes the panel and so
/// held, which a larger text size or a shorter window moves out of the reopened body's
/// view while the panel is closed, gives way as a click on the header's Pull requests
/// reopens the panel: the frame that first draws the reopened panel finds the patch outside
/// the body's view, so focus goes to the section's first stop, the changed-file list, drawn
/// whole with its ring, as at 18 pt in 461 × 300, 461 × 360 and 461 × 490 windows. Where the
/// reopened body still shows the patch, as at 13 pt in a 461 × 300 window, it keeps focus,
/// whole. No test reached this way out: the held controls of the others still lay in view,
/// or had already left it as the panel closed.
#[gpui::test]
async fn reopening_after_the_held_patch_moves_out_of_view_focuses_the_file_list(
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let (list, patch) = panel.read_with(cx, |panel, _| {
        (
            panel.review.file_focus.clone(),
            panel.review.line_focus.clone(),
        )
    });
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..6 {
            crate::width_walk::frame(cx);
        }
    };
    let focused = |cx: &mut VisualTestContext, focus: &FocusHandle| {
        cx.update(|window, _| focus.is_focused(window))
    };
    // Whether the reopened body shows the held patch: at 18 pt it lies past the body's
    // fold in each of these windows; at 13 pt in a 461 × 300 one the body still shows it.
    for (interface, height, shown) in [
        (18u8, 300., false),
        (18, 360., false),
        (13, 300., true),
        (18, 490., false),
    ] {
        let at = format!("reopened at {interface} pt in 461 × {height}");
        crate::focus_ring::sweep::interface_size(cx, 13);
        cx.simulate_resize(size(px(461.), px(490.)));
        cx.update(|window, cx| {
            panel.update(cx, |panel, cx| {
                panel.pull = Some(pull.clone());
                panel.review.show_list = false;
                panel.review.section = Section::Files;
                panel.review.files = files.clone();
                panel.review.selected_file = None;
                panel.select_review_file(1, window, cx);
            })
        });
        settle_panel(&app, cx).await;
        frames(cx);
        for _ in 0..12 {
            if focused(cx, &patch) {
                break;
            }
            cx.simulate_keystrokes("tab");
            frames(cx);
        }
        assert!(focused(cx, &patch), "{at}: Tab reaches the patch");
        escape(cx);
        assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
        // While the panel is closed: a new text size and a shorter window.
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(461.), px(height)));
        frames(cx);
        crate::copy_feedback::tests::click(cx, "pull-requests");
        settle_panel(&app, cx).await;
        assert!(cx.update(|window, cx| window.has_active_dialog(cx)));
        frames(cx);
        let body = cx.debug_bounds("github-panel").expect("the body");
        let (which, selector, held) = if shown {
            ("the patch", "github-patch", &patch)
        } else {
            ("the changed-file list", "github-file-focus", &list)
        };
        assert!(focused(cx, held), "{at}: {which} holds focus");
        let held = cx.debug_bounds(selector).expect(selector);
        assert!(
            held.top() - room >= body.top() - px(0.5)
                && held.bottom() + room <= body.bottom() + px(0.5),
            "{at}: {which} {held:?} holds focus whole in the body {body:?}"
        );
        if which == "the changed-file list" {
            assert!(
                outlined(cx, selector),
                "{at}: {which} draws its ring after the click"
            );
        }
        escape(cx);
        crate::copy_feedback::tests::click(cx, "pull-requests");
        settle_panel(&app, cx).await;
        frames(cx);
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// A Button of the body that held focus as Escape closed the panel takes it back as a click
/// on the header's Pull requests reopens it, drawn whole in the body with its ring:
/// Overview's Open captured local comparison, Files' Comment on selection and Overview's
/// first conversation's Reply, each reached by Tab, at 13 pt in a 1,480 × 973 window, and
/// at 18 pt in a 461 × 490 one with the body scrolled until one of its edges runs through
/// the Button as the panel closes. Every frame the reopened panel draws shows the part
/// holding the Button whole, and Reply's conversation actions whole in the conversation
/// list and the body. Each kept its focus handle in its own element state, which went with
/// the closed dialog's frame, so reopening gave focus to the section's first stop.
#[gpui::test]
async fn reopening_gives_focus_back_to_a_body_button(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let scroll = panel.read_with(cx, |panel, _| panel.review.body_scroll.clone());
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    let whole = |part: Bounds<Pixels>, view: Bounds<Pixels>| {
        part.top() - room >= view.top() - px(0.5) && part.bottom() + room <= view.bottom() + px(0.5)
    };
    let kept = |cx: &mut VisualTestContext, id: &ElementId| {
        panel.read_with(cx, |panel, _| panel.review.buttons.kept(id.clone()))
    };
    let focused = |cx: &mut VisualTestContext, id: &ElementId| {
        let focus = kept(cx, id);
        cx.update(|window, _| focus.is_some_and(|focus| focus.is_focused(window)))
    };
    let buttons: [(Section, ElementId, &'static str); 3] = [
        (
            Section::Overview,
            "github-open-changes".into(),
            "github-open-changes",
        ),
        (
            Section::Files,
            "github-inline-start".into(),
            "github-inline-start",
        ),
        (
            Section::Overview,
            ("github-thread-reply", 0usize).into(),
            "github-thread-reply-0",
        ),
    ];
    // Each case: its text size, its window, and whether the body cuts the Button as the
    // panel closes.
    for (interface, width, height, cut) in [(13u8, 1480., 973., false), (18, 461., 490., true)] {
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(width), px(height)));
        for (section, id, selector) in buttons.clone() {
            let at = format!("{selector} at {interface} pt in {width} × {height}");
            cx.update(|window, cx| {
                panel.update(cx, |panel, cx| {
                    panel.pull = Some(pull.clone());
                    panel.review.show_list = false;
                    panel.review.section = section;
                    panel.review.files = files.clone();
                    panel.review.selected_file = None;
                    if section == Section::Files {
                        panel.select_review_file(1, window, cx);
                    }
                    panel.review.body_scroll.set_offset(point(px(0.), px(0.)));
                    panel
                        .conversations
                        .list_scroll
                        .set_offset(point(px(0.), px(0.)));
                    panel.focus_visible_section(window, cx);
                    cx.notify();
                })
            });
            settle_panel(&app, cx).await;
            frames(cx);
            for _ in 0..40 {
                if focused(cx, &id) {
                    break;
                }
                cx.simulate_keystrokes("tab");
                frames(cx);
            }
            assert!(focused(cx, &id), "{at}: Tab reaches the Button");
            let body = cx.debug_bounds("github-panel").expect("the body");
            let shown = cx.debug_bounds(selector).expect(selector);
            assert!(
                whole(shown, body),
                "{at}: Tab shows the Button {shown:?} whole in {body:?}"
            );
            if cut {
                // The body's foot, or else its top, runs through the Button's middle.
                let (y, max) = (scroll.offset().y, scroll.max_offset().y);
                let (down, up) = (
                    body.bottom() - shown.center().y,
                    shown.center().y - body.top(),
                );
                let target = if y + down <= px(0.) { y + down } else { y - up };
                assert!(
                    target <= px(0.) && target >= -max,
                    "{at}: the body scrolls from {y:?} to {target:?} within {max:?}"
                );
                scroll.set_offset(point(px(0.), target));
                frames(cx);
                let shown = cx.debug_bounds(selector).expect(selector);
                assert!(
                    !whole(shown, body)
                        && shown.top() < body.bottom()
                        && shown.bottom() > body.top(),
                    "{at}: the body {body:?} cuts the Button {shown:?} as the panel closes"
                );
            }
            let before = kept(cx, &id);
            escape(cx);
            assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
            let part = panel
                .read_with(cx, |panel, _| panel.review.held_part.clone())
                .map(|(_, name)| name)
                .unwrap_or_else(|| panic!("{at}: closing holds the Button's part"));
            review::BODY_FRAMES.set(Some(Vec::new()));
            crate::copy_feedback::tests::click(cx, "pull-requests");
            settle_panel(&app, cx).await;
            frames(cx);
            let drawn = review::BODY_FRAMES.take().expect("watched");
            assert!(
                focused(cx, &id) && kept(cx, &id) == before,
                "{at}: the Button, focused as the panel closed, takes focus back as it reopens"
            );
            assert!(
                drawn.len() >= 2,
                "{at}: the reopened panel drew {} frames",
                drawn.len()
            );
            for (index, frame) in drawn.iter().enumerate() {
                let find = |name: &str| {
                    frame
                        .parts
                        .iter()
                        .find(|(drawn, _)| drawn == name)
                        .map(|(_, bounds)| *bounds)
                        .unwrap_or_else(|| panic!("{at}: frame {index} draws {name}: {frame:?}"))
                };
                let held = find(&part);
                assert!(
                    whole(held, frame.view),
                    "{at}: frame {index} draws {part} {held:?} whole in {:?}",
                    frame.view
                );
                if selector == "github-thread-reply-0" {
                    // The first conversation's actions, Reply first among them.
                    let actions = find("0");
                    let viewport = frame.list.expect("the frame draws the conversation list");
                    assert!(
                        whole(actions, viewport) && whole(actions, frame.view),
                        "{at}: frame {index} draws Reply's actions {actions:?} whole in the \
                         list {viewport:?} and the body {:?}",
                        frame.view
                    );
                }
            }
            let body = cx.debug_bounds("github-panel").expect("the body");
            let shown = cx.debug_bounds(selector).expect(selector);
            assert!(
                whole(shown, body) && ringed(cx, selector),
                "{at}: the Button {shown:?} is whole in the body {body:?} with its ring"
            );
            if selector == "github-thread-reply-0" {
                let viewport = cx.debug_bounds("github-threads").expect("the list");
                assert!(
                    whole(shown, viewport),
                    "{at}: Reply {shown:?} is whole in the list {viewport:?}"
                );
            }
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// `part`, with its ring's room, is whole inside `view`, or, where it is taller than `view`,
/// shows its top edge there.
fn revealed_whole(part: Bounds<Pixels>, view: Bounds<Pixels>, room: Pixels) -> bool {
    if part.size.height + room * 2. > view.size.height {
        part.top() - room >= view.top() - px(0.5) && part.top() < view.bottom()
    } else {
        part.top() - room >= view.top() - px(0.5) && part.bottom() + room <= view.bottom() + px(0.5)
    }
}

/// The PR row that held focus as the panel closed, its title cut by the body's foot, is
/// whole in the first frame the reopened panel paints: at 13 and 18 pt at the sweep's sizes
/// ([`REVEAL_SIZES`]), the title with its ring's room inside the body's view and the PR
/// list's in every frame. A row is a [`review::PULL`] part, so the reopened panel held no
/// part for it and painted it cut until the Reveal phase scrolled it into view; what a
/// reopen focuses is decided in the frame's layout, before its content prepaints
/// (DESIGN.md, "Keyboard focus").
#[gpui::test]
async fn reopening_draws_a_held_pr_row_the_bodys_foot_cut_whole_in_its_first_frame(
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let rows: Vec<PullRequest> = (0..12)
        .map(|index| {
            let mut row = pull.clone();
            row.number = pull.number + index;
            row.title = format!("Fixture row {index} of twelve in a list past its cap");
            row
        })
        .collect();
    let number = rows[0].number;
    let id: ElementId = ("github-pr", number).into();
    let selector: &'static str = Box::leak(format!("github-pr-{number}").into_boxed_str());
    // The sixth row, below the list's fold at every size until the list scrolls.
    let later = pull.number + 5;
    let later_id: ElementId = ("github-pr", later).into();
    let later_selector: &'static str = Box::leak(format!("github-pr-{later}").into_boxed_str());
    // Long enough to stand the rows below the body's foot at every size.
    let notice = (0..80)
        .map(|line| format!("Line {line} of a notice that makes the body overflow."))
        .collect::<Vec<_>>()
        .join("\n");
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.rows = rows));
    let (scroll, list) = panel.read_with(cx, |panel, _| {
        (
            panel.review.body_scroll.clone(),
            panel.review.pull_scroll.clone(),
        )
    });
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    for (interface, width, height) in REVEAL_SIZES {
        let at = format!("at {interface} pt in {width} × {height}");
        show_surface(
            (&app, &panel, &pull, &[]),
            Surface::Pulls,
            (interface, width, height),
            cx,
        )
        .await;
        cx.update(|_, cx| {
            panel.update(cx, |panel, cx| {
                panel.notice = Some(notice.clone());
                cx.notify();
            })
        });
        settle_panel(&app, cx).await;
        frames(cx);
        let name = panel.read_with(cx, |panel, _| panel.row_parts[0].1.clone());
        let body = cx.debug_bounds("github-panel").expect("the body");
        let title = cx.debug_bounds(selector).expect("the row's title");
        let (y, max) = (scroll.offset().y, scroll.max_offset().y);
        let target = y + body.bottom() - title.center().y;
        assert!(
            target <= px(0.) && target >= -max,
            "{at}: the body scrolls from {y:?} to {target:?} within {max:?}"
        );
        scroll.set_offset(point(px(0.), target));
        frames(cx);
        let focus = panel
            .read_with(cx, |panel, _| panel.review.buttons.kept(id.clone()))
            .expect("the row's title takes focus");
        cx.update(|window, cx| focus.focus(window, cx));
        frames(cx);
        let body = cx.debug_bounds("github-panel").expect("the body");
        let shown = cx.debug_bounds(selector).expect("the row's title");
        assert!(
            !revealed_whole(shown, body, room)
                && shown.top() < body.bottom()
                && shown.bottom() > body.bottom(),
            "{at}: the body's foot {body:?} runs through the row {shown:?} as the panel \
             closes"
        );
        assert_held_row_reopens_whole((&app, &panel), &focus, &name, room, &at, cx).await;
        cx.update(|_, cx| {
            panel.update(cx, |panel, cx| {
                panel.notice = None;
                cx.notify();
            })
        });

        // A later row the list's own foot cuts: the list scrolls first, in that frame's
        // layout, so its title is whole in the list and the body from the first frame.
        let at = format!("the sixth row at {interface} pt in {width} × {height}");
        show_surface(
            (&app, &panel, &pull, &[]),
            Surface::Pulls,
            (interface, width, height),
            cx,
        )
        .await;
        list.set_offset(point(px(0.), px(0.)));
        frames(cx);
        let name = panel.read_with(cx, |panel, _| panel.row_parts[5].1.clone());
        // A row wholly below the fold draws nothing a selector records: bring its top in.
        let (view, card) = (
            list.bounds(),
            list.bounds_for_item(5).expect("the sixth row"),
        );
        assert!(
            card.top() > view.bottom() - px(8.),
            "{at}: the row {card:?} starts below the list's fold {view:?}"
        );
        let y = list.offset().y - (card.top() - view.bottom() + px(8.));
        list.set_offset(point(px(0.), y));
        frames(cx);
        // Its title's middle on the list's foot, and all of the list in the body's view.
        let view = list.bounds();
        let title = cx.debug_bounds(later_selector).expect("the row's title");
        let y = list.offset().y + view.bottom() - title.center().y;
        list.set_offset(point(px(0.), y));
        let body = cx.debug_bounds("github-panel").expect("the body");
        let (y, max) = (scroll.offset().y, scroll.max_offset().y);
        let y = (y + body.top() + room - view.top()).clamp(-max, px(0.));
        scroll.set_offset(point(px(0.), y));
        frames(cx);
        let focus = panel
            .read_with(cx, |panel, _| panel.review.buttons.kept(later_id.clone()))
            .expect("the row's title takes focus");
        cx.update(|window, cx| focus.focus(window, cx));
        frames(cx);
        let (body, view) = (
            cx.debug_bounds("github-panel").expect("the body"),
            list.bounds(),
        );
        let shown = cx.debug_bounds(later_selector).expect("the row's title");
        assert!(
            !revealed_whole(shown, view, room)
                && shown.top() < view.bottom()
                && shown.bottom() > view.bottom()
                && shown.top() < body.bottom()
                && shown.bottom() > body.top(),
            "{at}: the list's foot {view:?} runs through the row {shown:?} inside the body \
             {body:?} as the panel closes"
        );
        assert_held_row_reopens_whole((&app, &panel), &focus, &name, room, &at, cx).await;
        list.set_offset(point(px(0.), px(0.)));
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Closes the panel with `focus`, the title of the PR row `name`, held inside the body's
/// view, reopens it by a click on the header's Pull requests and asserts that every frame
/// it paints, the first among them, draws the title whole with `room` clear of the edges of
/// the body's view and the PR list's, focus back on the title.
async fn assert_held_row_reopens_whole(
    (app, panel): (&Entity<GitTurtle>, &Entity<Panel>),
    focus: &FocusHandle,
    name: &SharedString,
    room: Pixels,
    at: &str,
    cx: &mut VisualTestContext,
) {
    escape(cx);
    assert!(
        !cx.update(|window, cx| window.has_active_dialog(cx)),
        "{at}: Escape closes the panel"
    );
    assert_eq!(
        panel.read_with(cx, |panel, _| panel.review.held_part.clone()),
        Some((review::PULL, name.clone())),
        "{at}: closing holds the row"
    );
    review::BODY_FRAMES.set(Some(Vec::new()));
    crate::copy_feedback::tests::click(cx, "pull-requests");
    settle_panel(app, cx).await;
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
    let drawn = review::BODY_FRAMES.take().expect("watched");
    assert!(
        cx.update(|window, _| focus.is_focused(window)),
        "{at}: the row takes focus back"
    );
    assert!(!drawn.is_empty(), "{at}: the reopened panel drew no frame");
    for (index, frame) in drawn.iter().enumerate() {
        let held = frame
            .parts
            .iter()
            .find(|(drawn, _)| drawn == name)
            .map(|(_, bounds)| *bounds)
            .unwrap_or_else(|| panic!("{at}: frame {index} draws the row"));
        assert!(
            revealed_whole(held, frame.view, room) && revealed_whole(held, frame.pulls, room),
            "{at}: frame {index} draws the row {held:?} whole in the body {:?} and the list \
             {:?}",
            frame.view,
            frame.pulls
        );
    }
}

/// With no control held as the panel closed, the shown section's first stop that the reopen
/// focuses is whole in the first frame the reopened panel paints, however the body had
/// scrolled: Files' changed-file list and Overview's conversations pane, at 13 and 18 pt at
/// the sweep's sizes ([`REVEAL_SIZES`]), with the body at its end, where the stop lies above
/// its view. Revealed once a frame found it on the focus path, the stop came into view a
/// frame late, cut or out of view in the frames before.
#[gpui::test]
async fn reopening_draws_the_sections_first_stop_whole_in_its_first_frame(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let scroll = panel.read_with(cx, |panel, _| panel.review.body_scroll.clone());
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    let mut scrolled = 0;
    for (interface, width, height) in REVEAL_SIZES {
        for (surface, part) in [
            (Surface::Changes, "file-rows"),
            (Surface::Overview, "conversations"),
        ] {
            let at = format!("{part} at {interface} pt in {width} × {height}");
            show_surface(
                (&app, &panel, &pull, &files),
                surface,
                (interface, width, height),
                cx,
            )
            .await;
            if scroll.max_offset().y <= px(0.) {
                continue;
            }
            scrolled += 1;
            scroll.set_offset(point(px(0.), -scroll.max_offset().y));
            frames(cx);
            escape(cx);
            assert!(
                !cx.update(|window, cx| window.has_active_dialog(cx)),
                "{at}: Escape closes the panel"
            );
            // No control to give focus back to: the reopen focuses the section's first stop.
            cx.update(|_, cx| {
                panel.update(cx, |panel, _| {
                    panel.review.held = None;
                    panel.review.held_part = None;
                })
            });
            review::BODY_FRAMES.set(Some(Vec::new()));
            crate::copy_feedback::tests::click(cx, "pull-requests");
            settle_panel(&app, cx).await;
            frames(cx);
            let drawn = review::BODY_FRAMES.take().expect("watched");
            assert!(!drawn.is_empty(), "{at}: the reopened panel drew no frame");
            for (index, frame) in drawn.iter().enumerate() {
                let shown = frame
                    .parts
                    .iter()
                    .find(|(drawn, _)| drawn == part)
                    .map(|(_, bounds)| *bounds)
                    .unwrap_or_else(|| panic!("{at}: frame {index} draws {part}"));
                assert!(
                    revealed_whole(shown, frame.view, room),
                    "{at}: frame {index} draws {shown:?} whole in {:?}",
                    frame.view
                );
            }
            escape(cx);
        }
    }
    assert!(scrolled > 0, "some size scrolls the body");
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Cuts `selector`, a form of the body holding `focus`, at the body's foot, or else its
/// top, closes the panel, reopens it by a click on the header's Pull requests and asserts
/// that every frame it paints, the first among them, draws the form whole with `room` clear
/// of the body's edges, focus still on it.
async fn assert_held_form_reopens_whole(
    (app, panel): (&Entity<GitTurtle>, &Entity<Panel>),
    selector: &'static str,
    focus: &FocusHandle,
    room: Pixels,
    at: &str,
    cx: &mut VisualTestContext,
) {
    let scroll = panel.read_with(cx, |panel, _| panel.review.body_scroll.clone());
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    cx.update(|window, cx| focus.focus(window, cx));
    frames(cx);
    let body = cx.debug_bounds("github-panel").expect("the body");
    let form = cx.debug_bounds(selector).expect(selector);
    let (y, max) = (scroll.offset().y, scroll.max_offset().y);
    let (down, up) = (
        y + body.bottom() - form.center().y,
        y - (form.center().y - body.top()),
    );
    let target = if down <= px(0.) && down >= -max {
        down
    } else {
        up
    };
    assert!(
        target <= px(0.) && target >= -max,
        "{at}: the body scrolls from {y:?} to {target:?} within {max:?}"
    );
    scroll.set_offset(point(px(0.), target));
    frames(cx);
    let body = cx.debug_bounds("github-panel").expect("the body");
    let form = cx.debug_bounds(selector).expect(selector);
    assert!(
        !revealed_whole(form, body, room)
            && form.top() < body.bottom()
            && form.bottom() > body.top(),
        "{at}: the body {body:?} cuts the form {form:?} as the panel closes"
    );
    escape(cx);
    assert!(
        !cx.update(|window, cx| window.has_active_dialog(cx)),
        "{at}: Escape closes the panel"
    );
    assert!(
        panel.read_with(cx, |panel, _| panel.review.held.is_some()),
        "{at}: closing holds the form"
    );
    review::BODY_FRAMES.set(Some(Vec::new()));
    crate::copy_feedback::tests::click(cx, "pull-requests");
    settle_panel(app, cx).await;
    frames(cx);
    let drawn = review::BODY_FRAMES.take().expect("watched");
    assert!(
        cx.update(|window, _| focus.is_focused(window)),
        "{at}: the form takes focus back"
    );
    assert!(!drawn.is_empty(), "{at}: the reopened panel drew no frame");
    for (index, frame) in drawn.iter().enumerate() {
        let shown = frame
            .parts
            .iter()
            .find(|(drawn, _)| drawn == review::FOCUSED_FORM)
            .map(|(_, bounds)| *bounds)
            .unwrap_or_else(|| panic!("{at}: frame {index} draws the form"));
        assert!(
            revealed_whole(shown, frame.view, room),
            "{at}: frame {index} draws the form {shown:?} whole in {:?}",
            frame.view
        );
    }
}

/// A review summary or reply composer that held focus as the panel closed, cut by the
/// body's edge, is whole in the first frame the reopened panel paints: neither lies in a
/// part of the body, so its mark stood idle while reveals waited, and the form was whole
/// only from the frame after the phase ended. The summary at the sweep's sizes
/// ([`REVEAL_SIZES`]), a long notice making the body overflow at each, and the reply
/// composer, a padded pane, in 461 px windows tall enough to hold it whole, its open
/// conversation standing a notice above the body rather than among the content.
#[gpui::test]
async fn reopening_draws_a_held_form_the_body_cut_whole_in_its_first_frame(
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let notice = (0..80)
        .map(|line| format!("Line {line} of a notice that makes the body overflow."))
        .collect::<Vec<_>>()
        .join("\n");
    for (interface, width, height) in REVEAL_SIZES {
        let at = format!("the summary at {interface} pt in {width} × {height}");
        show_surface(
            (&app, &panel, &pull, &[]),
            Surface::Review,
            (interface, width, height),
            cx,
        )
        .await;
        cx.update(|_, cx| {
            panel.update(cx, |panel, cx| {
                panel.notice = Some(notice.clone());
                cx.notify();
            })
        });
        settle_panel(&app, cx).await;
        let (focus, room) = cx.update(|_, cx| {
            (
                panel.read(cx).body.read(cx).focus_handle(cx),
                appearance::button_ring_room(cx),
            )
        });
        assert_held_form_reopens_whole(
            (&app, &panel),
            "github-review-summary",
            &focus,
            room,
            &at,
            cx,
        )
        .await;
        escape(cx);
        cx.update(|_, cx| {
            panel.update(cx, |panel, cx| {
                panel.notice = None;
                cx.notify();
            })
        });
        cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
        settle_panel(&app, cx).await;
    }
    for (interface, height) in [(13u8, 640.), (18, 900.)] {
        let at = format!("the reply composer at {interface} pt in 461 × {height}");
        show_surface(
            (&app, &panel, &pull, &[]),
            Surface::Overview,
            (interface, 461., height),
            cx,
        )
        .await;
        cx.update(|window, cx| {
            panel.update(cx, |panel, cx| {
                let target = panel.conversations.threads[0].target.clone();
                panel.begin_reply(target, window, cx);
            })
        });
        settle_panel(&app, cx).await;
        let (focus, room) = cx.update(|window, cx| {
            (
                panel.read(cx).conversations.input.read(cx).focus_handle(cx),
                review::reveal_room(window, cx),
            )
        });
        assert_held_form_reopens_whole(
            (&app, &panel),
            "github-reply-composer",
            &focus,
            room,
            &at,
            cx,
        )
        .await;
        cx.update(|_, cx| panel.update(cx, |panel, _| panel.conversations.active = None));
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// With a single page of files both pager buttons are disabled and no stop reveals the
/// page label, so the Files list's accessible name carries the page reading; a further
/// page drops it, its pager then a stop that reveals the label. The name is all that
/// changes: the list stays one Tab stop and draws nothing new.
#[gpui::test]
async fn the_files_lists_name_carries_the_single_page_reading(cx: &mut TestAppContext) {
    use crate::native_accessibility::written;
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    show_surface(
        (&app, &panel, &pull, &files),
        Surface::Changes,
        (13, 1480., 800.),
        cx,
    )
    .await;
    let name = |cx: &mut VisualTestContext| {
        written::forget();
        crate::tags::tests::draw(cx);
        written::get("github-file-focus").and_then(|list| list.node.label().map(str::to_owned))
    };
    cx.update(|_, cx| {
        panel.update(cx, |panel, cx| {
            panel.review.file_page = 1;
            panel.review.files_next = false;
            cx.notify();
        })
    });
    assert_eq!(
        name(cx).as_deref(),
        Some("Pull request changed files, page 1 of 1"),
        "a single page's list carries the page reading"
    );
    cx.update(|_, cx| {
        panel.update(cx, |panel, cx| {
            panel.review.files_next = true;
            cx.notify();
        })
    });
    assert_eq!(
        name(cx).as_deref(),
        Some("Pull request changed files"),
        "a further page leaves the reading to the pager's stop"
    );
    let page = cx
        .debug_bounds("github-files-page")
        .expect("the page label");
    assert!(page.size.width > px(0.), "the page label still draws");
    // Before a page has loaded, or where reading it failed, there is no page to name.
    cx.update(|_, cx| {
        panel.update(cx, |panel, cx| {
            panel.review.files_next = false;
            panel.review.files.clear();
            panel.review.selected_file = None;
            cx.notify();
        })
    });
    assert_eq!(
        name(cx).as_deref(),
        Some("Pull request changed files"),
        "no page loaded, no page reading"
    );
}

/// A live drag keeps Send and Keep editing whole in the body's view while either holds
/// focus: a comment's confirmation at 13 pt and at 18 pt, where the two stand on two rows,
/// as a 461 px window shrinks from 973 to about 490 px tall, every frame of each step. Only the focused region's reveal ran from the
/// frame's layout, and the row's part reveals after paint only after a key, so with focus
/// placed on either Button the body's foot came to cut them.
#[gpui::test]
async fn a_live_drag_keeps_send_whole_while_it_or_keep_editing_holds_focus(
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    for (interface, id) in [13u8, 18]
        .into_iter()
        .flat_map(|size| ["github-confirm-send", "github-edit-submission"].map(|id| (size, id)))
    {
        open_confirmation(
            (&panel, &pull),
            confirmed_comment(),
            (interface, 461., 973.),
            cx,
        );
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        let focus = panel
            .read_with(cx, |panel, _| panel.review.buttons.kept(id))
            .expect(id);
        cx.update(|window, cx| focus.focus(window, cx));
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        confirm_frames();
        for step in 1..=8 {
            let height = 973. - 60. * step as f32;
            let at = format!("{id} at {interface} pt, {height} px tall");
            cx.simulate_resize(size(px(461.), px(height)));
            cx.executor().run_until_parked();
            crate::width_walk::frame(cx);
            let frames = confirm_frames();
            assert!(!frames.is_empty(), "{at}: the confirmation draws");
            for (index, frame) in frames.iter().enumerate() {
                let (actions, body) = (frame.actions, frame.body);
                assert!(
                    actions.top() >= body.top() - px(0.5)
                        && actions.bottom() <= body.bottom() + px(0.5),
                    "{at}: frame {index} draws Send and Keep editing {actions:?} whole in \
                     the body {body:?}"
                );
            }
            assert!(
                cx.update(|window, _| focus.is_focused(window)),
                "{at}: focus stays"
            );
        }
        cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
        for _ in 0..2 {
            crate::width_walk::frame(cx);
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// A body the person wheeled away from the confirmation stays where it is through a change
/// of the view's size alone: with the region focused or, after Tab, Send, at 13 pt in a
/// 461 × 490 window, wheeled to its top with the confirmation below its foot, neither a
/// resize nor a change of the text size brings the body back. Only a change of focus
/// reveals what the person wheeled away from.
#[gpui::test]
async fn a_body_wheeled_away_from_the_confirmation_stays_through_a_resize(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let (scroll, region) = panel.read_with(cx, |panel, _| {
        (
            panel.review.body_scroll.clone(),
            panel.conversations.confirm_focus.clone(),
        )
    });
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    for on_send in [false, true] {
        for resize in [true, false] {
            let at = format!(
                "{} through {}",
                if on_send { "Send" } else { "the region" },
                if resize { "a resize" } else { "a text size" }
            );
            open_confirmation((&panel, &pull), confirmed_comment(), (13, 461., 490.), cx);
            frames(cx);
            assert!(
                scroll.offset().y < px(0.),
                "{at}: the opening confirmation scrolled the body"
            );
            let focus = if on_send {
                cx.simulate_keystrokes("tab");
                frames(cx);
                panel
                    .read_with(cx, |panel, _| {
                        panel.review.buttons.kept("github-confirm-send")
                    })
                    .expect("Send")
            } else {
                region.clone()
            };
            assert!(
                cx.update(|window, _| focus.is_focused(window)),
                "{at}: focus is where the walk put it"
            );
            let body = cx.debug_bounds("github-panel").expect("the body");
            cx.simulate_event(ScrollEvent {
                position: body.origin + point(px(2.), px(2.)),
                delta: ScrollDelta::Pixels(point(px(0.), px(5000.))),
                modifiers: Modifiers::default(),
                touch_phase: TouchPhase::Moved,
                source: Default::default(),
            });
            frames(cx);
            assert_eq!(scroll.offset().y, px(0.), "{at}: the wheel reaches the top");
            let (body, send) = (
                cx.debug_bounds("github-panel").expect("the body"),
                cx.debug_bounds("github-confirm-send").expect("Send"),
            );
            assert!(
                send.top() >= body.bottom(),
                "{at}: the wheel took Send {send:?} out of the body {body:?}"
            );
            if resize {
                cx.simulate_resize(size(px(461.), px(540.)));
                cx.executor().run_until_parked();
            } else {
                crate::focus_ring::sweep::interface_size(cx, 15);
            }
            frames(cx);
            assert_eq!(
                scroll.offset().y,
                px(0.),
                "{at}: the body stays where the person wheeled it"
            );
            assert!(
                cx.update(|window, _| focus.is_focused(window)),
                "{at}: focus stays"
            );
            cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
            frames(cx);
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

