/// Reopened by a click on the header's Pull requests onto Files' patch, which held focus as
/// Escape closed the panel, the panel draws the patch whole with its ring's room in every
/// frame it paints, the first among them, where the patch keeps focus: at 13 and 18 pt in
/// a 461 × 490 window with the body scrolled until one of its edges runs through the
/// patch as the panel closes, and with the patch whole at the body's foot as it closes in
/// a 461 × 490 window, which a 461 × 420 one cuts at 13 pt while the panel is closed, and a
/// 380 × 490 one at 18 pt, its text wrapped again above the patch. The reopened body
/// revealed the patch only once a frame had found it drawn, so the patch came into view in
/// the third or fourth frame, cut at the body's foot in the frames before.
#[gpui::test]
async fn every_frame_of_a_reopen_draws_the_held_patch_whole(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let (patch, scroll) = panel.read_with(cx, |panel, _| {
        (
            panel.review.line_focus.clone(),
            panel.review.body_scroll.clone(),
        )
    });
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    let focused = |cx: &mut VisualTestContext| cx.update(|window, _| patch.is_focused(window));
    let whole = |part: Bounds<Pixels>, view: Bounds<Pixels>| {
        part.top() - room >= view.top() - px(0.5) && part.bottom() + room <= view.bottom() + px(0.5)
    };
    // Each case: its text size, whether the body cuts the patch as the panel closes, and
    // the window's size as it reopens.
    for (interface, cut, (width, height)) in [
        (13u8, true, (461., 490.)),
        (18, true, (461., 490.)),
        (13, false, (461., 420.)),
        (18, false, (380., 490.)),
    ] {
        let at = format!("{interface} pt, reopened in {width} × {height}");
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(461.), px(490.)));
        cx.update(|window, cx| {
            panel.update(cx, |panel, cx| {
                panel.pull = Some(pull.clone());
                panel.review.show_list = false;
                panel.review.section = Section::Files;
                panel.review.files = files.clone();
                panel.review.selected_file = None;
                panel.select_review_file(1, window, cx);
                panel.focus_visible_section(window, cx);
            })
        });
        settle_panel(&app, cx).await;
        frames(cx);
        for _ in 0..12 {
            if focused(cx) {
                break;
            }
            cx.simulate_keystrokes("tab");
            frames(cx);
        }
        assert!(focused(cx), "{at}: Tab reaches the patch");
        let body = cx.debug_bounds("github-panel").expect("the body");
        let shown = cx.debug_bounds("github-part-patch").expect("the patch");
        assert!(
            whole(shown, body),
            "{at}: Tab shows the patch {shown:?} whole in {body:?}"
        );
        // The body moved so that its foot, or else its top, runs through the patch's
        // middle, or so that the patch lies whole at its foot, which a shorter window cuts.
        let (y, max) = (scroll.offset().y, scroll.max_offset().y);
        let target = if cut {
            let (down, up) = (
                body.bottom() - shown.center().y,
                shown.center().y - body.top(),
            );
            if y + down <= px(0.) { y + down } else { y - up }
        } else if width < 461. {
            // The text wrapped again lowers the patch, by about 185 px here, so the panel
            // closes with it where the narrower body still shows its top, cut at the foot
            // (some 51 px below the body's top at 461 px): wholly out of view it would lose
            // focus rather than be revealed. Measured at that width.
            cx.simulate_resize(size(px(width), px(height)));
            frames(cx);
            let view = cx.debug_bounds("github-panel").expect("the body");
            let lower = cx.debug_bounds("github-part-patch").expect("the patch");
            let content = lower.top() - view.top() - scroll.offset().y;
            cx.simulate_resize(size(px(461.), px(490.)));
            frames(cx);
            view.size.height - px(30.) - content
        } else {
            y + (body.bottom() - room - shown.bottom())
        };
        assert!(
            target <= px(0.) && target >= -max,
            "{at}: the body scrolls from {y:?} to {target:?} within {max:?}"
        );
        scroll.set_offset(point(px(0.), target));
        frames(cx);
        let closed = scroll.offset().y;
        let shown = cx.debug_bounds("github-part-patch").expect("the patch");
        assert!(
            whole(shown, body) != cut && shown.top() < body.bottom() && shown.bottom() > body.top(),
            "{at}: the body {body:?} shows the patch {shown:?} as the panel closes"
        );
        escape(cx);
        assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
        cx.simulate_resize(size(px(width), px(height)));
        frames(cx);
        review::BODY_FRAMES.set(Some(Vec::new()));
        crate::copy_feedback::tests::click(cx, "pull-requests");
        settle_panel(&app, cx).await;
        frames(cx);
        let drawn = review::BODY_FRAMES.take().expect("watched");
        assert!(
            focused(cx),
            "{at}: the patch, in the body's view as the panel closed, keeps focus"
        );
        assert!(
            drawn.len() >= 4,
            "{at}: the reopened panel drew {} frames",
            drawn.len()
        );
        for (index, frame) in drawn.iter().enumerate() {
            let (_, part) = frame
                .parts
                .iter()
                .find(|(name, _)| name == "patch")
                .unwrap_or_else(|| panic!("{at}: frame {index} draws the patch: {frame:?}"));
            assert!(
                whole(*part, frame.view),
                "{at}: frame {index} draws the patch {part:?} whole in {:?}",
                frame.view
            );
        }
        if !cut {
            // The shorter window's body is shorter than the one the panel closed in, and
            // the narrower window's is narrower, with the patch lower in it.
            let first = drawn[0].view;
            assert!(
                first.size.height < body.size.height || first.size.width < body.size.width,
                "{at}: the body {first:?} is smaller than it closed at {body:?}"
            );
            // Where the body closed, the resized panel cuts the patch, so the first frame
            // moves the body.
            assert_ne!(
                scroll.offset().y,
                closed,
                "{at}: the reopened body moves to the patch"
            );
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// A confirmation a test opens, by what it confirms, and how it is made.
type Confirming = (&'static str, fn() -> Confirmation);

/// A confirmation a test opens, by what it confirms, how it is made, and at what text size
/// and window size.
type Opening = (&'static str, fn() -> Confirmation, (u8, f32, f32));

/// A reply to a conversation confirmed for sending, its destination naming every node ID
/// its target has, after the fixture PR's full head and base commit IDs, and its text
/// `lines` lines long, ending "The reply's last line.".
fn confirmed_long_reply(lines: usize) -> Confirmation {
    let repository = Repository::parse("gitturtle-fixture/native-review").unwrap();
    let target = CapturedThread {
        pull: github::review::fixture_pull(false).capture(repository),
        account: "offline-reviewer".into(),
        account_id: "U_kgDOAccountNode0123456789".into(),
        repository_id: "R_kgDORepositoryNode0123456789".into(),
        pull_id: "PR_kwDOPullRequestNode0123456789".into(),
        thread_id: "PRRT_kwDOReviewThreadNode0123456789".into(),
        path: "src/deeply/nested/module/with/a/long/path/review.rs".into(),
        root_comment_id: Some("PRRC_kwDORootCommentNode0123456789".into()),
        original_commit_id: None,
    };
    let mut body: Vec<String> = (1..lines)
        .map(|line| format!("Line {line} of a reply long enough to run past the region."))
        .collect();
    body.push("The reply's last line.".into());
    Confirmation {
        account: target.account.clone(),
        action: Action::Reply {
            target,
            body: body.join("\n"),
        },
    }
}

/// The text sizes and window sizes the confirmation's one stop is walked at
/// ([`the_confirmation_is_one_stop_whole_beside_send_at`]), in the order one test walked
/// them. Each is one test now, its own slice of this list below.
const ONE_STOP_SIZES: [(u8, f32, f32); 4] = [
    (13, 1480., 973.),
    (18, 461., 490.),
    (13, 461., 490.),
    (18, 1480., 973.),
];

/// The slice of [`ONE_STOP_SIZES`] each part of the walk runs, in the list's order;
/// `the_parts_of_the_one_stop_walk_run_each_size_once` holds them to the list.
const ONE_STOP_AT_13_PT_IN_1480_BY_973: std::ops::Range<usize> = 0..1;
const ONE_STOP_AT_18_PT_IN_461_BY_490: std::ops::Range<usize> = 1..2;
const ONE_STOP_AT_13_PT_IN_461_BY_490: std::ops::Range<usize> = 2..3;
const ONE_STOP_AT_18_PT_IN_1480_BY_973: std::ops::Range<usize> = 3..4;

/// The outbound confirmation's one Tab stop is the region that scrolls its destination and
/// text: at 13 and 18 pt in 1,480 × 973 and 461 × 490 windows, for a comment and
/// for a long reply whose destination names every node ID, a walk with Tab and one with
/// Shift+Tab round the panel's Review each meet the region once, its ring whole on the edge
/// of the room around it, with Send and Keep editing whole in the body's view below it, and
/// every other stop's ring whole too (`focus_ring::sweep`). Shown whole, the confirmation
/// was the stop, 446 px tall at 18 pt in a 461 × 490 window, where the body is about 265 px,
/// so no reveal could draw its ring whole; made without a Tab stop, its handle let both walks
/// pass over it.
///
/// Walked at `sizes`, a slice of [`ONE_STOP_SIZES`], on a panel of its own: one test a
/// size, since the sixteen walks in one test took 86.4 s on a hosted runner, against the
/// 120 s at which nextest ends a test.
async fn the_confirmation_is_one_stop_whole_beside_send_at(
    sizes: std::ops::Range<usize>,
    cx: &mut TestAppContext,
) {
    use crate::focus_ring::sweep;
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let region = panel.read_with(cx, |panel, _| panel.conversations.confirm_focus.clone());
    let confirmations: [Confirming; 2] = [
        ("a comment", confirmed_comment),
        ("a long reply", || confirmed_long_reply(40)),
    ];
    let mut failures = Vec::new();
    for (interface, width, height) in ONE_STOP_SIZES[sizes].iter().copied() {
        sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(width), px(height)));
        for (kind, confirmation) in confirmations {
            for key in ["tab", "shift-tab"] {
                let at =
                    format!("{kind} by {key} at {interface} pt in a {width} × {height} window");
                // The confirmation as Review submission… opens it, its region focused.
                cx.update(|window, cx| {
                    panel.update(cx, |panel, cx| {
                        panel.pull = Some(pull.clone());
                        panel.review.show_list = false;
                        panel.review.section = Section::Review;
                        panel.confirm = Some(confirmation());
                        panel.focus_confirmation(window, cx);
                    })
                });
                cx.executor().run_until_parked();
                let mut met = 0;
                sweep::walk_each(
                    &app,
                    cx,
                    key,
                    &format!(
                        "the GitHub panel's confirmation of {kind} in a {width} × {height} window"
                    ),
                    interface,
                    &mut failures,
                    &mut |cx, stop, ring| {
                        if !cx.update(|window, _| region.is_focused(window)) {
                            return;
                        }
                        met += 1;
                        let edge = cx
                            .debug_bounds("github-confirm-ring")
                            .expect("the ring's room");
                        assert!(
                            ring.iter().any(|outline| outline.whole
                                && sweep::rings_edge(&[outline.bounds], edge)),
                            "{stop}: the region draws its ring whole on {edge:?}, not only {ring:?}"
                        );
                        let body = cx.debug_bounds("github-panel").expect("the body");
                        for shown in [
                            "github-confirm-ring",
                            "github-confirm-send",
                            "github-edit-submission",
                        ] {
                            let drawn = cx.debug_bounds(shown).expect(shown);
                            assert!(
                                drawn.top() >= body.top() - px(0.5)
                                    && drawn.bottom() <= body.bottom() + px(0.5),
                                "{stop}: {shown} {drawn:?} lies whole in the body {body:?}"
                            );
                        }
                    },
                );
                assert_eq!(met, 1, "{at}: the walk meets the region once");
            }
        }
    }
    sweep::assert_whole(failures);
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

