/// The four parts of the confirmation's walk run [`ONE_STOP_SIZES`] between them, each
/// size once and in the list's order, and each part runs one size at least: a size added
/// to the list that no part takes fails here, as does one two parts take.
#[test]
fn the_parts_of_the_one_stop_walk_run_each_size_once() {
    let parts = [
        ONE_STOP_AT_13_PT_IN_1480_BY_973,
        ONE_STOP_AT_18_PT_IN_461_BY_490,
        ONE_STOP_AT_13_PT_IN_461_BY_490,
        ONE_STOP_AT_18_PT_IN_1480_BY_973,
    ];
    assert!(
        parts.iter().all(|part| !part.is_empty()),
        "a part runs no size: {parts:?}"
    );
    let run: Vec<_> = parts
        .into_iter()
        .flat_map(|part| ONE_STOP_SIZES[part].iter().copied())
        .collect();
    assert_eq!(run, ONE_STOP_SIZES);
}

/// Reopening draws no confirmation, so focus held on its region, Send or Keep editing as
/// Escape closed the panel goes to Review's first stop, there from the first frame the
/// reopened panel draws. The reopen once gave it back to the handle the panel still kept,
/// which nothing drew, and it sat there for two frames before the fallback moved it.
#[gpui::test]
async fn reopening_gives_no_focus_to_the_confirmation_it_drops(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let summary = cx.read(|cx| panel.read(cx).body.read(cx).focus_handle(cx));
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    for control in [
        "github-confirm-region",
        "github-confirm-send",
        "github-edit-submission",
    ] {
        let at = format!("closed with focus on {control}");
        open_confirmation((&panel, &pull), confirmed_comment(), (13, 1480., 973.), cx);
        frames(cx);
        let focus = panel.read_with(cx, |panel, _| match control {
            "github-confirm-region" => panel.conversations.confirm_focus.clone(),
            button => panel
                .review
                .buttons
                .kept(button)
                .unwrap_or_else(|| panic!("the panel keeps {button}'s handle")),
        });
        cx.update(|window, cx| focus.focus(window, cx));
        frames(cx);
        assert!(
            cx.update(|window, _| focus.is_focused(window)),
            "{at}: the control holds focus"
        );
        escape(cx);
        assert!(
            !cx.update(|window, cx| window.has_active_dialog(cx)),
            "{at}: Escape closes the panel"
        );
        assert!(
            panel.read_with(cx, |panel, _| panel.review.held.is_none()),
            "{at}: closing holds none of the confirmation's controls"
        );
        review::BODY_FRAMES.set(Some(Vec::new()));
        cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
        settle_panel(&app, cx).await;
        frames(cx);
        let drawn = review::BODY_FRAMES.take().expect("watched");
        assert!(
            drawn.len() >= 2,
            "{at}: the reopened panel drew {} frames",
            drawn.len()
        );
        for (index, frame) in drawn.iter().enumerate() {
            assert_eq!(
                frame.focused.as_ref(),
                Some(&summary),
                "{at}: frame {index} draws focus on Review's first stop"
            );
        }
        assert!(
            cx.update(|window, _| summary.is_focused(window)),
            "{at}: focus stays on Review's first stop"
        );
        assert!(
            cx.debug_bounds("github-confirm-send").is_none(),
            "{at}: the reopened panel draws no confirmation"
        );
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The confirmation's region scrolls by keys while it holds focus, under its own key
/// context: at 13 and 18 pt in 1,480 × 973 and 461 × 490 windows, a reply whose
/// destination names every node ID and whose text runs past the region opens at its top;
/// Down and Up move it a line, Page Down to its end, where its last line ends at the region's
/// foot, End stays there and Home goes back to its top, focus staying on the region and Send
/// whole in the body's view. The region is a group named for what it confirms that
/// holds the destination, with the full head and base commit IDs and every node ID, and the
/// text.
#[gpui::test]
async fn the_confirmation_region_scrolls_a_long_reply_by_keys(cx: &mut TestAppContext) {
    use crate::native_accessibility::written;
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let (region, scroll) = panel.read_with(cx, |panel, _| {
        (
            panel.conversations.confirm_focus.clone(),
            panel.conversations.confirm_scroll.clone(),
        )
    });
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    let near = |a: Pixels, b: Pixels| (a - b).abs() <= px(0.01);
    for (interface, width, height) in [
        (13, 1480., 973.),
        (18, 461., 490.),
        (13, 461., 490.),
        (18, 1480., 973.),
    ] {
        let at = format!("{interface} pt in a {width} × {height} window");
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(width), px(height)));
        let confirmation = confirmed_long_reply(60);
        let Action::Reply { target, .. } = &confirmation.action else {
            unreachable!("a reply")
        };
        let target = target.clone();
        cx.update(|window, cx| {
            panel.update(cx, |panel, cx| {
                panel.pull = Some(pull.clone());
                panel.review.show_list = false;
                panel.review.section = Section::Review;
                panel.confirm = Some(confirmation);
                panel.focus_confirmation(window, cx);
            })
        });
        cx.executor().run_until_parked();
        written::forget();
        frames(cx);

        let group = written::get("github-confirm-region").expect("the region's node");
        assert_eq!(
            group.node.role(),
            Role::Group,
            "{at}: the region is a group"
        );
        assert_eq!(
            group.node.label(),
            Some("Confirm the reply: its destination and what Send sends"),
            "{at}: named for what it confirms"
        );
        for held in ["github-confirm-destination", "github-confirm-text"] {
            assert!(
                written::lies_in(held, "github-confirm-region"),
                "{at}: the region holds {held}"
            );
        }
        // The guidance: in the region after the destination at 18 pt in the narrow window,
        // where the body cannot hold it beside the buttons and the region's two lines, and
        // below the region, above Send, at 13 pt in the wide one.
        let mut place = |selector: &'static str| cx.debug_bounds(selector).expect(selector);
        let (destination, guidance, ring, sent) = (
            place("github-confirm-destination"),
            place("github-confirm-guidance"),
            place("github-confirm-ring"),
            place("github-confirm-send"),
        );
        let within = written::lies_in("github-confirm-guidance", "github-confirm-region");
        let narrow = width < 1000.;
        if interface == 18 && narrow {
            assert!(within, "{at}: the region holds the guidance");
            assert!(
                guidance.top() >= destination.bottom(),
                "{at}: the guidance {guidance:?} follows the destination {destination:?}"
            );
        } else if interface == 13 && !narrow {
            assert!(!within, "{at}: the guidance stands outside the region");
            assert!(
                guidance.top() >= ring.bottom() && guidance.bottom() <= sent.top(),
                "{at}: the guidance {guidance:?} stands below the region's ring {ring:?}, \
                 above Send {sent:?}"
            );
        }
        let destination = written::get("github-confirm-destination")
            .and_then(|text| text.node.value().map(str::to_owned))
            .expect("the destination's text");
        assert_eq!(target.pull.head.sha.len(), 40, "a full commit ID");
        for identity in [
            &target.pull.head.sha,
            &target.pull.base.sha,
            &target.account_id,
            &target.repository_id,
            &target.pull_id,
            &target.thread_id,
        ] {
            assert!(
                destination.contains(identity.as_str()),
                "{at}: the destination names {identity} whole: {destination}"
            );
        }

        let send = |cx: &mut VisualTestContext, after: &str| {
            let body = cx.debug_bounds("github-panel").expect("the body");
            let drawn = cx.debug_bounds("github-confirm-send").expect("Send");
            assert!(
                drawn.top() >= body.top() - px(0.5) && drawn.bottom() <= body.bottom() + px(0.5),
                "{at}, after {after}: Send {drawn:?} lies whole in the body {body:?}"
            );
            assert!(
                cx.update(|window, _| region.is_focused(window)),
                "{at}, after {after}: the region keeps focus"
            );
        };
        let end = scroll.max_offset().y;
        assert!(end > px(0.), "{at}: the reply runs past the region");
        assert!(
            near(scroll.offset().y, px(0.)),
            "{at}: the region opens at its top"
        );
        send(cx, "opening");
        let line = panel.read_with(cx, |panel, _| panel.conversations.confirm_fit.get().line);
        assert!(line > px(0.), "{at}: the line measured");
        cx.simulate_keystrokes("down");
        frames(cx);
        assert!(
            near(scroll.offset().y, -line),
            "{at}: Down moves a line: {:?}",
            scroll.offset()
        );
        cx.simulate_keystrokes("up");
        frames(cx);
        assert!(near(scroll.offset().y, px(0.)), "{at}: Up moves it back");
        let mut presses = 0;
        while !near(scroll.offset().y, -end) && presses < 100 {
            cx.simulate_keystrokes("pagedown");
            frames(cx);
            presses += 1;
        }
        assert!(
            near(scroll.offset().y, -end),
            "{at}: Page Down reaches the end"
        );
        let (shown, text) = (
            cx.debug_bounds("github-confirm-region")
                .expect("the region"),
            cx.debug_bounds("github-confirm-text").expect("the text"),
        );
        assert!(
            (text.bottom() - shown.bottom()).abs() <= px(0.5),
            "{at}: the reply's last line ends at the region's foot: {text:?} in {shown:?}"
        );
        send(cx, "Page Down");
        cx.simulate_keystrokes("end");
        frames(cx);
        assert!(near(scroll.offset().y, -end), "{at}: End stays at the end");
        cx.simulate_keystrokes("pageup");
        frames(cx);
        assert!(scroll.offset().y > -end, "{at}: Page Up moves back a page");
        cx.simulate_keystrokes("home");
        frames(cx);
        assert!(
            near(scroll.offset().y, px(0.)),
            "{at}: Home returns to the top"
        );
        send(cx, "Home");
    }
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The confirmation's region never takes less than two of its lines: at 18 pt in a
/// 461 × 300 window, where the body's 120 px floor leaves less room than the confirmation's
/// buttons alone take, a long reply's region is two of its 12 pt lines tall.
#[gpui::test]
async fn the_confirmation_region_keeps_two_lines_in_a_short_body(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    open_confirmation(
        (&panel, &pull),
        confirmed_long_reply(40),
        (18, 461., 300.),
        cx,
    );
    for _ in 0..4 {
        crate::width_walk::frame(cx);
    }
    let line = panel.read_with(cx, |panel, _| panel.conversations.confirm_fit.get().line);
    assert!(line > px(20.), "a 12 pt line at 18 pt: {line:?}");
    let region = cx
        .debug_bounds("github-confirm-region")
        .expect("the region");
    assert!(
        (region.size.height - line * 2.).abs() <= px(0.5),
        "the region is two {line:?} lines tall: {:?}",
        region.size.height
    );
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The confirmation's frames drawn since the last take ([`conversations::ConfirmFrame`]).
fn confirm_frames() -> Vec<conversations::ConfirmFrame> {
    conversations::CONFIRM_FRAMES.with(|frames| frames.take())
}

/// Opens `confirmation` on the open PR's Review as Review submission… opens it, its region
/// focused, at `interface` pt in a `width` × `height` window.
fn open_confirmation(
    (panel, pull): (&Entity<Panel>, &PullRequest),
    confirmation: Confirmation,
    (interface, width, height): (u8, f32, f32),
    cx: &mut VisualTestContext,
) {
    crate::focus_ring::sweep::interface_size(cx, interface);
    cx.simulate_resize(size(px(width), px(height)));
    cx.executor().run_until_parked();
    // The frames the confirmation open before drew at the new size.
    confirm_frames();
    cx.update(|window, cx| {
        panel.update(cx, |panel, cx| {
            panel.pull = Some(pull.clone());
            panel.review.show_list = false;
            panel.review.section = Section::Review;
            panel.confirm = Some(confirmation);
            panel.focus_confirmation(window, cx);
        })
    });
    cx.executor().run_until_parked();
}

/// Every frame the confirmation draws as it opens lays its region out at the height it
/// settles at, its ring and Send and Keep editing fitting the body's view together, and the
/// settled frame draws Send and Keep editing whole in that view: a comment's in a new panel
/// at 13 pt in a 1,480 × 973 window, which, laid out before any confirmation had been
/// measured, took the whole room the body leaves, and a short comment's right after a long
/// reply's at that size and at 18 pt in a 461 × 490 window, which opened as tall as the
/// reply's, sized from what the reply held.
#[gpui::test]
async fn a_confirmation_lays_its_region_out_at_its_own_height_from_its_first_frame(
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let opens: [Opening; 5] = [
        (
            "a comment in a new panel",
            confirmed_comment,
            (13, 1480., 973.),
        ),
        (
            "a long reply",
            || confirmed_long_reply(60),
            (13, 1480., 973.),
        ),
        ("a comment after it", confirmed_comment, (13, 1480., 973.)),
        (
            "a long reply",
            || confirmed_long_reply(60),
            (18, 461., 490.),
        ),
        ("a comment after it", confirmed_comment, (18, 461., 490.)),
    ];
    for (kind, confirmation, (interface, width, height)) in opens {
        let at = format!("{kind} at {interface} pt in a {width} × {height} window");
        open_confirmation(
            (&panel, &pull),
            confirmation(),
            (interface, width, height),
            cx,
        );
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        let frames = confirm_frames();
        let settled = *frames.last().expect("the confirmation draws");
        let (room, reveal) = cx.update(|window, cx| {
            (
                appearance::button_ring_room(cx),
                review::reveal_room(window, cx),
            )
        });
        let region = |frame: &conversations::ConfirmFrame| frame.ring.size.height - room * 2.;
        for (index, frame) in frames.iter().enumerate() {
            assert!(
                (region(frame) - region(&settled)).abs() <= px(0.5),
                "{at}: frame {index} lays the region out {:?} tall, not the {:?} it settles at",
                region(frame),
                region(&settled)
            );
            let together = frame.actions.bottom() - frame.ring.top();
            assert!(
                together <= frame.body.size.height - reveal * 2. + px(0.5),
                "{at}: frame {index}: the region's ring and Send and Keep editing, {together:?} \
                 together, fit the body's {:?} view",
                frame.body.size.height
            );
        }
        let body = cx.debug_bounds("github-panel").expect("the body");
        for shown in ["github-confirm-send", "github-edit-submission"] {
            let drawn = cx.debug_bounds(shown).expect(shown);
            assert!(
                drawn.top() >= body.top() - px(0.5) && drawn.bottom() <= body.bottom() + px(0.5),
                "{at}: {shown} {drawn:?} lies whole in the body {body:?}"
            );
        }
    }
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// A window made only shorter lays the confirmation's region out for the body it draws
/// in: with a long reply's region focused at 13 pt in a 1,480 × 973 window, every frame
/// drawn as the window becomes 1,480 × 486, the first included, draws Send and Keep
/// editing inside the body, where nothing in the confirmation rewraps. Sized from the view
/// the last frame drew, the region kept its 612 px for the 290 px body, Send below its
/// foot, until some other frame drew.
#[gpui::test]
async fn a_shorter_window_lays_the_confirmation_out_for_its_body_at_once(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    open_confirmation(
        (&panel, &pull),
        confirmed_long_reply(80),
        (13, 1480., 973.),
        cx,
    );
    for _ in 0..6 {
        crate::width_walk::frame(cx);
    }
    let inside = |frame: &conversations::ConfirmFrame| {
        frame.actions.top() >= frame.body.top() - px(0.5)
            && frame.actions.bottom() <= frame.body.bottom() + px(0.5)
    };
    let before = confirm_frames();
    assert!(
        before.last().is_some_and(inside),
        "Send and Keep editing lie in the body before the resize: {:?}",
        before.last()
    );
    // Height only: the width stays, so nothing in the confirmation rewraps.
    cx.simulate_resize(size(px(1480.), px(486.)));
    cx.executor().run_until_parked();
    crate::width_walk::frame(cx);
    let frames = confirm_frames();
    assert!(
        !frames.is_empty(),
        "the shorter window draws the confirmation"
    );
    for (index, frame) in frames.iter().enumerate() {
        assert!(
            inside(frame),
            "frame {index} after the resize: Send and Keep editing {:?} lie in the body {:?}",
            frame.actions,
            frame.body
        );
    }
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
}

/// Asserts that each of `frames`, the confirmation's frames since something changed, draws
/// the confirmation in the form the last one settles in: the guidance in the same place, in
/// the region or below it, and the region, inside `room` for its ring, at the same height.
fn assert_confirmation_form_settled(
    at: &str,
    frames: &[conversations::ConfirmFrame],
    room: Pixels,
) {
    let settled = *frames
        .last()
        .unwrap_or_else(|| panic!("{at}: the confirmation draws"));
    let region = |frame: &conversations::ConfirmFrame| frame.ring.size.height - room * 2.;
    let place = |frame: &conversations::ConfirmFrame| {
        if frame.inside {
            "in the region"
        } else {
            "below the region"
        }
    };
    for (index, frame) in frames.iter().enumerate() {
        assert_eq!(
            frame.inside,
            settled.inside,
            "{at}: frame {index} of {} stands the guidance {}, where it settles {}",
            frames.len(),
            place(frame),
            place(&settled)
        );
        assert!(
            (region(frame) - region(&settled)).abs() <= px(0.5),
            "{at}: frame {index} lays the region out {:?} tall, not the {:?} it settles at",
            region(frame),
            region(&settled)
        );
    }
}

/// [`assert_confirmation_form_settled`], the region's ring and Send and Keep editing
/// fitting the body's view together in each of `frames`, with `reveal`, the reveal's room,
/// at either edge, and Send and Keep editing whole in that view in every frame, the first
/// included: the body's reveal of the focused region is decided from the frame's layout,
/// before the frame draws it (DESIGN.md, "Keyboard focus").
fn assert_confirmation_settled(
    at: &str,
    frames: &[conversations::ConfirmFrame],
    rooms: (Pixels, Pixels),
) {
    assert_confirmation_settled_from(at, frames, rooms, 0);
}

/// [`assert_confirmation_settled`], with Send and Keep editing whole in the body's view
/// from frame `first`: frame 0 of a change of the top line above a focused region, which
/// asks for the region's reveal in that frame, so the body moves in the next.
fn assert_confirmation_settled_from(
    at: &str,
    frames: &[conversations::ConfirmFrame],
    (room, reveal): (Pixels, Pixels),
    first: usize,
) {
    assert_confirmation_form_settled(at, frames, room);
    for (index, frame) in frames.iter().enumerate() {
        let (actions, body) = (frame.actions, frame.body);
        let together = actions.bottom() - frame.ring.top();
        assert!(
            together <= body.size.height - reveal * 2. + px(0.5),
            "{at}: frame {index}: the region's ring and Send and Keep editing, {together:?} \
             together, fit the body's {:?} view",
            body.size.height
        );
        let whole = actions.top() >= body.top() - px(0.5)
            && actions.bottom() <= body.bottom() + px(0.5)
            && actions.right() <= body.right() + px(0.5);
        assert!(
            whole || index < first,
            "{at}: frame {index} draws Send and Keep editing {actions:?} whole in the body \
             {body:?}"
        );
    }
}

/// A new panel's first confirmation takes its form in its first frame: at 18 pt in a 461 ×
