/// The sentence a test stands on the panel's top line: one line in a 1,480 px window, several
/// in a 461 px one.
const TOP_LINE_NOTICE: &str = "Check the captured conversation and its exact text before you send this reply, and repeat nothing after an uncertain attempt.";

/// Opens the first conversation's reply on `pull`, drafts a reply long enough to run past the
/// confirmation's region, stands `notice` on the top line above the body, and confirms the
/// reply as Review reply… does, its region focused, at `interface` pt in a `width` × `height`
/// window: unlike [`open_confirmation`], with `conversations.active` set, as a real reply's.
fn open_reply_confirmation(
    panel: (&Entity<Panel>, &PullRequest),
    notice: Option<&str>,
    window: (u8, f32, f32),
    cx: &mut VisualTestContext,
) {
    let body = (1..80)
        .map(|line| format!("Line {line} of a reply long enough to run past the region."))
        .collect::<Vec<_>>()
        .join("\n");
    open_reply_confirmation_saying(panel, body, notice, window, cx);
}

/// [`open_reply_confirmation`] for a reply that says `body`.
fn open_reply_confirmation_saying(
    (panel, pull): (&Entity<Panel>, &PullRequest),
    body: String,
    notice: Option<&str>,
    (interface, width, height): (u8, f32, f32),
    cx: &mut VisualTestContext,
) {
    crate::focus_ring::sweep::interface_size(cx, interface);
    cx.simulate_resize(size(px(width), px(height)));
    cx.executor().run_until_parked();
    cx.update(|window, cx| {
        panel.update(cx, |panel, cx| {
            panel.pull = Some(pull.clone());
            panel.review.show_list = false;
            panel.review.section = Section::Overview;
            let target = panel.conversations.threads[0].target.clone();
            panel.begin_reply(target, window, cx);
            panel
                .conversations
                .input
                .update(cx, |input, cx| input.set_value(body, window, cx));
            panel.notice = notice.map(Into::into);
            panel.review_reply(window, cx);
            assert!(panel.confirm.is_some(), "the reply is confirmed");
            assert!(
                panel.conversations.active.is_some(),
                "its conversation is open"
            );
        })
    });
    cx.executor().run_until_parked();
}

/// A reply's region keeps its height through a resize that rewraps the top line standing
/// above the body: with a real reply's region focused, its conversation open and a notice on
/// the top line, every frame drawn as the window goes from 1,480 × 973 to 461 × 973 at
/// 13 pt, where the notice wraps onto several lines, and back, the first included, lays the
/// region out at the height it settles at. Read from the height the last frame drew, the
/// first narrow frame's region was the line's new height too tall, the body measured short
/// by as much, the second's as much too short, and the third settled.
#[gpui::test]
async fn a_reply_confirmation_keeps_its_region_as_the_top_line_rewraps(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    open_reply_confirmation(
        (&panel, &pull),
        Some(TOP_LINE_NOTICE),
        (13, 1480., 973.),
        cx,
    );
    let frames = |cx: &mut VisualTestContext| {
        cx.executor().run_until_parked();
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        confirm_frames()
    };
    let rooms = cx.update(|window, cx| {
        (
            appearance::button_ring_room(cx),
            review::reveal_room(window, cx),
        )
    });
    let line = |cx: &mut VisualTestContext| {
        cx.debug_bounds("github-top-line")
            .expect("the top line stands above the body")
            .size
            .height
    };
    frames(cx);
    let wide = line(cx);
    cx.simulate_resize(size(px(461.), px(973.)));
    let narrowing = frames(cx);
    let narrow = line(cx);
    assert!(
        narrow > wide + px(20.),
        "the notice wraps onto more lines: {wide:?}, then {narrow:?}"
    );
    assert_confirmation_settled(
        "a real reply's region focused at 13 pt, a notice on the top line, as the window \
         becomes 461 × 973 from 1,480 × 973",
        &narrowing,
        rooms,
    );
    cx.simulate_resize(size(px(1480.), px(973.)));
    let widening = frames(cx);
    assert_confirmation_settled(
        "a real reply's region focused at 13 pt, a notice on the top line, as the window \
         becomes 1,480 × 973 from 461 × 973",
        &widening,
        rooms,
    );
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
}

/// Every frame of a resize across the width where Send and Keep editing go from one row to
/// two lays the confirmation out in the form that width decides: at 18 pt, with a long
/// reply's region focused in a window 973 px tall, narrowing by one pixel from the last
/// width that holds them on one row and widening back, each frame, the first included,
/// draws what the form leaves for them, keeps the region at the height it settles at, and
/// draws them whole in the body's view ([`assert_confirmation_settled`]). The width is found by laying them out, so it holds
/// for the font a platform draws them in.
#[gpui::test]
async fn the_confirmation_settles_across_its_buttons_row_boundary(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    open_confirmation(
        (&panel, &pull),
        confirmed_long_reply(60),
        (18, 1480., 973.),
        cx,
    );
    // Whether the window `width` px wide stands Keep editing on a row below Send's.
    let two_rows = |cx: &mut VisualTestContext, width: i32| {
        cx.simulate_resize(size(px(width as f32), px(973.)));
        cx.executor().run_until_parked();
        crate::width_walk::frame(cx);
        let send = cx.debug_bounds("github-confirm-send").expect("Send");
        let keep = cx
            .debug_bounds("github-edit-submission")
            .expect("Keep editing");
        keep.top() > send.top() + px(0.5)
    };
    // Narrower than the half tile, so the bound holds in a narrower platform font too.
    let (mut two, mut one) = (400, 1480);
    assert!(two_rows(cx, two), "two rows at 18 pt in a 400 px window");
    assert!(!two_rows(cx, one), "one row at 18 pt in a 1,480 px window");
    while one - two > 1 {
        let width = (one + two) / 2;
        if two_rows(cx, width) {
            two = width;
        } else {
            one = width;
        }
    }
    let rooms = cx.update(|window, cx| {
        (
            appearance::button_ring_room(cx),
            review::reveal_room(window, cx),
        )
    });
    for (from, to) in [(one, two), (two, one)] {
        let at = format!("as the window goes from {from} to {to} px wide at 18 pt");
        assert_eq!(two_rows(cx, from), from == two, "{at}: the row before");
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        confirm_frames();
        assert_eq!(two_rows(cx, to), to == two, "{at}: the row after");
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        let frames = confirm_frames();
        let form = panel
            .read_with(cx, |panel, _| {
                panel.conversations.confirm_form.borrow().clone()
            })
            .expect("the form decided");
        for (index, frame) in frames.iter().enumerate() {
            assert!(
                (frame.chrome - form.chrome).abs() <= px(0.5),
                "{at}: frame {index} draws {:?} besides its region and guidance, not the \
                 {:?} its form leaves",
                frame.chrome,
                form.chrome
            );
        }
        assert_confirmation_settled(&at, &frames, rooms);
    }
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The busy row keeps Cancel whole inside it, its label wrapping beside the Button: at 18 pt
/// in a 461 × 490 window, for every request the row can be about, above the body with a
/// conversation open and among the content with none. Left on one line, the label pushed
/// Cancel past the row's right edge, and past the window's for most of them.
#[gpui::test]
async fn the_busy_row_keeps_cancel_inside_it_whatever_it_says(cx: &mut TestAppContext) {
    thread_local! {
        static CANCEL: crate::views::TextWidth = const { RefCell::new(None) };
    }
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    open_reply_confirmation((&panel, &pull), None, (18, 461., 490.), cx);
    let width = cx.update(|window, _| {
        crate::placed_button_width(
            crate::label_text_width("Cancel", &CANCEL, window),
            false,
            window,
        )
    });
    let mut outside = Vec::new();
    for pinned in [true, false] {
        let place = if pinned {
            "above the body"
        } else {
            "among the content"
        };
        for kind in RequestKind::ALL {
            cx.update(|_, cx| {
                panel.update(cx, |panel, cx| {
                    panel.pending = true;
                    panel.request = kind;
                    if !pinned {
                        panel.confirm = None;
                        panel.conversations.active = None;
                    }
                    cx.notify();
                })
            });
            cx.executor().run_until_parked();
            for _ in 0..4 {
                crate::width_walk::frame(cx);
            }
            assert_eq!(
                cx.debug_bounds("github-top-line").is_some(),
                pinned,
                "{kind:?}: the row stands {place}"
            );
            let row = cx.debug_bounds("github-busy-row").expect("the busy row");
            let text = cx.debug_bounds("github-busy").expect("its label");
            let cancel = cx.debug_bounds("github-cancel").expect("its Cancel");
            let whole = cancel.size.width >= width - px(0.5)
                && cancel.left() >= row.left()
                && cancel.right() <= row.right()
                && cancel.top() >= row.top()
                && cancel.bottom() <= row.bottom()
                && text.right() <= cancel.left();
            if !whole {
                outside.push(format!(
                    "{kind:?} {place}: row {row:?}, label {text:?}, Cancel {cancel:?}"
                ));
            }
        }
    }
    assert!(
        outside.is_empty(),
        "Cancel ({width:?} wide) leaves its row at 18 pt in 461 × 490: {outside:#?}"
    );
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The height the confirmation decides before layout for the top line standing above the
/// body is the height the line is drawn: with a real reply's conversation open, at 13 and
/// 18 pt in 1,480 × 973, 700 × 680 and 461 × 490 windows, for a notice, for a notice with a
/// failure and refused input under it, for the busy row alone and under a notice, with a
/// request's own label and with one that wraps to more lines than any of them beside
/// Cancel, and for a failure too long for half the body, which scrolls under its cap. A
/// frame that changes what the line says keeps the region where it settles too, and from
/// the frame after it, the reveal the change asks for having landed, draws Send and Keep
/// editing whole in the body wherever the line leaves the body room for them beside the
/// region's two lines; a line that leaves too little, only at 18 pt in the 461 × 490
/// window, keeps the form alone. With no conversation open the busy row stands
/// among the content, and none of it is decided.
#[gpui::test]
async fn the_confirmation_decides_the_top_line_it_draws(cx: &mut TestAppContext) {
    const LONG_LABEL: &str = "Waiting for GitHub to answer the request this panel made for \
                              the conversation you opened…";
    type Line = (
        &'static str,
        Option<&'static str>,
        Option<String>,
        Option<DraftIssue>,
        bool,
        Option<&'static str>,
    );
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let lines: [Line; 7] = [
        ("a notice", Some(TOP_LINE_NOTICE), None, None, false, None),
        (
            "a notice, a failure and refused input",
            Some(TOP_LINE_NOTICE),
            Some(TOP_LINE_NOTICE.into()),
            Some(DraftIssue::Destination),
            false,
            None,
        ),
        ("the busy row", None, None, None, true, None),
        (
            "a busy row with a long label",
            None,
            None,
            None,
            true,
            Some(LONG_LABEL),
        ),
        (
            "a notice over the busy row",
            Some(TOP_LINE_NOTICE),
            None,
            None,
            true,
            None,
        ),
        (
            "a notice over a busy row with a long label",
            Some(TOP_LINE_NOTICE),
            None,
            None,
            true,
            Some(LONG_LABEL),
        ),
        (
            "a failure taller than its cap",
            None,
            Some(TOP_LINE_NOTICE.repeat(40)),
            None,
            false,
            None,
        ),
    ];
    for (interface, width, height) in [
        (13, 1480., 973.),
        (18, 1480., 973.),
        (13, 700., 680.),
        (18, 700., 680.),
        (13, 461., 490.),
        (18, 461., 490.),
    ] {
        open_reply_confirmation((&panel, &pull), None, (interface, width, height), cx);
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        confirm_frames();
        let rooms = cx.update(|window, cx| {
            (
                appearance::button_ring_room(cx),
                review::reveal_room(window, cx),
            )
        });
        let mut out_of_room_kinds = Vec::new();
        for (kind, notice, error, issue, busy, long) in lines.clone() {
            let at = format!("{kind} at {interface} pt in a {width} × {height} window");
            BUSY_LABEL_FOR_TEST.with(|label| label.set(long));
            cx.update(|_, cx| {
                panel.update(cx, |panel, cx| {
                    panel.notice = notice.map(Into::into);
                    panel.error = error;
                    panel.draft_issue = issue;
                    panel.pending = busy;
                    cx.notify();
                })
            });
            cx.executor().run_until_parked();
            for _ in 0..4 {
                crate::width_walk::frame(cx);
            }
            let frames = confirm_frames();
            // Whether the line, as decided before layout, leaves the body too little for the
            // region's two lines, its ring and the buttons, with the reveal's room at either
            // edge: at 18 pt in a 461 × 490 window they take 156 px and that room 40 px.
            // Read from the decided line and not from these frames, so a confirmation drawn
            // too tall for a line that leaves it room still fails below.
            let out_of_room = cx.update(|window, cx| {
                let conversations = &panel.read(cx).conversations;
                let form = conversations
                    .confirm_form
                    .borrow()
                    .clone()
                    .expect("the form decided");
                let line = conversations::pinned_line_height(form.top_text, form.busy_text, window);
                let floor = conversations.confirm_fit.get().line * 2.;
                form.chrome + floor
                    > window.pixel_snap(body_max_height(window) - line) - rooms.1 * 2.
            });
            if out_of_room {
                assert_eq!(
                    (interface, height),
                    (18, 490.),
                    "{at}: only the smallest window leaves the line too little room"
                );
                out_of_room_kinds.push(kind);
                assert_confirmation_form_settled(&at, &frames, rooms.0);
            } else {
                // A change of the top line above a focused region asks for the region's
                // reveal in that frame; the body moves in the next.
                assert_confirmation_settled_from(&at, &frames, rooms, 1);
            }
            let drawn = cx
                .debug_bounds("github-top-line")
                .unwrap_or_else(|| panic!("{at}: the top line stands above the body"))
                .size
                .height;
            let decided = cx.update(|window, cx| {
                let form = panel
                    .read(cx)
                    .conversations
                    .confirm_form
                    .borrow()
                    .clone()
                    .expect("the form decided");
                conversations::pinned_line_height(form.top_text, form.busy_text, window)
            });
            assert!(
                (drawn - decided).abs() <= px(0.5),
                "{at}: the top line is drawn {drawn:?} tall, not the {decided:?} decided"
            );
            // In the narrowest window the long label takes more lines than Cancel is
            // tall, so the row is as tall as the lines and not the Button.
            if long.is_some() && width == 461. {
                let mut height = |selector: &'static str| {
                    cx.debug_bounds(selector)
                        .unwrap_or_else(|| panic!("{at}: {selector} is drawn"))
                        .size
                        .height
                };
                assert!(
                    height("github-busy") > height("github-cancel"),
                    "{at}: the label stands taller than Cancel"
                );
            }
        }
        // The check above is decided for each line: the failure under its cap cannot leave
        // the room, and the busy row alone, two lines at this size, leaves it by 5 px.
        if (interface, height) == (18, 490.) {
            assert!(
                out_of_room_kinds.contains(&"a failure taller than its cap")
                    && !out_of_room_kinds.contains(&"the busy row"),
                "at 18 pt in a 461 × 490 window: {out_of_room_kinds:?} leave too little room"
            );
        }
        cx.update(|_, cx| {
            panel.update(cx, |panel, _| {
                panel.notice = None;
                panel.error = None;
                panel.draft_issue = None;
                panel.pending = false;
                panel.confirm = None;
                panel.conversations.active = None;
            })
        });
    }
    BUSY_LABEL_FOR_TEST.with(|label| label.set(None));
    open_confirmation(
        (&panel, &pull),
        confirmed_long_reply(60),
        (18, 461., 490.),
        cx,
    );
    cx.update(|_, cx| {
        panel.update(cx, |panel, cx| {
            panel.pending = true;
            cx.notify();
        })
    });
    cx.executor().run_until_parked();
    for _ in 0..4 {
        crate::width_walk::frame(cx);
    }
    assert!(
        cx.debug_bounds("github-busy-row").is_some()
            && cx.debug_bounds("github-top-line").is_none(),
        "with no conversation open the busy row stands among the content"
    );
    let busy_text = cx.update(|_, cx| {
        panel
            .read(cx)
            .conversations
            .confirm_form
            .borrow()
            .as_ref()
            .expect("the form decided")
            .busy_text
    });
    assert_eq!(
        busy_text,
        Pixels::ZERO,
        "among the content the row takes none of the room above the body"
    );
    cx.update(|_, cx| {
        panel.update(cx, |panel, _| {
            panel.pending = false;
            panel.confirm = None;
        })
    });
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The busy row Refresh PRs draws among the content leaves a focused confirmation in view:
/// with no conversation open and a comment's region focused, in a window whose body holds
/// the toolbar and the whole confirmation with less room below it than the row takes, at
/// 13 pt in a wide window and at 18 pt in a 461 px one, where the row wraps, Refresh PRs
/// pressed with the pointer keeps focus on the region and the confirmation open, the row
/// pushes Send past the body's foot in the frame that draws it, and the body brings Send and
/// Keep editing back whole. Nothing revealed it: focus and the body's size stayed the same.
/// The same holds for a confirmation already cut there, the foot through Send or through the
/// region with the buttons below it: some of it was in view, so the body is not one the
/// person scrolled away from it.
#[gpui::test]
async fn a_busy_row_among_the_content_reveals_the_focused_confirmation(cx: &mut TestAppContext) {
    use crate::copy_feedback::tests::click;
    // Where the body's foot falls on the confirmation before the row arrives.
    #[derive(Clone, Copy, Debug)]
    enum Foot {
        BelowIt,
        ThroughSend,
        ThroughRegion,
    }
    // The room left below the confirmation's reveal, less than any row takes.
    const SPARE: f32 = 6.;
    // Of the window's height, the part the dialog's cap follows
    // ([`appearance::dialog_max_height`]: it starts a tenth of the window down).
    const CAP_SLOPE: f32 = 0.9;
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    cx.update(|_, cx| cx.set_reduce_motion(true));
    let (region, scroll) = panel.read_with(cx, |panel, _| {
        (
            panel.conversations.confirm_focus.clone(),
            panel.review.body_scroll.clone(),
        )
    });
    for (interface, width, foot) in [
        (13, 1480., Foot::BelowIt),
        (13, 1480., Foot::ThroughSend),
        (13, 1480., Foot::ThroughRegion),
        (18, 461., Foot::BelowIt),
        (18, 461., Foot::ThroughSend),
        (18, 461., Foot::ThroughRegion),
    ] {
        let at = format!("{foot:?} at {interface} pt in a {width} px wide window");
        // Nothing on the top line, as opening a PR leaves it: the row arrives on its own.
        cx.update(|_, cx| panel.update(cx, |panel, _| panel.notice = None));
        // Tall enough that the body holds all it draws, for what the confirmation needs.
        let mut height = 2400.;
        open_confirmation(
            (&panel, &pull),
            confirmed_comment(),
            (interface, width, height),
            cx,
        );
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        assert!(
            panel.read_with(cx, |panel, _| panel.conversations.active.is_none()),
            "{at}: no conversation is open"
        );
        let body = cx.debug_bounds("github-panel").expect("the body");
        let reveal = cx.update(|window, cx| review::reveal_room(window, cx));
        let frame = *confirm_frames().last().expect("it draws");
        let send = cx.debug_bounds("github-confirm-send").expect("Send");
        let wanted = match foot {
            Foot::BelowIt => frame.actions.bottom() - body.top() + reveal + px(SPARE),
            Foot::ThroughSend => send.center().y - body.top(),
            Foot::ThroughRegion => frame.ring.center().y - body.top(),
        };
        // The body's cap at exactly that height.
        for _ in 0..2 {
            let room = cx.update(|window, _| body_max_height(window));
            height += f32::from(wanted - room) / CAP_SLOPE;
            cx.simulate_resize(size(px(width), px(height)));
            cx.executor().run_until_parked();
            crate::width_walk::frame(cx);
        }
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        // Scrolled back to the top, as a wheel would: the shorter body's reveal moved it.
        scroll.set_offset(point(scroll.offset().x, px(0.)));
        cx.executor().run_until_parked();
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        let body = cx.debug_bounds("github-panel").expect("the body");
        let refresh = cx.debug_bounds("github-refresh").expect("Refresh PRs");
        assert!(
            refresh.top() >= body.top() && refresh.bottom() <= body.bottom(),
            "{at}: Refresh PRs {refresh:?} lies in the body {body:?} to press"
        );
        let frame = *confirm_frames().last().expect("it draws");
        let send = cx.debug_bounds("github-confirm-send").expect("Send");
        let cut =
            |part: Bounds<Pixels>| part.top() < body.bottom() && part.bottom() > body.bottom();
        let (actions, ring) = (frame.actions, frame.ring);
        let starts = match foot {
            Foot::BelowIt => actions.bottom() <= body.bottom(),
            Foot::ThroughSend => cut(send),
            Foot::ThroughRegion => cut(ring) && actions.top() >= body.bottom(),
        };
        assert!(
            starts,
            "{at}: the body {body:?} starts so, over the region {ring:?}, Send {send:?} and \
             the buttons {actions:?}"
        );

        let held = app.update(cx, |app, _| app.operations.hold());
        click(cx, "github-refresh");
        cx.executor().run_until_parked();
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        assert!(
            panel.read_with(cx, |panel, _| panel.pending && panel.confirm.is_some()),
            "{at}: Refresh PRs is running and the confirmation stays open"
        );
        assert!(
            cx.debug_bounds("github-busy-row").is_some()
                && cx.debug_bounds("github-top-line").is_none(),
            "{at}: the busy row stands among the content"
        );
        assert!(
            cx.update(|window, _| region.is_focused(window)),
            "{at}: the press leaves focus on the region"
        );
        let frames = confirm_frames();
        assert!(
            frames
                .iter()
                .any(|frame| frame.actions.bottom() > body.bottom() + px(0.5)),
            "{at}: the row pushes Send and Keep editing past the body's foot {:?}: {:?}",
            body.bottom(),
            frames.iter().map(|frame| frame.actions).collect::<Vec<_>>()
        );
        let body = cx.debug_bounds("github-panel").expect("the body");
        for shown in ["github-confirm-send", "github-edit-submission"] {
            let drawn = cx.debug_bounds(shown).expect(shown);
            assert!(
                drawn.top() >= body.top() - px(0.5) && drawn.bottom() <= body.bottom() + px(0.5),
                "{at}: {shown} {drawn:?} lies whole in the body {body:?} after the reveal, \
                 the body scrolled {:?}",
                scroll.offset().y
            );
        }

        drop(held);
        app.read_with(cx, |app, _| app.operations.drain());
        settle_panel(&app, cx).await;
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The busy row Refresh PRs draws among the content does not pull back a body the person
/// scrolled away from the confirmation: at 18 pt in a 461 × 490 window, with no conversation
/// open and a comment's region focused, the body wheeled up so the toolbar shows and the
/// confirmation lies below the body's foot, Refresh PRs pressed with the pointer leaves the
/// body where the wheel left it and the row and its Cancel, which that press asked for, in
/// view.
#[gpui::test]
async fn a_busy_row_among_the_content_keeps_a_body_scrolled_from_the_confirmation(
    cx: &mut TestAppContext,
) {
    use crate::copy_feedback::tests::click;
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    cx.update(|_, cx| {
        cx.set_reduce_motion(true);
        panel.update(cx, |panel, _| panel.notice = None);
    });
    let (region, scroll) = panel.read_with(cx, |panel, _| {
        (
            panel.conversations.confirm_focus.clone(),
            panel.review.body_scroll.clone(),
        )
    });
    open_confirmation((&panel, &pull), confirmed_comment(), (18, 461., 490.), cx);
    for _ in 0..4 {
        crate::width_walk::frame(cx);
    }
    // Scrolled up, as a wheel would, until Refresh PRs stands at the body's top.
    let body = cx.debug_bounds("github-panel").expect("the body");
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let refresh = cx.debug_bounds("github-refresh").expect("Refresh PRs");
    let offset = scroll.offset();
    scroll.set_offset(point(
        offset.x,
        (offset.y + body.top() + room - refresh.top()).clamp(-scroll.max_offset().y, px(0.)),
    ));
    cx.executor().run_until_parked();
    for _ in 0..4 {
        crate::width_walk::frame(cx);
    }
    let refresh = cx.debug_bounds("github-refresh").expect("Refresh PRs");
    assert!(
        refresh.top() >= body.top() && refresh.bottom() <= body.bottom(),
        "Refresh PRs {refresh:?} lies in the body {body:?} to press"
    );
    let ring = confirm_frames().last().expect("it draws").ring;
    assert!(
        ring.top() >= body.bottom(),
        "the confirmation {ring:?} lies below the body {body:?}"
    );
    let wheeled = scroll.offset();

    let held = app.update(cx, |app, _| app.operations.hold());
    click(cx, "github-refresh");
    cx.executor().run_until_parked();
    for _ in 0..4 {
        crate::width_walk::frame(cx);
    }
    assert!(
        panel.read_with(cx, |panel, _| panel.pending && panel.confirm.is_some()),
        "Refresh PRs is running and the confirmation stays open"
    );
    assert!(
        cx.debug_bounds("github-busy-row").is_some()
            && cx.debug_bounds("github-top-line").is_none(),
        "the busy row stands among the content"
    );
    assert!(
        cx.update(|window, _| region.is_focused(window)),
        "the press leaves focus on the region"
    );
    assert_eq!(
        scroll.offset(),
        wheeled,
        "the body stays where the wheel left it"
    );
    for shown in ["github-busy-row", "github-cancel"] {
        let drawn = cx.debug_bounds(shown).expect(shown);
        assert!(
            drawn.top() >= body.top() && drawn.bottom() <= body.bottom(),
            "{shown} {drawn:?} lies whole in the body {body:?}"
        );
    }

    drop(held);
    app.read_with(cx, |app, _| app.operations.drain());
    settle_panel(&app, cx).await;
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// A change of the top line's height above the body does not pull back a body the person
/// wheeled away from the confirmation: with a real reply's region focused and its
/// conversation open, the body wheeled to its top so the confirmation lies below its foot,
/// a notice on the top line that grows onto more lines leaves the content where it was
/// drawn, the confirmation still below the body, and resizes that wrap the notice again
/// leave the confirmation out of view too: at 13 pt in a 1,480 × 490 window narrowed to
/// 900, and at 18 pt in a 461 × 490 window widened to 700 and narrowed back. Asked for with no look at where the body had been wheeled, the focused region's reveal
/// brought it back, as the line among the content once did.
#[gpui::test]
async fn a_pinned_top_line_keeps_a_body_wheeled_from_the_confirmation(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    cx.update(|_, cx| cx.set_reduce_motion(true));
    let (region, scroll) = panel.read_with(cx, |panel, _| {
        (
            panel.conversations.confirm_focus.clone(),
            panel.review.body_scroll.clone(),
        )
    });
    let settle = |cx: &mut VisualTestContext| {
        cx.executor().run_until_parked();
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
        confirm_frames()
            .last()
            .expect("the confirmation draws")
            .ring
    };
    let line = |cx: &mut VisualTestContext| {
        cx.debug_bounds("github-top-line")
            .expect("the top line stands above the body")
            .size
            .height
    };
    // The notice grows to two lines at 13 pt in 1,480 px and to four at 18 pt in 461 px,
    // under the line's cap of half the body, so each resize wraps it onto other lines.
    let doubled = format!("{TOP_LINE_NOTICE} {TOP_LINE_NOTICE}");
    let cases: [(u8, f32, &[f32], &str); 2] = [
        (13, 1480., &[900.], &doubled),
        (18, 461., &[700., 461.], TOP_LINE_NOTICE),
    ];
    for (interface, width, resizes, grown) in cases {
        let at = format!("{interface} pt, {width} × 490");
        open_reply_confirmation(
            (&panel, &pull),
            Some("Check the reply."),
            (interface, width, 490.),
            cx,
        );
        settle(cx);
        assert!(
            cx.update(|window, _| region.is_focused(window)),
            "{at}: the region holds focus"
        );
        // The wheel, over the body's top corner, clear of the conversation list, takes the
        // body to its top.
        let body = cx.debug_bounds("github-panel").expect("the body");
        cx.simulate_event(ScrollEvent {
            position: body.origin + point(px(2.), px(2.)),
            delta: ScrollDelta::Pixels(point(px(0.), -scroll.offset().y + px(100.))),
            modifiers: Modifiers::default(),
            touch_phase: TouchPhase::Moved,
            source: Default::default(),
        });
        let wheeled = settle(cx);
        assert_eq!(
            scroll.offset().y,
            px(0.),
            "{at}: the wheel takes the body to its top"
        );
        let body = cx.debug_bounds("github-panel").expect("the body");
        assert!(
            wheeled.top() >= body.bottom(),
            "{at}: the confirmation {wheeled:?} lies below the body {body:?}"
        );

        // A notice that grows onto more lines.
        let before = line(cx);
        cx.update(|_, cx| {
            panel.update(cx, |panel, cx| {
                panel.notice = Some(grown.into());
                cx.notify();
            })
        });
        let grown = settle(cx);
        let after = line(cx);
        assert!(
            after > before + px(10.),
            "{at}: the notice grows onto more lines: {before:?}, then {after:?}"
        );
        assert!(
            cx.update(|window, _| region.is_focused(window)),
            "{at}: the region keeps focus"
        );
        let body = cx.debug_bounds("github-panel").expect("the body");
        assert!(
            grown.top() >= body.bottom(),
            "{at}: a growing notice leaves the confirmation {grown:?} below the body {body:?}"
        );
        assert!(
            (grown.top() - wheeled.top()).abs() <= px(0.5),
            "{at}: the content stays where it was drawn: the confirmation at {:?}, then {:?}",
            wheeled.top(),
            grown.top()
        );

        // Resizes that wrap it onto other lines again.
        let mut heights = vec![after];
        for &to in resizes {
            cx.simulate_resize(size(px(to), px(490.)));
            let resized = settle(cx);
            heights.push(line(cx));
            let body = cx.debug_bounds("github-panel").expect("the body");
            assert!(
                resized.top() >= body.bottom(),
                "{at}: a resize to {to} px that wraps the line leaves the confirmation \
                 {resized:?} below the body {body:?}"
            );
        }
        assert!(
            heights
                .windows(2)
                .all(|pair| (pair[1] - pair[0]).abs() > px(10.)),
            "{at}: each resize wraps the notice onto other lines: {heights:?}"
        );
        cx.update(|_, cx| {
            panel.update(cx, |panel, _| {
                panel.confirm = None;
                panel.notice = None;
            })
        });
        settle_frames(cx);
    }
}

/// A change of the top line's height above a body nobody wheeled shows the focused region
/// whole again: with a 20-line reply's region focused, holding all of its text, and its
/// conversation open, at 13 pt in a 1,480 × 973 window, where the body's reveal leaves the
/// confirmation at its foot and room above the region's ring, a notice on the top line that
/// grows by more than that room ends, once the frames settle, with the ring whole in the
/// body's view, and Send and Keep editing with it. The line's shift of the body's scroll
/// keeps the content where it was drawn as the body's top moves down past the ring, and the
/// reveal the changed line asks for shows the region again; without it the ring's top stayed
/// under the body's new top.
#[gpui::test]
async fn a_growing_top_line_shows_the_focused_region_whole_again(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    cx.update(|_, cx| cx.set_reduce_motion(true));
    let (region, held) = panel.read_with(cx, |panel, _| {
        (
            panel.conversations.confirm_focus.clone(),
            panel.conversations.confirm_scroll.clone(),
        )
    });
    let line = |cx: &mut VisualTestContext| {
        cx.debug_bounds("github-top-line")
            .expect("the top line stands above the body")
            .size
            .height
    };
    let reply = (1..=20)
        .map(|line| format!("Line {line} of a reply."))
        .collect::<Vec<_>>()
        .join("\n");
    open_reply_confirmation_saying(
        (&panel, &pull),
        reply,
        Some("Check the reply."),
        (13, 1480., 973.),
        cx,
    );
    settle_frames(cx);
    assert!(
        cx.update(|window, _| region.is_focused(window)),
        "the region holds focus"
    );
    assert_eq!(
        held.max_offset().y,
        px(0.),
        "the region holds all of the reply"
    );
    let opened = *confirm_frames().last().expect("the confirmation draws");
    let room = opened.ring.top() - opened.body.top();
    assert!(
        opened.actions.bottom() <= opened.body.bottom() && room > px(0.),
        "the confirmation {:?} stands whole in the body {:?}",
        opened.ring,
        opened.body
    );
    let before = line(cx);
    cx.update(|_, cx| {
        panel.update(cx, |panel, cx| {
            panel.notice = Some([TOP_LINE_NOTICE; 10].join(" "));
            cx.notify();
        })
    });
    settle_frames(cx);
    let after = line(cx);
    assert!(
        after - before > room + px(10.),
        "the notice grows by more than the {room:?} above the ring: {before:?}, then {after:?}"
    );
    assert!(
        cx.update(|window, _| region.is_focused(window)),
        "the region keeps focus"
    );
    let settled = *confirm_frames().last().expect("the confirmation draws");
    assert!(
        settled.ring.top() >= settled.body.top() - px(0.5),
        "the region's ring {:?} stands whole below the body's top {:?}",
        settled.ring,
        settled.body
    );
    assert!(
        settled.actions.bottom() <= settled.body.bottom() + px(0.5),
        "Send and Keep editing {:?} stand whole in the body {:?}",
        settled.actions,
        settled.body
    );
    cx.update(|_, cx| {
        panel.update(cx, |panel, _| {
            panel.confirm = None;
            panel.notice = None;
        })
    });
    settle_frames(cx);
}

/// Runs what is waiting and draws four frames, as a reveal asked for in one frame moves the
/// body in the next.
fn settle_frames(cx: &mut VisualTestContext) {
    cx.executor().run_until_parked();
    for _ in 0..4 {
        crate::width_walk::frame(cx);
    }
}

/// The confirmation lays out the form it decides before layout
/// ([`conversations::ConfirmForm`]): at 13 and 18 pt in 1,480 × 973, 700 × 680 and 461 ×
/// 490 windows, for a comment and a long reply, with Send reading the offline fixture's
/// label and GitHub's, the region and the guidance are laid out at the width the form was
/// decided at, the guidance as tall as the form's, and the confirmation draws besides its
/// region and the guidance what the form leaves for the room around the region and Send and
/// Keep editing, which stand on one row in some of them and on two in others.
#[gpui::test]
async fn the_confirmation_lays_out_the_form_it_decides(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let confirmations: [Confirming; 2] = [
        ("a comment", confirmed_comment),
        ("a long reply", || confirmed_long_reply(40)),
    ];
    let mut rows = std::collections::BTreeSet::new();
    for fixture in [true, false] {
        cx.update(|_, cx| panel.update(cx, |panel, _| panel.review.fixture = fixture));
        for (interface, width, height) in [
            (13, 1480., 973.),
            (18, 1480., 973.),
            (13, 700., 680.),
            (18, 700., 680.),
            (13, 461., 490.),
            (18, 461., 490.),
        ] {
            for (kind, confirmation) in confirmations {
                let at = format!(
                    "{kind} at {interface} pt in a {width} × {height} window, Send for {}",
                    if fixture { "the fixture" } else { "GitHub" }
                );
                open_confirmation(
                    (&panel, &pull),
                    confirmation(),
                    (interface, width, height),
                    cx,
                );
                for _ in 0..4 {
                    crate::width_walk::frame(cx);
                }
                let settled = *confirm_frames().last().expect("the confirmation draws");
                let form = panel
                    .read_with(cx, |panel, _| {
                        panel.conversations.confirm_form.borrow().clone()
                    })
                    .expect("the form decided");
                let mut place = |selector: &'static str| cx.debug_bounds(selector).expect(selector);
                let (guidance, region, send, keep) = (
                    place("github-confirm-guidance"),
                    place("github-confirm-region"),
                    place("github-confirm-send"),
                    place("github-edit-submission"),
                );
                for (name, laid) in [("guidance", guidance), ("region", region)] {
                    assert!(
                        (laid.size.width - form.width()).abs() <= px(0.01),
                        "{at}: the {name} {laid:?} is laid out at the {:?} its form was \
                         decided at",
                        form.width()
                    );
                }
                assert!(
                    (guidance.size.height - form.guidance).abs() <= px(0.5),
                    "{at}: the guidance {guidance:?} is as tall as its form's {:?}",
                    form.guidance
                );
                assert!(
                    (settled.chrome - form.chrome).abs() <= px(0.5),
                    "{at}: the confirmation draws {:?} besides its region and guidance, the \
                     {:?} its form leaves (Send {send:?}, Keep editing {keep:?})",
                    settled.chrome,
                    form.chrome
                );
                rows.insert(keep.top() > send.top() + px(0.5));
            }
        }
    }
    assert_eq!(
        rows.len(),
        2,
        "Send and Keep editing stand on one row in some windows and on two in others"
    );
    cx.update(|_, cx| {
        panel.update(cx, |panel, _| {
            panel.review.fixture = true;
            panel.confirm = None;
        })
    });
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The confirmation decides its form again only when what it was decided for changes
/// ([`conversations::ConfirmForm`]): with a long reply's region focused at 13 pt in a
/// 1,480 × 973 window, more frames, the keys that scroll the region and a window made only
/// shorter decide nothing; a narrower window, a larger text size and Send's other label each
/// decide it once; and a frame that keeps the form allocates nothing for it.
#[gpui::test]
async fn the_confirmation_decides_its_form_only_when_its_width_size_or_text_changes(
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let decided = || conversations::CONFIRM_FORMS_DECIDED.with(std::cell::Cell::get);
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    open_confirmation(
        (&panel, &pull),
        confirmed_long_reply(60),
        (13, 1480., 973.),
        cx,
    );
    frames(cx);
    let opened = decided();
    assert!(opened > 0, "the confirmation decides its form as it opens");
    frames(cx);
    cx.simulate_keystrokes("down");
    frames(cx);
    cx.simulate_keystrokes("pagedown");
    frames(cx);
    assert_eq!(
        decided(),
        opened,
        "frames and the region's keys decide nothing"
    );
    cx.simulate_resize(size(px(1480.), px(700.)));
    cx.executor().run_until_parked();
    frames(cx);
    assert_eq!(
        decided(),
        opened,
        "a window made only shorter decides nothing"
    );
    cx.simulate_resize(size(px(461.), px(700.)));
    cx.executor().run_until_parked();
    frames(cx);
    assert_eq!(decided(), opened + 1, "a narrower window decides it once");
    crate::focus_ring::sweep::interface_size(cx, 18);
    frames(cx);
    assert_eq!(decided(), opened + 2, "a larger text size decides it once");
    cx.update(|_, cx| {
        panel.update(cx, |panel, cx| {
            panel.review.fixture = false;
            cx.notify();
        })
    });
    cx.executor().run_until_parked();
    frames(cx);
    assert_eq!(decided(), opened + 3, "Send's other label decides it once");
    let allocated = cx.update(|window, cx| {
        let style = window.text_style();
        let panel = panel.read(cx);
        let before = crate::test_support::allocations();
        let _ =
            panel
                .conversations
                .confirm_form(&style, "Send to GitHub", [None; 3], None, window, cx);
        crate::test_support::allocations() - before
    });
    assert_eq!(
        allocated, 0,
        "a frame that keeps the form allocates nothing for it"
    );
    assert_eq!(decided(), opened + 3, "nor decides it again");
    cx.update(|_, cx| {
        panel.update(cx, |panel, _| {
            panel.review.fixture = true;
            panel.confirm = None;
        })
    });
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The confirmation's region cues what lies past its edges with the shared scroll cue's
/// edge fades in the dialog's surface (`tags::ScrollCue`): at 18 pt in a 461 × 490 window a
/// long reply's region, opened at its top, fades its foot and not its top, and after End
/// its top and not its foot; at 13 pt in a 1,480 × 973 window a comment's region, which
/// holds all of it, fades neither. No fade reaches the ring the region draws on the room
/// around it. Cut at its foot with no cue, the region gave no sign that the guidance and
/// the text Send sends lay below.
#[gpui::test]
async fn the_confirmation_region_fades_the_edges_more_lies_past(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let stroke = appearance::BUTTON_FOCUS_RING.width;
    let fades = |cx: &mut VisualTestContext, at: &str, expected: (bool, bool)| {
        let region = cx
            .debug_bounds("github-confirm-region")
            .expect("the region");
        let (top, bottom) = crate::tags::tests::painted_fades(cx, region);
        assert_eq!(
            (top.is_some(), bottom.is_some()),
            expected,
            "{at}: the fades at the region's top and foot: {top:?}, {bottom:?}"
        );
        // The ring's stroke lies along the edge of the room around the region.
        let ring = cx
            .debug_bounds("github-confirm-ring")
            .expect("the ring's room")
            .dilate(-stroke);
        for band in [
            top.map(|height| Bounds::new(region.origin, size(region.size.width, height))),
            bottom.map(|height| {
                Bounds::new(
                    point(region.left(), region.bottom() - height),
                    size(region.size.width, height),
                )
            }),
        ]
        .into_iter()
        .flatten()
        {
            assert!(
                band.top() >= ring.top()
                    && band.bottom() <= ring.bottom()
                    && band.left() >= ring.left()
                    && band.right() <= ring.right(),
                "{at}: the fade {band:?} lies clear of the ring inside {ring:?}"
            );
        }
    };
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    let at = "a long reply at 18 pt in a 461 × 490 window";
    open_confirmation(
        (&panel, &pull),
        confirmed_long_reply(60),
        (18, 461., 490.),
        cx,
    );
    frames(cx);
    fades(cx, &format!("{at}, at rest"), (false, true));
    cx.simulate_keystrokes("end");
    frames(cx);
    fades(cx, &format!("{at}, after End"), (true, false));
    open_confirmation((&panel, &pull), confirmed_comment(), (13, 1480., 973.), cx);
    frames(cx);
    fades(
        cx,
        "a comment at 13 pt in a 1,480 × 973 window",
        (false, false),
    );
    cx.update(|_, cx| panel.update(cx, |panel, _| panel.confirm = None));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Reopening hands focus to the shown section's first stop, drawn whole, where the control
/// that held it as the panel closed lies out of the reopened body's view: Files' Source
/// editor, focused by Tab and whole in view beside the changed-file list at 13 pt in a
/// 1,480 × 973 window as Escape closes the panel, lies below the body's fold under that list
/// once the window is 461 × 490 and the text 18 pt, so the header's Pull requests reopens
/// the panel onto the list, whole in view, and not onto the editor out of view.
#[gpui::test]
async fn reopening_past_a_source_editor_out_of_view_focuses_the_file_list(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    show_surface(
        (&app, &panel, &pull, &files),
        Surface::Source,
        (13, 1480., 973.),
        cx,
    )
    .await;
    let (list, source) = cx.read(|cx| {
        let panel = panel.read(cx);
        let source = panel.review.source.as_ref().expect("Source's editor");
        (
            panel.review.file_focus.clone(),
            source.read(cx).focus_handle(cx),
        )
    });
    let focused = |cx: &mut VisualTestContext, focus: &FocusHandle| {
        cx.update(|window, _| focus.is_focused(window))
    };
    for _ in 0..12 {
        if focused(cx, &source) {
            break;
        }
        cx.simulate_keystrokes("tab");
        frames(cx);
    }
    assert!(focused(cx, &source), "Tab reaches Source's editor");
    let body = cx.debug_bounds("github-panel").expect("the body");
    let editor = cx.debug_bounds("github-source-patch").expect("Source");
    assert!(
        editor.top() >= body.top() && editor.bottom() <= body.bottom(),
        "Source {editor:?} is whole in the body {body:?} as the panel closes"
    );
    escape(cx);
    crate::focus_ring::sweep::interface_size(cx, 18);
    cx.simulate_resize(size(px(461.), px(490.)));
    crate::copy_feedback::tests::click(cx, "pull-requests");
    settle_panel(&app, cx).await;
    assert!(
        cx.update(|window, cx| window.has_active_dialog(cx)),
        "the header's Pull requests reopens the panel"
    );
    frames(cx);
    let body = cx.debug_bounds("github-panel").expect("the body");
    assert!(
        focused(cx, &list),
        "the changed-file list, Files' first stop, takes focus"
    );
    let editor = cx.debug_bounds("github-source-patch").expect("Source");
    assert!(
        editor.top() >= body.bottom() || editor.bottom() <= body.top(),
        "Source {editor:?} lies out of the reopened body {body:?}"
    );
    let shown = cx.debug_bounds("github-file-focus").expect("the list");
    assert!(
        shown.top() - room >= body.top() - px(0.5)
            && shown.bottom() + room <= body.bottom() + px(0.5),
        "the list {shown:?} is whole in the body {body:?}"
    );
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Whether the last frame stood the file beside the changed-file list rather than below it.
fn files_beside(cx: &mut VisualTestContext) -> bool {
    let list = cx.debug_bounds("github-file-focus").expect("the file list");
    let column = cx.debug_bounds("github-file-column").expect("the file");
    column.left() > list.right()
}

/// The narrowest window 800 px tall, to `step`, in which Files stands the file beside the
/// list, between 400 px, where it stands below, and 1,480 px.
fn narrowest_beside(cx: &mut VisualTestContext, step: f32) -> f32 {
    let beside_at = |cx: &mut VisualTestContext, width: f32| {
        cx.simulate_resize(size(px(width), px(800.)));
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        files_beside(cx)
    };
    let (mut below, mut beside) = (400., 1480.);
    assert!(
        !beside_at(cx, below) && beside_at(cx, beside),
        "the file stands below the list in a 400 px window and beside it in a 1,480 px one"
    );
    while beside - below > step {
        let middle = below + ((beside - below) / step / 2.).floor() * step;
        if beside_at(cx, middle) {
            beside = middle;
        } else {
            below = middle;
        }
    }
    beside
}

/// Where the last frame stood the file beside the list, its mode row, Changes, Source,
/// Threads and the comment Button, lies on one line inside the file's column.
fn assert_mode_row_on_one_line(cx: &mut VisualTestContext, at: &str) {
    if !files_beside(cx) {
        return;
    }
    let column = cx.debug_bounds("github-file-column").expect("the file");
    let first = cx.debug_bounds("github-file-mode-0").expect("Changes");
    let last = cx
        .debug_bounds("github-inline-start")
        .expect("the comment Button");
    assert!(
        (last.top() - first.top()).abs() <= px(0.5) && last.right() <= column.right() + px(0.5),
        "{at}: beside the list, the mode row from {first:?} to {last:?} keeps one line in \
         the file's column {column:?}"
    );
}

/// Files stands the file beside the list where its mode row fits there on one line with
/// the label its last Button reads now, at 13 pt (`review::mode_row_width`): in the window
/// a pixel too narrow for Comment on selection beside the list, an open comment, whose
/// Button reads the narrower Continue comment, stands the file beside the list, its row on
/// one line, and as the comment closes the file stands below the list again, each in the
/// frames the change draws. The row's width measured with one label and kept for the other
/// would keep the other's layout.
#[gpui::test]
async fn files_mode_row_follows_its_last_label(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    show_first_file(&app, &panel, &pull, cx).await;
    let beside = narrowest_beside(cx, 1.);
    let wide = cx
        .debug_bounds("github-inline-start")
        .expect("Comment on selection");
    let width = beside - 1.;
    cx.simulate_resize(size(px(width), px(800.)));
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
    assert!(!files_beside(cx), "the file below the list at {width} px");
    let comment = cx.read(|cx| {
        let file = &panel.read(cx).review.files[0];
        let row = file
            .rows
            .iter()
            .position(|row| row.kind == b'+')
            .expect("an added line");
        file.selection(row, row).expect("an inline position")
    });
    for open in [true, false, true, false] {
        let label = if open {
            "Continue comment"
        } else {
            "Comment on selection"
        };
        let at = format!("{label} in a {width} px window");
        let comment = comment.clone();
        cx.update(|_, cx| {
            panel.update(cx, |panel, cx| {
                panel.review.composing = open.then_some(comment);
                cx.notify();
            })
        });
        assert_eq!(
            files_beside(cx),
            open,
            "{at}: the file beside the list only with the narrower label"
        );
        for _ in 0..2 {
            crate::width_walk::frame(cx);
        }
        assert_eq!(files_beside(cx), open, "{at}, two frames on");
        assert_mode_row_on_one_line(cx, &at);
        let button = cx.debug_bounds("github-inline-start").expect(label);
        assert!(
            !open || button.size.width < wide.size.width - px(1.),
            "{at}: the Button {button:?} is narrower than Comment on selection {wide:?} by \
             more than the pixel"
        );
    }
}

/// Files measures its mode row again as the display's scale changes between frames, at
/// 13 pt (`review::mode_row_width`): in the narrowest window at 2x in which the file stands
/// beside the list, to an eighth of a pixel, a scale at which the row's Buttons, each laid
/// out on whole device pixels, take more room than the file's column leaves stands the
/// file below the list, wherever the file stands beside the list its row keeps one line in
/// the column, and back at 2x it stands beside the list again. The row's width measured at
/// another scale and kept stood the file beside the list with its row wrapped.
#[gpui::test]
async fn files_mode_row_follows_the_display_scale(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    show_first_file(&app, &panel, &pull, cx).await;
    let width = narrowest_beside(cx, 0.125);
    cx.simulate_resize(size(px(width), px(800.)));
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
    let mut below = Vec::new();
    for scale in [1., 1.25, 1.5, 1.75] {
        cx.update(|window, _| window.set_scale_factor(scale));
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        assert_mode_row_on_one_line(cx, &format!("at {scale}x in a {width} px window"));
        if !files_beside(cx) {
            below.push(scale);
        }
        cx.update(|window, _| window.set_scale_factor(2.));
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        let at = format!("back at 2x from {scale}x in a {width} px window");
        assert!(files_beside(cx), "{at}: the file beside the list");
        assert_mode_row_on_one_line(cx, &at);
    }
    assert!(
        !below.is_empty(),
        "a scale's device pixels widen the row past the column at {width} px"
    );
}

/// Shift+Tab back onto a conversation's last action reveals it again in the conversation
/// list, at 13 pt in a 470 × 490 window, after Tab took focus on to the conversations'
/// pager and the list scrolled back to its top: the list kept the action as the focus it
/// had shown, so the reveal saw no change of focus, and the action stayed out of view with
/// its ring undrawn (FU18-F's sweep, Overview's stop 12).
#[gpui::test]
async fn a_conversation_action_focused_again_is_revealed_again(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    show_overview(&panel, &pull, (13, 470., 490.), cx);
    let contexts = |cx: &mut VisualTestContext| {
        cx.update(|window, _| {
            window
                .context_stack()
                .iter()
                .map(|context| format!("{context:?}"))
                .collect::<Vec<_>>()
                .join(" < ")
        })
    };
    let list = cx.read(|cx| panel.read(cx).conversations.list_scroll.clone());
    let mut last = String::new();
    for _ in 0..20 {
        cx.simulate_keystrokes("tab");
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        let now = contexts(cx);
        if now.contains("conversations-pager") {
            break;
        }
        last = now;
    }
    assert!(
        last.contains("GitTurtleGithubConversation=2") && list.offset().y < px(0.),
        "Tab reached the last conversation's last action, the list scrolled to it: {last}"
    );
    list.set_offset(point(px(0.), px(0.)));
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
    cx.simulate_keystrokes("shift-tab");
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
    assert_eq!(contexts(cx), last, "Shift+Tab returns to the action");
    let viewport = cx.debug_bounds("github-threads").expect("the list");
    let actions = cx
        .debug_bounds("github-thread-actions-2")
        .expect("the actions");
    assert!(
        actions.top() >= viewport.top() && actions.bottom() <= viewport.bottom(),
        "the list shows the actions {actions:?} again in {viewport:?}"
    );
}

/// Shift+Tab from Back to repository, below the body, back onto the body's last control
/// reveals it again with its ring, at 13 pt in a 470 × 490 window, after the wheel scrolled
/// the body back to its top: the body kept the control as the focus it had shown, so the
/// reveal saw no change of focus, and the control stayed below the body's foot with its
/// ring undrawn (coordinator's decision, 2026-11-05: a control focus returns to is revealed
/// again wherever its list has scrolled since).
#[gpui::test]
async fn the_bodys_last_control_focused_again_is_revealed_again(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    show_overview(&panel, &pull, (13, 470., 490.), cx);
    let scroll = cx.read(|cx| panel.read(cx).review.body_scroll.clone());
    let stop = |cx: &mut VisualTestContext| {
        cx.update(|window, cx| {
            let inside = window
                .context_stack()
                .iter()
                .any(|context| context.contains(review::BODY));
            (window.focused(cx), inside)
        })
    };
    // The Button rings the last frame drew whole inside the body.
    let rings = |cx: &mut VisualTestContext| {
        let body = cx.debug_bounds("github-panel").expect("the body");
        let (ring, color, scale) = cx.update(|window, cx| {
            let theme = gpui_kit::component::Theme::global(cx);
            let ring = theme.button_focus_ring;
            (ring, theme.ring.alpha(ring.opacity), window.scale_factor())
        });
        quads(cx)
            .into_iter()
            .filter(|(bounds, quad)| {
                quad.background.is_transparent()
                    && quad.border_color == color
                    && quad.border_widths.top.as_f32() == ring.width.as_f32() * scale
                    && bounds.top() >= body.top()
                    && bounds.bottom() <= body.bottom()
            })
            .map(|(bounds, _)| bounds)
            .collect::<Vec<_>>()
    };
    let mut last = None;
    for _ in 0..30 {
        cx.simulate_keystrokes("tab");
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        let (focused, inside) = stop(cx);
        if !inside && last.is_some() {
            break;
        }
        last = inside.then(|| (focused, scroll.offset().y, rings(cx)));
    }
    let Some((control, shown, ringed)) = last else {
        panic!("Tab reached a control in the body before one below it");
    };
    assert!(
        shown < px(0.) && !ringed.is_empty(),
        "Tab scrolled the body {shown:?} onto its last control, its ring drawn {ringed:?}"
    );
    assert!(
        rings(cx).is_empty(),
        "Tab moved on to Back to repository, below the body"
    );
    // The wheel, over the body's top corner, clear of the conversation list, takes the body
    // back to its top, the control out of view.
    let body = cx.debug_bounds("github-panel").expect("the body");
    cx.simulate_event(ScrollEvent {
        position: body.origin + point(px(2.), px(2.)),
        delta: ScrollDelta::Pixels(point(px(0.), -shown + px(100.))),
        modifiers: Modifiers::default(),
        touch_phase: TouchPhase::Moved,
        source: Default::default(),
    });
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
    assert_eq!(
        scroll.offset().y,
        px(0.),
        "the wheel scrolls the body to its top"
    );
    cx.simulate_keystrokes("shift-tab");
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
    assert!(
        stop(cx) == (control, true),
        "Shift+Tab returns to the control"
    );
    let again = rings(cx);
    assert!(
        scroll.offset().y < px(0.) && !again.is_empty(),
        "the body {:?} shows the control again with its ring {again:?}",
        scroll.offset().y
    );
}

/// What Files' lists and clips hide is no line of the body, at 13 and 18 pt in a 461 × 490
/// window: the changed-file list, holding twelve files, scrolled half a row inside itself
/// and standing past the body's top edge, and Source's text, standing past the body's
/// foot, each tell the body their viewport ([`review::clipped`]), so the row the list's own
/// edge cuts, past that edge, and the part of a row under Source's clip, inside the
/// editor's bottom padding, are none of its lines: no line of the body crosses either
/// edge of either. Past the body's edge, where the clip around them is the body's, the
/// body once took such a row for a line, and a reveal could refuse a stop that cut nothing
/// a person sees (FU18-F's review).
#[gpui::test]
async fn rows_files_hides_past_its_edges_are_no_lines_of_the_body(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let listed = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    // The fixture's files, and copies of them under other names, so the list scrolls.
    let files: Vec<_> = (0..12)
        .map(|index| {
            let mut file = listed[index % listed.len()].clone();
            if index >= listed.len() {
                file.filename = format!("copy-{index}/{}", file.filename);
            }
            file
        })
        .collect();
    let scroll = cx.read(|cx| panel.read(cx).review.body_scroll.clone());
    let slack = px(0.5);
    // Scrolls the body so `edge`, a place in the frame, lies at `at`.
    let place = |edge: Pixels, at: Pixels, cx: &mut VisualTestContext| {
        let offset = (scroll.offset().y + at - edge).clamp(-scroll.max_offset().y, px(0.));
        scroll.set_offset(point(px(0.), offset));
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    // The lines of the body that cross the top or bottom edge of the clip `name` draws and
    // that `ours` takes for one of its rows, the text beside the clip apart.
    let crossing = |name: &'static str,
                    ours: &dyn Fn(&(Pixels, Pixels)) -> bool,
                    cx: &mut VisualTestContext| {
        let clip = cx.debug_bounds(name).expect("the clip");
        let lines = panel.read_with(cx, |panel, cx| panel.review.body_blocks.lines(cx));
        let crosses = |edge: Pixels, (top, bottom): &(Pixels, Pixels)| {
            *top < edge - slack && *bottom > edge + slack
        };
        lines
            .into_iter()
            .filter(|line| crosses(clip.top(), line) || crosses(clip.bottom(), line))
            .filter(|line| ours(line))
            .collect::<Vec<_>>()
    };
    for interface in [13, 18] {
        let at = format!("{interface} pt in 461 × 490");
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(461.), px(490.)));
        let (pull, files) = (pull.clone(), files.clone());
        cx.update(|window, cx| {
            panel.update(cx, |panel, cx| {
                panel.pull = Some(pull);
                panel.review.show_list = false;
                panel.review.section = Section::Files;
                panel.review.files = files;
                panel.review.selected_file = None;
                panel.select_review_file(0, window, cx);
            })
        });
        settle_panel(&app, cx).await;
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        // The list scrolled half a row inside itself, its top edge 10 px above the body's.
        let row = cx.debug_bounds("github-file-row-0").expect("a file row");
        cx.update(|_, cx| {
            let panel = panel.read(cx);
            let handle = panel.review.file_scroll.0.borrow();
            handle
                .base_handle
                .set_offset(point(px(0.), -row.size.height / 2.));
        });
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        let list = cx.debug_bounds("github-file-rows").expect("the list");
        let body = cx.debug_bounds("github-panel").expect("the body");
        place(list.top(), body.top() - px(10.), cx);
        let list = cx.debug_bounds("github-file-rows").expect("the list");
        let body = cx.debug_bounds("github-panel").expect("the body");
        let rows: Vec<Bounds<Pixels>> = indexed("github-file-row-", 12)
            .into_iter()
            .filter_map(|name| cx.debug_bounds(name))
            .collect();
        let cut = rows
            .iter()
            .any(|row| row.top() < list.top() - slack && row.bottom() > list.top() + slack);
        assert!(
            cut && list.top() < body.top() - slack && list.bottom() > body.top(),
            "{at}: the list {list:?} cuts a row at its top, past the body's {body:?}"
        );
        let a_row = |(top, bottom): &(Pixels, Pixels)| {
            rows.iter().any(|row| {
                (row.top() - *top).abs() < px(0.01) && (row.bottom() - *bottom).abs() < px(0.01)
            })
        };
        assert_eq!(
            crossing("github-file-rows", &a_row, cx),
            Vec::new(),
            "{at}: no line of the body crosses the file list's edges"
        );
        // Source's text, its clip's foot 10 px below the body's.
        cx.update(|window, cx| panel.update(cx, |panel, cx| panel.review_source(1, window, cx)));
        settle_panel(&app, cx).await;
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        let clip = cx
            .debug_bounds("github-source-text")
            .expect("Source's clip");
        let body = cx.debug_bounds("github-panel").expect("the body");
        place(clip.bottom(), body.bottom() + px(10.), cx);
        let clip = cx
            .debug_bounds("github-source-text")
            .expect("Source's clip");
        let body = cx.debug_bounds("github-panel").expect("the body");
        let (view, line) = cx.read(|cx| {
            let source = panel.read(cx).review.source.clone().expect("Source");
            let source = source.read(cx);
            (
                source.input_bounds(),
                source.line_height().expect("Source has painted"),
            )
        });
        assert!(
            clip.bottom() > body.bottom() + slack
                && clip.top() < body.bottom()
                && view.bottom() >= clip.bottom() - slack,
            "{at}: Source's clip {clip:?} stands past the body's foot {body:?}, the editor \
             {view:?} to its foot"
        );
        assert_eq!(
            crossing(
                "github-source-text",
                &|(top, bottom)| *top >= clip.top() - slack && *bottom - *top <= line + slack,
                cx
            ),
            Vec::new(),
            "{at}: no line of the body crosses Source's clip"
        );
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// A surface of the panel the reveal sweep walks ([`sweep_reveals`]) on the offline
/// fixture: the connection pane above the PR list, the PR list, a PR's Overview with its
/// Conversations pane, its Review, and Files in Changes, Source and Threads, the file's
/// Conversations pane.
#[derive(Clone, Copy, Debug, PartialEq)]
enum Surface {
    Connection,
    Pulls,
    Overview,
    Review,
    Changes,
    Source,
    Threads,
}

/// Every surface the reveal sweep walks.
const SURFACES: [Surface; 7] = [
    Surface::Connection,
    Surface::Pulls,
    Surface::Overview,
    Surface::Review,
    Surface::Changes,
    Surface::Source,
    Surface::Threads,
];

/// Surfaces the reveal sweep walks at one size, an interface size and a window's width and
/// height ([`sweep_reveals`]).
type Walk<'a> = ((u8, f32, f32), &'a [Surface]);

/// The keys the reveal sweep walks each surface with, in turn ([`sweep_reveals`]): Tab
/// through every stop, then Shift+Tab, which reveals each from the other side.
const BOTH_WAYS: [&str; 2] = ["tab", "shift-tab"];

/// What the reveal sweep found ([`sweep_reveals`]), each finding named by its surface,
/// size and stop.
#[derive(Default)]
struct Swept {
    /// Reveals that left a line cut at an edge of the body where a place clears every line
    /// with the focused control whole with its ring, and reveals that kept more than the
    /// focused part with its ring's room ([`over_wide`]).
    cuts: Vec<String>,
    /// Stops that show no whole ring (`focus_ring::sweep::walk_each`), but for a control
    /// too tall for the body with its ring's room, which shows the ring's top edge.
    rings: Vec<String>,
    /// Lines outside the lists inside the body that no stop of a surface's walks shows
    /// whole, and texts and Buttons part of which no stop shows at all.
    unseen: Vec<String>,
    /// How many stops the walks took, how many of them moved the body, and how many of
    /// those revealed a part too tall for the body, whose cuts the sweep leaves alone.
    stops: usize,
    moves: usize,
    tall: usize,
}

/// Shows `surface` on the offline fixture at `interface` pt in a `width` × `height`
/// window, with `files` listed in Files and the first selected, the body and the
/// conversation list at their tops and focus where the surface opens it.
async fn show_surface(
    (app, panel, pull, files): (
        &Entity<GitTurtle>,
        &Entity<Panel>,
        &PullRequest,
        &[crate::github::review::PullFile],
    ),
    surface: Surface,
    (interface, width, height): (u8, f32, f32),
    cx: &mut VisualTestContext,
) {
    crate::focus_ring::sweep::interface_size(cx, interface);
    cx.simulate_resize(size(px(width), px(height)));
    let (pull, files) = (pull.clone(), files.to_vec());
    cx.update(|window, cx| {
        panel.update(cx, |panel, cx| {
            let listed = matches!(surface, Surface::Connection | Surface::Pulls);
            panel.review.connection_open = surface == Surface::Connection;
            panel.pull = (!listed).then_some(pull);
            panel.review.show_list = listed;
            panel.review.section = match surface {
                Surface::Review => Section::Review,
                Surface::Changes | Surface::Source | Surface::Threads => Section::Files,
                _ => Section::Overview,
            };
            panel.review.files = files;
            panel.review.selected_file = None;
            panel.select_review_file(0, window, cx);
        })
    });
    settle_panel(app, cx).await;
    let mode = match surface {
        Surface::Source => 1,
        Surface::Threads => 2,
        _ => 0,
    };
    cx.update(|window, cx| {
        panel.update(cx, |panel, cx| {
            if mode > 0 {
                panel.review_source(mode, window, cx);
            }
            panel.review.body_scroll.set_offset(point(px(0.), px(0.)));
            panel
                .conversations
                .list_scroll
                .set_offset(point(px(0.), px(0.)));
            panel.focus_visible_section(window, cx);
            cx.notify();
        })
    });
    settle_panel(app, cx).await;
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
}

/// Walks each of `walks`' surfaces on the offline fixture at its size (an interface size
/// and a window's width and height), through every stop with each of `keys` in turn, Tab
/// and Shift+Tab ([`BOTH_WAYS`]) or one of them, each walk from the surface opened at the
/// body's top (`focus_ring::sweep::walk_each`), and returns what it found ([`Swept`]):
/// every stop's ring that is not whole; every reveal that left a line drawn in the frame
/// ([`frame_lines`]) cut at an edge of the body where a place the body's top edge can take
/// keeps the focused control whole with its ring and, drawn there, cuts no line
/// ([`needless_cut`]), but at the content's top, which a reveal keeps
/// ([`review::clear_of_lines`]); and every line outside the lists inside the body that no
/// stop of the surface's walks shows whole, with every text and Button outside them part
/// of which no stop shows at all.
async fn sweep_reveals(cx: &mut TestAppContext, walks: &[Walk<'_>], keys: &[&str]) -> Swept {
    use crate::native_accessibility::written;
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let scroll = cx.read(|cx| panel.read(cx).review.body_scroll.clone());
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let slack = px(0.5);
    let mut swept = Swept::default();
    for &((interface, width, height), surfaces) in walks {
        for &surface in surfaces {
            let at = format!("{surface:?} at {interface} pt in {width} × {height}");
            // Each line outside the lists by its place, and whether a stop showed it whole;
            // each text and Button outside them by its place and extent in the content; and
            // the extent of the content each stop showed.
            let mut lines: std::collections::BTreeMap<(i32, i32), (String, bool)> =
                Default::default();
            let mut boxes: std::collections::BTreeMap<(i32, i32), (String, Pixels, Pixels)> =
                Default::default();
            let mut views: Vec<(Pixels, Pixels)> = Vec::new();
            for &key in keys {
                show_surface(
                    (&app, &panel, &pull, &files),
                    surface,
                    (interface, width, height),
                    cx,
                )
                .await;
                let mut before = scroll.offset().y;
                let mut each =
                    |cx: &mut VisualTestContext,
                     stop: &str,
                     ring: &[crate::focus_ring::PaintedOutline]| {
                        let now = scroll.offset().y;
                        let (body, drawn) = frame_lines(cx, &panel);
                        swept.stops += 1;
                        let origin = body.top() + now;
                        views.push((body.top() - origin, body.bottom() - origin));
                        for line in drawn.iter().filter(|line| !line.nested) {
                            let whole = line.top >= body.top() - slack
                                && line.bottom <= body.bottom() + slack;
                            let seen = lines
                                .entry(line.place)
                                .or_insert_with(|| (line.name.clone(), false));
                            seen.1 |= whole;
                        }
                        let lists: Vec<Bounds<Pixels>> = BODY_LISTS
                            .iter()
                            .filter_map(|list| cx.debug_bounds(list))
                            .collect();
                        let scale = cx.update(|window, _| window.scale_factor());
                        // What a list inside the body holds is the list's to show, where
                        // its own scroll has taken it too: the conversation list's rows
                        // below its foot once counted as text no stop of the body showed.
                        let listed: Vec<String> = BODY_LISTS
                            .iter()
                            .flat_map(|list| written::inside(list))
                            .collect();
                        for id in written::inside("github-panel") {
                            if listed.contains(&id) {
                                continue;
                            }
                            let Some(text) = written::get(&id) else {
                                continue;
                            };
                            let (Role::Label | Role::Button, Some(layout)) =
                                (text.node.role(), text.layout)
                            else {
                                continue;
                            };
                            let bounds = Bounds::from_corners(
                                point(px(layout.x0 as f32 / scale), px(layout.y0 as f32 / scale)),
                                point(px(layout.x1 as f32 / scale), px(layout.y1 as f32 / scale)),
                            );
                            if bounds.size.height <= px(0.)
                                || lists.iter().any(|list| list.intersects(&bounds))
                            {
                                continue;
                            }
                            let half = |value: Pixels| (f32::from(value) * 2.).round() as i32;
                            boxes
                                .entry((half(bounds.left()), half(bounds.top() - origin)))
                                .or_insert((id, bounds.top() - origin, bounds.bottom() - origin));
                        }
                        // A ring a clip cuts: a control that cannot fit the body with its ring's
                        // room shows its top, the ring's top edge drawn, as the Conversations
                        // pane does; any other ring is whole.
                        for outline in ring.iter().filter(|outline| !outline.whole) {
                            let tall =
                                outline.bounds.size.height + room * 2. > body.size.height + slack;
                            if !tall || !outline.sides[0] {
                                swept.rings.push(format!(
                                    "{stop}: a clip cuts its ring {:?}, sides whole {:?}, in the \
                                 body {body:?}",
                                    outline.bounds, outline.sides
                                ));
                            }
                        }
                        if let Some(finding) = over_wide(cx, &panel, ring, stop) {
                            swept.cuts.push(finding);
                        }
                        let moved = now != before;
                        before = now;
                        if !moved {
                            return;
                        }
                        swept.moves += 1;
                        if now == px(0.) {
                            return;
                        }
                        match needless_cut(cx, &panel, (body, &drawn), ring, stop) {
                            Err(()) => swept.tall += 1,
                            Ok(Some(finding)) => swept.cuts.push(finding),
                            Ok(None) => {}
                        }
                    };
                // The walk's own findings but its clipped rings, which `each` reads above.
                let mut walked = Vec::new();
                crate::focus_ring::sweep::walk_each(
                    &app,
                    cx,
                    key,
                    &at,
                    interface,
                    &mut walked,
                    &mut each,
                );
                swept.rings.extend(
                    walked
                        .into_iter()
                        .filter(|failure| !failure.contains(": a clip cuts the ")),
                );
            }
            swept.unseen.extend(
                lines
                    .iter()
                    .filter(|(_, (_, whole))| !whole)
                    .map(|(place, (name, _))| format!("{at}: {name} at {place:?} is never whole")),
            );
            // What of each text and Button no stop showed at all.
            views.sort_by(|a, b| a.0.as_f32().total_cmp(&b.0.as_f32()));
            for (name, top, bottom) in boxes.values() {
                let mut reach = *top;
                for (shown, ends) in &views {
                    if *shown > reach + slack {
                        break;
                    }
                    reach = reach.max(*ends);
                }
                if reach < *bottom - slack {
                    swept.unseen.push(format!(
                        "{at}: no stop shows {name} {top:?}..{bottom:?} below {reach:?}"
                    ));
                }
            }
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    swept
}

/// At 18 pt in a 461 × 490 window, every stop of the PR list, the connection pane above it,
/// Changes and Source, walked with Tab and with Shift+Tab from the surface opened at the
/// body's top, draws its ring whole inside every clip around it (`focus_ring::sweep`), but
/// for the connection pane's own stop, which is taller than the body there and draws its
/// ring on its edge, so its reveal shows its top, the ring's top edge whole. The
/// reveal sweep found two cut ([`sweep_reveals`]): Tab onto the PR list's first row left
/// its ring's top edge half a pixel above the body's top, where the reveal's stop clear of
/// every line was allowed half a pixel inside the part it shows; and Tab onto Changes'
/// patch, which fits the body with its ring's room, revealed the file's part, which is
/// taller than the body, at its top, the patch's foot and its ring below the body's.
#[gpui::test]
async fn reveals_draw_the_pr_rows_and_the_files_boxes_rings_whole(cx: &mut TestAppContext) {
    use crate::focus_ring::sweep;
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let mut failures = Vec::new();
    for surface in [
        Surface::Connection,
        Surface::Pulls,
        Surface::Changes,
        Surface::Source,
    ] {
        for key in ["tab", "shift-tab"] {
            show_surface((&app, &panel, &pull, &files), surface, (18, 461., 490.), cx).await;
            sweep::walk_each(
                &app,
                cx,
                key,
                &format!("{surface:?} by {key}"),
                18,
                &mut failures,
                &mut |_, _, _| {},
            );
        }
    }
    sweep::assert_whole_except(
        failures,
        &[
            (
                "Connection by tab at 18 pt, stop 2 by Tab (",
                "a clip cuts the right, bottom, left",
            ),
            (
                "Connection by shift-tab at 18 pt, stop 6 by Shift+Tab (",
                "a clip cuts the right, bottom, left",
            ),
        ],
    );
}

/// Tab onto the PR list's row from Account options, and Shift+Tab onto it from Recover
/// drafts, at 17 pt in a 461 × 490 window, leave no line cut at the body's edges, the
/// title whole with its ring and its row's context line with it: the title is a part of
/// its own. Revealed as the list, the row's reveal kept the room the list keeps below its
/// last row, which no place with every line whole showed, and left Previous PR page cut
/// at the body's foot (Tab, the body's top edge could stop clear of every line 43.5 px
/// higher) or the second line of Drafts stay on this computer (Shift+Tab, 199 px higher),
/// as FU27-B's probe found.
#[gpui::test]
async fn a_pr_rows_reveal_leaves_no_line_cut_at_17_pt(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    for key in BOTH_WAYS {
        show_surface(
            (&app, &panel, &pull, &[]),
            Surface::Pulls,
            (17, 461., 490.),
            cx,
        )
        .await;
        let mut rows = 0;
        let mut each =
            |cx: &mut VisualTestContext, stop: &str, _: &[crate::focus_ring::PaintedOutline]| {
                let on_row = cx.update(|window, _| {
                    window.context_stack().iter().any(|context| {
                        context
                            .get(review::PULL)
                            .is_some_and(|part| part.as_ref() == format!("pr-{}", pull.number))
                    })
                });
                if !on_row {
                    return;
                }
                rows += 1;
                let (body, drawn) = frame_lines(cx, &panel);
                assert_eq!(
                    cut_at_edges(body, &drawn),
                    Vec::<String>::new(),
                    "{stop}: the row's reveal leaves no line cut at the body's edges {body:?}"
                );
            };
        let mut walked = Vec::new();
        crate::focus_ring::sweep::walk_each(
            &app,
            cx,
            key,
            &format!("Pulls at 17 pt in 461 × 490 by {key}"),
            17,
            &mut walked,
            &mut each,
        );
        assert_eq!(rows, 1, "{key} reaches the PR row once");
        crate::focus_ring::sweep::assert_whole(walked);
    }
}

/// The text sizes and window sizes the twelve-row PR list is walked at
/// ([`a_pr_row_below_the_lists_fold_is_revealed_in_the_list_then_the_body_at`]), in the
/// order one test walked them. Each is one test now, its own slice of this list below.
const FOLD_SIZES: [(u8, f32, f32); 3] = [(13, 461., 490.), (17, 461., 490.), (18, 461., 490.)];

/// The slice of [`FOLD_SIZES`] each part of the walk runs, in the list's order;
/// `the_parts_of_the_fold_walk_run_each_size_once` holds them to the list.
const FOLD_AT_13_PT: std::ops::Range<usize> = 0..1;
const FOLD_AT_17_PT: std::ops::Range<usize> = 1..2;
const FOLD_AT_18_PT: std::ops::Range<usize> = 2..3;

/// Tab and Shift+Tab through a PR list of twelve rows, taller than the list's 206 px cap, at
/// 13, 17 and 18 pt in a 461 × 490 window, across the list's fold and the body's: each row's
/// title takes focus with its ring whole, inside both the list and the body, the list
/// scrolling first and the body then showing where the title landed, and no more than the
/// title with its ring's room ([`over_wide`]), leaving no line cut where a place would not
/// ([`needless_cut`]). Rows start below the list's fold, so the walk cannot pass without
/// scrolling it. Revealed as parts of the body, the rows below the fold had the body scroll
/// to where the list clipped them, away from the list, their rings undrawn.
///
/// Walked at `sizes`, a slice of [`FOLD_SIZES`], on a panel and twelve rows of its own:
/// one test a size, since the six walks in one test took 73.6 s on a hosted runner,
/// against the 120 s at which nextest ends a test.
async fn a_pr_row_below_the_lists_fold_is_revealed_in_the_list_then_the_body_at(
    sizes: std::ops::Range<usize>,
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let rows: Vec<PullRequest> = (0..12)
        .map(|index| {
            let mut row = pull.clone();
            row.number = pull.number + index;
            row.title = format!("Fixture row {index} of twelve in a list past its cap");
            row
        })
        .collect();
    let count = rows.len();
    panel.update(cx, |panel, _| panel.rows = rows);
    for size in FOLD_SIZES[sizes].iter().copied() {
        for key in BOTH_WAYS {
            show_surface((&app, &panel, &pull, &[]), Surface::Pulls, size, cx).await;
            // Laid out, a row the list clips draws nothing a debug selector records.
            let scroll = cx.read(|cx| panel.read(cx).review.pull_scroll.clone());
            let list = scroll.bounds();
            let last = scroll.bounds_for_item(count - 1).expect("the last row");
            assert!(
                last.top() > list.bottom(),
                "{size:?}: the last row {last:?} starts below the list's fold {list:?}"
            );
            let mut reached = Vec::new();
            let mut findings = Vec::new();
            let mut each = |cx: &mut VisualTestContext,
                            stop: &str,
                            ring: &[crate::focus_ring::PaintedOutline]| {
                let row = cx.update(|window, _| {
                    window
                        .context_stack()
                        .iter()
                        .find_map(|context| context.get(review::PULL).cloned())
                });
                let Some(row) = row else {
                    return;
                };
                reached.push(row.to_string());
                let Some(title) = ring
                    .iter()
                    .map(|outline| outline.bounds)
                    .reduce(|a, b| a.union(&b))
                else {
                    return;
                };
                let list = cx.debug_bounds("github-pr-list").expect("the list");
                let body = cx.debug_bounds("github-panel").expect("the body");
                for (name, clip) in [("list", list), ("body", body)] {
                    if title.top() < clip.top() - px(0.5)
                        || title.bottom() > clip.bottom() + px(0.5)
                    {
                        findings.push(format!(
                            "{stop}: the ring {title:?} not whole in the {name} {clip:?}"
                        ));
                    }
                }
                findings.extend(over_wide(cx, &panel, ring, stop));
                let (body, drawn) = frame_lines(cx, &panel);
                if let Ok(Some(finding)) = needless_cut(cx, &panel, (body, &drawn), ring, stop) {
                    findings.push(finding);
                }
            };
            let mut walked = Vec::new();
            crate::focus_ring::sweep::walk_each(
                &app,
                cx,
                key,
                &format!("Twelve PR rows at {size:?} by {key}"),
                size.0,
                &mut walked,
                &mut each,
            );
            reached.sort();
            reached.dedup();
            assert_eq!(
                reached.len(),
                12,
                "{size:?} by {key}: every row takes focus"
            );
            crate::focus_ring::sweep::assert_whole(walked);
            assert_eq!(findings, Vec::<String>::new(), "{size:?} by {key}");
        }
    }
}

