/// The three parts of the twelve-row walk run [`FOLD_SIZES`] between them, each size once
/// and in the list's order, and each part runs one size at least: a size added to the list
/// that no part takes fails here, as does one two parts take.
#[test]
fn the_parts_of_the_fold_walk_run_each_size_once() {
    let parts = [FOLD_AT_13_PT, FOLD_AT_17_PT, FOLD_AT_18_PT];
    assert!(
        parts.iter().all(|part| !part.is_empty()),
        "a part runs no size: {parts:?}"
    );
    let run: Vec<_> = parts
        .into_iter()
        .flat_map(|part| FOLD_SIZES[part].iter().copied())
        .collect();
    assert_eq!(run, FOLD_SIZES);
}

/// A pane that holds focus, itself or on a control inside it, hands it to the control
/// that closed it as it goes, by the pointer's route, in a 1,480 × 800 window at 13 pt: a
/// click on the connection pane's help focuses the pane, and Tab from there focuses its
/// first control; Account options then closes it and takes focus, and Tab moves on to the
/// PR list's row after it; a click on the Conversations pane's heading in Files' Threads
/// focuses that pane, and Tab its first control; Changes then replaces it and takes
/// focus, and Tab moves on to Source. Left on a pane no frame drew, or on a control of
/// one, focus started the next Tab again from the window's first stop, and the panel's
/// keys, Escape among them, went nowhere. Native QA's route on Omarchy too, with no
/// account connected, at 18 pt in a 480 × 490 window: a click on the help, scrolled into
/// view, then the body scrolled back to its top and Account options, named Connect
/// account there, closing the pane, leaves focus on Connect account.
#[gpui::test]
async fn closing_a_focused_pane_focuses_the_control_that_closed_it(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let (connection, account, section, modes) = cx.read(|cx| {
        let review = &panel.read(cx).review;
        (
            review.connection_focus.clone(),
            review.account_focus.clone(),
            review.section_focus.clone(),
            review.mode_focus.clone(),
        )
    });
    let focused = |cx: &mut VisualTestContext, focus: &FocusHandle| {
        cx.update(|window, _| focus.is_focused(window))
    };
    let settle = |cx: &mut VisualTestContext| {
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    let click = |cx: &mut VisualTestContext, selector: &'static str| {
        let at = cx.debug_bounds(selector).expect(selector).center();
        cx.simulate_click(at, Modifiers::none());
        settle(cx);
    };
    // Tab from the pane, which a click focused, onto the first control inside it.
    let into = |cx: &mut VisualTestContext, pane: &FocusHandle, name: &str| {
        cx.simulate_keystrokes("tab");
        settle(cx);
        assert!(
            cx.update(|window, cx| !pane.is_focused(window) && pane.contains_focused(window, cx)),
            "Tab moves from {name} onto a control inside it"
        );
    };
    let size = (13, 1480., 800.);

    for inside in [false, true] {
        let held = if inside {
            "a control inside the pane"
        } else {
            "the pane"
        };
        show_surface((&app, &panel, &pull, &files), Surface::Connection, size, cx).await;
        click(cx, "github-connection-help");
        assert!(
            focused(cx, &connection),
            "a click on the help focuses the pane"
        );
        if inside {
            into(cx, &connection, "the connection pane");
        }
        click(cx, "github-account-options");
        assert!(
            !panel.read_with(cx, |panel, _| panel.review.connection_open),
            "Account options closes the pane"
        );
        assert!(
            focused(cx, &account),
            "the focus {held} held moves to Account options, which closed it"
        );
        cx.simulate_keystrokes("tab");
        settle(cx);
        let part = cx.update(|window, _| {
            window
                .context_stack()
                .iter()
                .rev()
                .find_map(|context| context.get(review::PULL).cloned())
        });
        assert_eq!(
            part.as_deref(),
            Some(format!("pr-{}", pull.number).as_str()),
            "Tab moves on from Account options to the PR list's row"
        );

        show_surface((&app, &panel, &pull, &files), Surface::Threads, size, cx).await;
        click(cx, "github-conversations-heading");
        assert!(
            focused(cx, &section),
            "a click on the heading focuses the Conversations pane"
        );
        if inside {
            into(cx, &section, "the Conversations pane");
        }
        click(cx, "github-file-mode-0");
        assert_eq!(panel.read_with(cx, |panel, _| panel.review.mode), 0);
        assert!(
            focused(cx, &modes[0]),
            "the focus {held} held moves to Changes, which closed it"
        );
        cx.simulate_keystrokes("tab");
        settle(cx);
        assert!(
            focused(cx, &modes[1]),
            "Tab moves on from Changes to Source"
        );
    }

    show_surface(
        (&app, &panel, &pull, &files),
        Surface::Connection,
        (18, 480., 490.),
        cx,
    )
    .await;
    panel.update(cx, |panel, cx| {
        panel.account = None;
        cx.notify();
    });
    settle(cx);
    let scroll = cx.read(|cx| panel.read(cx).review.body_scroll.clone());
    let body = scroll.bounds();
    // Scrolled as a wheel would, which moves no focus: the help's top at the body's top.
    let help = cx.debug_bounds("github-connection-help").expect("the help");
    let offset = scroll.offset();
    scroll.set_offset(point(
        offset.x,
        (offset.y - (help.top() - body.top())).clamp(-scroll.max_offset().y, px(0.)),
    ));
    settle(cx);
    let help = cx.debug_bounds("github-connection-help").expect("the help");
    let at = point(
        help.center().x,
        help.top() + (help.bottom().min(body.bottom()) - help.top()) / 2.,
    );
    assert!(
        body.contains(&at),
        "the help's click {at:?} lies in the body {body:?}"
    );
    cx.simulate_click(at, Modifiers::none());
    settle(cx);
    assert!(
        focused(cx, &connection),
        "at 18 pt in 480 × 490, a click on the help focuses the pane"
    );
    // Scrolled up, as a wheel would, until Connect account, which the toolbar wraps below
    // the body's foot at the body's top, shows whole.
    scroll.set_offset(point(offset.x, px(0.)));
    settle(cx);
    let button = cx
        .debug_bounds("github-account-options")
        .expect("Connect account");
    scroll.set_offset(point(
        offset.x,
        (body.bottom() - button.bottom()).clamp(-scroll.max_offset().y, px(0.)),
    ));
    settle(cx);
    let button = cx
        .debug_bounds("github-account-options")
        .expect("Connect account");
    assert!(
        body.contains(&button.center()),
        "Connect account {button:?} shows in the body {body:?}"
    );
    cx.simulate_click(button.center(), Modifiers::none());
    settle(cx);
    assert!(
        !panel.read_with(cx, |panel, _| panel.review.connection_open),
        "Connect account closes the pane"
    );
    assert!(
        cx.update(|window, _| account.is_focused(window) && !window.context_stack().is_empty()),
        "the pane's focus moves to Connect account, which closed it, drawn"
    );
}

/// The control a press records as the panel's closer takes the focus a pane held only as
/// the frame its press draws takes the pane away ([`review::ReviewState::closer`]), in a
/// 1,480 × 800 window at 13 pt: with Threads' Conversations pane focused by a click on its
/// heading, Account options opens the connection pane, taking no pane away; a page of
/// files the panel receives later replaces Threads with no press since, and the file list
/// takes the pane's focus ([`Panel::focus_visible_section`]). Kept until another press,
/// the closer gave it to Account options, whose press had closed nothing.
#[gpui::test]
async fn a_press_that_takes_no_pane_away_leaves_no_closer_for_later(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let page = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap();
    let files = page.items.clone();
    let (section, account, file_list) = cx.read(|cx| {
        let review = &panel.read(cx).review;
        (
            review.section_focus.clone(),
            review.account_focus.clone(),
            review.file_focus.clone(),
        )
    });
    let settle = |cx: &mut VisualTestContext| {
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    let click = |cx: &mut VisualTestContext, selector: &'static str| {
        let at = cx.debug_bounds(selector).expect(selector).center();
        cx.simulate_click(at, Modifiers::none());
        settle(cx);
    };
    show_surface(
        (&app, &panel, &pull, &files),
        Surface::Threads,
        (13, 1480., 800.),
        cx,
    )
    .await;
    click(cx, "github-conversations-heading");
    click(cx, "github-account-options");
    assert!(
        panel.read_with(cx, |panel, _| panel.review.connection_open),
        "Account options opens the connection pane"
    );
    assert!(
        cx.update(|window, _| section.is_focused(window)),
        "the Conversations pane keeps the focus its heading's click gave it"
    );
    panel.update(cx, |panel, cx| {
        panel.receive_file_page(page);
        cx.notify();
    });
    settle(cx);
    assert_eq!(panel.read_with(cx, |panel, _| panel.review.mode), 0);
    let (on_account, on_list) =
        cx.update(|window, _| (account.is_focused(window), file_list.is_focused(window)));
    assert!(
        !on_account && on_list,
        "the file list takes the pane's focus, not Account options \
         (Account options {on_account}, the file list {on_list})"
    );
}

/// New pull request and Files' pages take away a pane that holds focus by the pointer's
/// route too, and the panel's one guard hands its focus on
/// ([`Panel::hand_off_lost_pane_focus`]), in a 1,480 × 800 window at 13 pt: a click on the
/// Conversations pane's heading in Overview focuses the pane, and New pull request then
/// replaces the PR and takes focus, Tab moving on to Account options; in Files' Threads on
/// the third page, Previous loads the second, which replaces the pane, and takes focus;
/// from the first page with a next one, Next loads the second, which has none, so Next is
/// disabled there and the file list takes focus. Each is a focus the frame draws: left on
/// the pane, focus was on nothing drawn and the next Tab started again from the window's
/// first stop.
#[gpui::test]
async fn a_new_pr_or_a_page_of_files_hands_on_the_focus_of_the_pane_it_replaces(
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let (section, create, account, pages, file_list) = cx.read(|cx| {
        let review = &panel.read(cx).review;
        (
            review.section_focus.clone(),
            review.create_focus.clone(),
            review.account_focus.clone(),
            review.file_page_focus.clone(),
            review.file_focus.clone(),
        )
    });
    // Focus on `focus`, which the last frame drew.
    let drawn = |cx: &mut VisualTestContext, focus: &FocusHandle| {
        cx.update(|window, _| focus.is_focused(window) && !window.context_stack().is_empty())
    };
    let settle = |cx: &mut VisualTestContext| {
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    let click = |cx: &mut VisualTestContext, selector: &'static str| {
        let at = cx.debug_bounds(selector).expect(selector).center();
        cx.simulate_click(at, Modifiers::none());
        settle(cx);
    };
    let size = (13, 1480., 800.);

    show_surface((&app, &panel, &pull, &files), Surface::Overview, size, cx).await;
    // The offline fixture offers no New pull request.
    panel.update(cx, |panel, cx| {
        panel.review.fixture = false;
        cx.notify();
    });
    settle(cx);
    click(cx, "github-conversations-heading");
    assert!(
        drawn(cx, &section),
        "a click on the heading focuses the pane"
    );
    click(cx, "github-create");
    assert!(
        panel.read_with(cx, |panel, _| panel.create && panel.pull.is_none()),
        "New pull request replaces the PR"
    );
    assert!(
        drawn(cx, &create),
        "the pane's focus moves to New pull request, which replaced it"
    );
    cx.simulate_keystrokes("tab");
    settle(cx);
    assert!(
        drawn(cx, &account),
        "Tab moves on from New pull request to Account options"
    );
    panel.update(cx, |panel, cx| {
        panel.create = false;
        panel.review.fixture = true;
        cx.notify();
    });

    for (page, next, selector, takes, name) in [
        (3, false, "github-files-previous", &pages[0], "Previous"),
        (1, true, "github-files-next", &file_list, "the file list"),
    ] {
        show_surface((&app, &panel, &pull, &files), Surface::Threads, size, cx).await;
        panel.update(cx, |panel, cx| {
            panel.review.file_page = page;
            panel.review.files_next = next;
            cx.notify();
        });
        settle(cx);
        click(cx, "github-conversations-heading");
        assert!(
            drawn(cx, &section),
            "a click on the heading focuses the pane"
        );
        click(cx, selector);
        settle_panel(&app, cx).await;
        settle(cx);
        assert_eq!(
            panel.read_with(cx, |panel, _| (panel.review.mode, panel.review.file_page)),
            (0, 2),
            "{selector} loads the second page, which replaces Threads"
        );
        assert!(
            drawn(cx, takes),
            "the pane's focus moves to {name} as {selector}'s page replaces it"
        );
    }
}

/// Tab onto the destination field, the part the panel reopens onto, from the banner's Move
/// fixture head before it, and Shift+Tab onto it from Refresh PRs after it, draw the
/// field's accent edge and the ring outside it whole on the field's frame, as every kit
/// field draws them (`focus_ring::assert_input_ringed`), uncut by the body or any clip
/// around it: on the PR list, at 13 and 18 pt in a 1,480 × 973 window and a 461 × 490 one,
/// at scales 1.25 and 2.
#[gpui::test]
async fn tab_onto_the_destination_field_draws_its_ring_whole(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let field = cx.read(|cx| panel.read(cx).destination.read(cx).focus_handle(cx));
    let focused = |cx: &mut VisualTestContext| cx.update(|window, _| field.is_focused(window));
    let step = |cx: &mut VisualTestContext, key: &str| {
        cx.simulate_keystrokes(key);
        for _ in 0..2 {
            crate::width_walk::frame(cx);
        }
        // Moving the pointer without a press keeps the ring.
        cx.simulate_mouse_move(point(px(2.), px(2.)), None, Modifiers::none());
        crate::width_walk::frame(cx);
    };
    for scale in [1.25, 2.] {
        for (interface, width, height) in [
            (13, 1480., 973.),
            (18, 1480., 973.),
            (13, 461., 490.),
            (18, 461., 490.),
        ] {
            cx.update(|window, _| window.set_scale_factor(scale));
            show_surface(
                (&app, &panel, &pull, &[]),
                Surface::Pulls,
                (interface, width, height),
                cx,
            )
            .await;
            cx.update(|window, cx| window.focus(&field, cx));
            crate::width_walk::frame(cx);
            for (away, back) in [("shift-tab", "tab"), ("tab", "shift-tab")] {
                let at = format!("{back} at {interface} pt in {width} × {height} at {scale}");
                step(cx, away);
                assert!(!focused(cx), "{at}: {away} leaves the field");
                step(cx, back);
                assert!(focused(cx), "{at}: {back} focuses the field");
                let text = cx.read(|cx| panel.read(cx).destination.read(cx).input_bounds());
                crate::focus_ring::assert_input_ringed(cx, text, &at);
            }
        }
    }
}

/// A row a list inside the body cuts at its edge is a line of the body as far as the list
/// shows it (`review::keep_line`): at 18 pt in a 461 × 490 window, the changed-file list
/// stacked above Changes shows its first row whole and the top of its second, which the
/// body's lines hold from the row's top to the list's foot. Counted only where the list
/// showed it whole, the second row reported nothing, and the body's reveals took the file
/// name and status the list shows of it for room between lines: Tab onto the Review tab
/// stopped the body's foot through that status line, as Tab onto Source's text at 13 pt
/// stopped its top through the third row's file name, though no place the body could
/// scroll to cleared every line there ([`needless_cut`]).
#[gpui::test]
async fn a_row_a_list_cuts_is_a_line_of_the_body_where_the_list_shows_it(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    show_surface(
        (&app, &panel, &pull, &files),
        Surface::Changes,
        (18, 461., 490.),
        cx,
    )
    .await;
    let slack = px(0.5);
    let list = cx.debug_bounds("github-file-rows").expect("the file list");
    let rows: Vec<Bounds<Pixels>> = indexed("github-file-row-", files.len())
        .into_iter()
        .filter_map(|row| cx.debug_bounds(row))
        .collect();
    let cut: Vec<&Bounds<Pixels>> = rows
        .iter()
        .filter(|row| row.top() < list.bottom() - slack && row.bottom() > list.bottom() + slack)
        .collect();
    let [row] = cut[..] else {
        panic!("the list {list:?} cuts one row at its foot: {rows:?}");
    };
    let lines = panel.read_with(cx, |panel, cx| panel.review.body_blocks.lines(cx));
    assert!(
        lines.iter().any(|(top, bottom)| {
            (*top - row.top()).abs() <= slack && (*bottom - list.bottom()).abs() <= slack
        }),
        "the row {row:?} the list {list:?} cuts is a line of the body to the list's foot: \
         {lines:?}"
    );
}

/// Fails with every finding of `swept` ([`sweep_reveals`]), each printed first.
fn assert_swept(swept: Swept) {
    let findings: Vec<&String> = swept
        .cuts
        .iter()
        .chain(&swept.rings)
        .chain(&swept.unseen)
        .collect();
    for finding in &findings {
        eprintln!("{finding}");
    }
    assert!(swept.moves > 0, "the walks move the body");
    assert!(
        findings.is_empty(),
        "{} findings in {} stops, {} of them moving the body ({} onto a part too tall for it)",
        findings.len(),
        swept.stops,
        swept.moves,
        swept.tall
    );
}

/// The reveal sweep's walks at the stops where its run on 2026-11-05 found what FU20-GH6
/// traced, which the whole sweep takes too long to repeat in every gate
/// ([`the_reveal_sweep_finds_every_line_whole_and_every_ring_drawn`]): at 13 pt in a
/// 461 × 490 window, Overview and Source; at 18 pt there, the connection pane, the PR list,
/// Review, Changes, Source and Threads; at 13 pt in a 1,480 × 800 window, Threads. At every
/// stop of each walk the focused control draws its ring whole, no reveal leaves a line cut
/// where a place clears every line, and every line outside the lists is whole at some stop
/// ([`assert_swept`]). Each surface at its size is a test of its own, walked with Tab and
/// then with Shift+Tab, so a test runner takes them side by side: walked in one test, the
/// nine took about 74 s in a debug build on the Linux development host and ran past
/// nextest's 120 s limit on every hosted runner (run 42250019193). Threads in the wide
/// window, whose two walks of 24 stops each take about 16 s there, is two tests, one for
/// each key, and each walk shows every line outside the lists whole on its own.
///
/// The connection pane at 18 pt in a 480 × 490 window, where Linux lays its help out in
/// five lines as macOS does in 461 × 490, is a walk of its own: there no stop of its
/// controls can show its "Local worktree:" line or its help's first line with every line
/// whole, and hosted run 42333458175 found neither shown at any stop on macOS
/// (`connection_at_18_pt`), as the walk did on Linux from 470 to 495 px wide. The pane is
/// a stop of its own now, which shows both from its top. The PR list at 17 pt in a
/// 461 × 490 window is one too, where FU27-B's probe found its row's reveals leaving a line
/// cut ([`a_pr_rows_reveal_leaves_no_line_cut_at_17_pt`]). So is Overview at 17 pt in a
/// 440 × 490 window and at 18 pt in a 480 × 490 one, where the PR's captured identities,
/// six lines between the section tabs and the Conversations pane, lay below the last
/// tab's reveal and above the pane's, and no stop showed most of them, or any at 18 pt:
/// the last tab owns them now (`review::Owned`), and Tab onto it shows them with it. So is
/// Overview at 17 pt in a 461 × 490 window, where FU28-A's probe found the same, and in a
/// 440 × 400 one, where the body is shorter than the tab and the identities together, so
/// the last tab's reveal cannot show them and they are a group stop of their own, revealed
/// from their top (`review::Owned::apart`); held to the tab's reveal alone, no stop showed
/// them below about 430 px tall.
mod the_reveal_sweep_finds_nothing_where_it_found_reveals_to_trace {
    use super::*;

    /// Writes a test for each walk listed, a surface at an interface size in a window's
    /// width and height walked with the keys listed, that walks it through the reveal
    /// sweep ([`sweep_reveals`]) and fails with its findings ([`assert_swept`]).
    macro_rules! found_walks {
        ($($name:ident: $surface:ident at $size:expr, by $keys:expr;)*) => {$(
            #[gpui::test]
            async fn $name(cx: &mut TestAppContext) {
                let walk: Walk<'_> = ($size, &[Surface::$surface]);
                assert_swept(sweep_reveals(cx, &[walk], &$keys).await);
            }
        )*};
    }

    found_walks! {
        overview_at_13_pt: Overview at (13, 461., 490.), by BOTH_WAYS;
        overview_at_17_pt: Overview at (17, 461., 490.), by BOTH_WAYS;
        overview_at_17_pt_in_a_440_px_window: Overview at (17, 440., 490.), by BOTH_WAYS;
        overview_at_17_pt_in_a_440_by_400_window: Overview at (17, 440., 400.), by BOTH_WAYS;
        overview_at_18_pt_in_a_480_px_window: Overview at (18, 480., 490.), by BOTH_WAYS;
        source_at_13_pt: Source at (13, 461., 490.), by BOTH_WAYS;
        connection_at_18_pt: Connection at (18, 461., 490.), by BOTH_WAYS;
        connection_at_18_pt_in_a_480_px_window: Connection at (18, 480., 490.), by BOTH_WAYS;
        pulls_at_17_pt: Pulls at (17, 461., 490.), by BOTH_WAYS;
        pulls_at_18_pt: Pulls at (18, 461., 490.), by BOTH_WAYS;
        review_at_18_pt: Review at (18, 461., 490.), by BOTH_WAYS;
        changes_at_18_pt: Changes at (18, 461., 490.), by BOTH_WAYS;
        source_at_18_pt: Source at (18, 461., 490.), by BOTH_WAYS;
        threads_at_18_pt: Threads at (18, 461., 490.), by BOTH_WAYS;
        threads_at_13_pt_in_a_wide_window_by_tab: Threads at (13, 1480., 800.), by ["tab"];
        threads_at_13_pt_in_a_wide_window_by_shift_tab:
            Threads at (13, 1480., 800.), by ["shift-tab"];
    }
}

/// Overview's captured identities are a stop of their own exactly where they cannot fit the
/// body with the last section tab, which owns them (`review::Owned::apart`): not at 13 pt in
/// a 1,480 × 800 window, where Tab onto the tab shows them with it, but at 17 pt in a
/// 440 × 400 one, where it cannot, so Tab reaches them there (the always-on walk at that
/// size holds their ring and their lines whole, `overview_at_17_pt_in_a_440_by_400_window`);
/// a resize back gives the stop up again.
#[gpui::test]
async fn the_identities_are_a_stop_only_where_they_cannot_fit_with_the_last_tab(
    cx: &mut TestAppContext,
) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let (identities, focus) = cx.read(|cx| {
        let review = &panel.read(cx).review;
        (review.identities.clone(), review.identities_focus.clone())
    });
    for (size, apart) in [
        ((13, 1480., 800.), false),
        ((17, 440., 400.), true),
        ((13, 1480., 800.), false),
    ] {
        show_surface((&app, &panel, &pull, &[]), Surface::Overview, size, cx).await;
        assert_eq!(
            identities.apart(),
            apart,
            "{size:?}: the identities cannot fit the body with the last tab"
        );
        // Every stop of the window's Tab order, from the Conversations pane round to it.
        let reached = cx.update(|window, cx| {
            let start = window.focused(cx);
            let mut reached = false;
            for _ in 0..200 {
                window.focus_next(cx);
                reached |= focus.is_focused(window);
                if window.focused(cx) == start {
                    break;
                }
            }
            reached
        });
        assert_eq!(
            reached, apart,
            "{size:?}: the identities a stop of their own"
        );
    }
}

/// A click on Overview's captured identities focuses them only where they are a stop of
/// their own (`review::Owned::apart`), and New pull request, which replaces the PR, then
/// takes their focus as it takes the Conversations pane's
/// ([`Panel::hand_off_lost_pane_focus`]): at 13 pt in a 1,480 × 800 window, where the last
/// section tab shows them with it, a click leaves focus where it was; at 17 pt in a
/// 440 × 400 one, scrolled to them, it focuses them. Tracked at every size, a click
/// focused them at rest, where no Tab reaches them, and New pull request then left that
/// focus on nothing drawn.
#[gpui::test]
async fn a_click_focuses_the_identities_only_where_they_are_a_stop(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    let (identities, create, scroll) = cx.read(|cx| {
        let review = &panel.read(cx).review;
        (
            review.identities_focus.clone(),
            review.create_focus.clone(),
            review.body_scroll.clone(),
        )
    });
    let settle = |cx: &mut VisualTestContext| {
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
    };
    for (size, apart) in [((13, 1480., 800.), false), ((17, 440., 400.), true)] {
        show_surface((&app, &panel, &pull, &[]), Surface::Overview, size, cx).await;
        // The offline fixture offers no New pull request.
        panel.update(cx, |panel, cx| {
            panel.review.fixture = false;
            cx.notify();
        });
        settle(cx);
        // Scrolled as a wheel would, the identities' top at the body's.
        let shown = cx
            .debug_bounds("github-captured-identities")
            .expect("the identities");
        let body = scroll.bounds();
        let offset = scroll.offset();
        scroll.set_offset(point(
            offset.x,
            (offset.y - (shown.top() - body.top())).clamp(-scroll.max_offset().y, px(0.)),
        ));
        settle(cx);
        let at = cx
            .debug_bounds("github-captured-identities")
            .expect("the identities")
            .center();
        assert!(
            body.contains(&at),
            "{size:?}: the identities' middle {at:?} lies in the body {body:?}"
        );
        cx.simulate_click(at, Modifiers::none());
        settle(cx);
        assert_eq!(
            cx.update(|window, _| identities.is_focused(window)),
            apart,
            "{size:?}: a click focuses the identities only where they are a stop"
        );
        // Back to the toolbar, as a wheel would, which moves no focus.
        scroll.set_offset(point(offset.x, px(0.)));
        settle(cx);
        let at = cx
            .debug_bounds("github-create")
            .expect("New pull request")
            .center();
        cx.simulate_click(at, Modifiers::none());
        settle(cx);
        assert!(
            panel.read_with(cx, |panel, _| panel.create && panel.pull.is_none()),
            "{size:?}: New pull request replaces the PR"
        );
        if apart {
            assert!(
                cx.update(
                    |window, _| create.is_focused(window) && !window.context_stack().is_empty()
                ),
                "{size:?}: the identities' focus moves to New pull request, which replaced them"
            );
        }
        panel.update(cx, |panel, cx| {
            panel.create = false;
            panel.review.fixture = true;
            cx.notify();
        });
    }
}

/// The reveal sweep over every surface of the panel ([`SURFACES`]) on the offline fixture,
/// at 13 and 18 pt in a 461 × 490 window and a 1,480 × 800 one ([`REVEAL_SIZES`]), with
/// Tab through every stop and then Shift+Tab ([`sweep_reveals`]): at every stop the focused
/// control draws its ring whole, or its top edge where it cannot fit the body; no reveal
/// leaves a line cut at either of the body's edges where a place clears every line with
/// the revealed part whole; and every line outside the lists inside the body is whole at
/// some stop. It prints every finding before it fails. It takes about 3 min in a debug
/// build (180 s on the Linux development host on 2026-11-06), too long for every gate:
/// the gate walks the stops where it found reveals to trace, a test for each walk
/// ([`the_reveal_sweep_finds_nothing_where_it_found_reveals_to_trace`]), and this whole
/// sweep stays opt-in.
///
/// Run on Linux on 2026-11-05 (FU20-GH5), it found 133 in 872 stops. The 114 texts no stop
/// showed were the conversation list's own rows, scrolled out of the list below its foot or
/// above its top, which the sweep counted as the body's because only the rows crossing the
/// list's viewport counted as the list's; the list's reveals are
/// `conversation_reveals_leave_no_line_cut_at_the_lists_edges_at`'s, and the sweep now leaves
/// whatever a list in the body holds to that list. No line outside the lists was never
/// whole. The 19 left, traced in FU20-GH6 (2026-11-06), were three defects of the panel and
/// three of the sweep's reading, each fixed; the sweep finds nothing since:
/// - The PR list's first row at 18 pt in 461 × 490 (stops 2 and 3), its ring half a pixel
///   above the body's top: the reveal's stop clear of every line was allowed half a pixel
///   inside the part it shows (`review::clear_of_lines`).
/// - Changes' patch at 18 pt in 461 × 490 (stops 4 and 10), its foot and ring below the
///   body's: it was revealed as the file's part, taller than the body, and is now a part of
///   its own, as Source's box is
///   (`reveals_draw_the_pr_rows_and_the_files_boxes_rings_whole`).
/// - The Files section's third tab at 18 pt in 461 × 490 (Changes, Source and Threads,
///   stops 0, 14 and 22) and Source's text at 13 pt (stops 4 and 10): the changed-file
///   list's row its foot cut reported no line, so the reveals stopped through the status
///   line and the file name it showed of it; a row a list cuts is now the part it shows
///   (`review::keep_line`, `a_row_a_list_cuts_is_a_line_of_the_body_where_the_list_shows_it`).
/// - Buttons write no accessibility node, so the sweep read no Button's frame and took its
///   label's run, 12 px at 13 pt, for its line: the run "no label or Button holds" at 13 pt
///   in Overview (stop 10) was Recover drafts' label, whose frame the body's foot cut, and
///   at 13 pt in 1,480 × 800, Threads' file pane (stop 4) had places through the frames of
///   the section tabs above it, and others through a line out of view (below). It reads
///   each control of one line as drawn now (`review::drawn_one_lines`).
/// - Its places were clear of the lines its frame drew, and a frame draws nothing out of
///   the body's view: at 18 pt, the places for the review summary in Review (stop 15) and
///   for Source's text in Source (stops 4 and 10) cut the row of Buttons above them, out
///   of view where the reveal stopped, and Overview's at 13 pt cut the second line of
///   Drafts stay on this computer by half a pixel. It draws each place now, cut to the
///   reveal's hundredth of a pixel ([`verified_stop`]); none of them cleared every line.
/// - It counted two runs of the History page's text beneath the dialog as lines of the
///   body at every stop, where their clips lay inside the body; it reads the dialog's text
///   above its backdrop alone now ([`backdrop`]).
#[gpui::test]
#[ignore = "Opt-in reveal sweep: run with --ignored; prints every finding"]
async fn the_reveal_sweep_finds_every_line_whole_and_every_ring_drawn(cx: &mut TestAppContext) {
    let walks = REVEAL_SIZES.map(|size| (size, &SURFACES[..]));
    assert_swept(sweep_reveals(cx, &walks, &BOTH_WAYS).await);
}

/// A text of the panel works its lines out once for each change of what they follow from
/// (`review::text_lines`), on a PR's Overview of the offline fixture at 13 pt in a
/// 461 × 490 window: a frame that draws the panel unchanged reports every text's lines
/// again with none worked out afresh, into the room the frames before took for them; a
/// frame at another width works them out again, and reports the lines a frame working
/// every text's out afresh reports. Every text read the window's text style for its lines
/// in every frame, which folds the styles around it into a new one and allocates its font
/// features, and the body took new room for its lines in every frame.
#[gpui::test]
async fn texts_work_their_lines_out_once_for_each_width(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    crate::views::tests::hold_quiet_reads_for_test(&app, cx);
    show_overview(&panel, &pull, (13, 461., 490.), cx);
    let blocks = cx.read(|cx| panel.read(cx).review.body_blocks.clone());
    // The update's effects draw the window it dirtied, once, before it returns.
    let redraw = |cx: &mut VisualTestContext| {
        panel.update(cx, |_, cx| cx.notify());
        cx.run_until_parked();
    };
    redraw(cx);
    let (drawn, measured) = blocks.text_counts();
    let lines = cx.read(|cx| blocks.lines(cx));
    assert!(!lines.is_empty(), "the body collects its texts' lines");
    redraw(cx);
    let (drawn_again, measured_again) = blocks.text_counts();
    assert!(
        drawn_again > drawn,
        "the frame at rest draws the panel's texts again"
    );
    assert_eq!(
        measured_again, measured,
        "a frame at rest works out no text's lines again"
    );
    assert_eq!(
        cx.read(|cx| blocks.lines(cx)),
        lines,
        "and reports the lines the frame before did"
    );
    assert!(
        blocks.keeps_its_room(),
        "the frame at rest records its lines in the room the frame before took"
    );

    cx.simulate_resize(size(px(441.), px(490.)));
    for _ in 0..3 {
        crate::width_walk::frame(cx);
    }
    let (_, resized) = blocks.text_counts();
    assert!(
        resized > measured,
        "a frame at another width works the texts' lines out again"
    );
    let kept = cx.read(|cx| blocks.lines(cx));
    blocks.forget_texts();
    redraw(cx);
    assert_eq!(
        cx.read(|cx| blocks.lines(cx)),
        kept,
        "the lines a frame takes from the one before are those it works out afresh"
    );
}

/// Tab through a PR's Overview on the offline fixture, at 13 and 18 pt in a 461 × 490
/// window and in a 1,480 × 800 one: where a stop scrolls the body or the conversation list,
/// the scrolled box's top edge lies at the start of a block, cutting no line, as long as
/// the box has content left below to show; and wrapping from the dialog's last stop to its
/// first, the banner's, returns the body to its top. A conversation's reveal once cut its
/// author line at the list's top, and the wrap left the body 6.5 px (13 pt) and 9 px (18
/// pt) down, the banner's top cut. Every stop draws its ring whole (`focus_ring::sweep`),
/// but for the conversations pane, which is taller than the body in a 461 × 490 window and
/// shows its top edge there, its bottom below the fold.
#[gpui::test]
async fn tab_reveals_land_on_whole_lines_and_wrap_to_the_body_top(cx: &mut TestAppContext) {
    use crate::focus_ring::sweep;
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    let (body_scroll, list_scroll) = cx.read(|cx| {
        let panel = panel.read(cx);
        (
            panel.review.body_scroll.clone(),
            panel.conversations.list_scroll.clone(),
        )
    });
    let mut rings = Vec::new();
    for sizes in REVEAL_SIZES {
        let (interface, width, height) = sizes;
        let at = format!("{interface} pt in {width} × {height}");
        show_overview(&panel, &pull, sizes, cx);
        // The case the narrow window is here for, which the rings' known failures below
        // count on: the conversations pane, with its ring's room above and below it,
        // taller than the body, so it shows its top there and its foot below the fold.
        // At 13 pt it is taller by about 9 px, and a layout change that let it fit would
        // otherwise fail only as known failures that no longer happen.
        if width < 1000. {
            let body = cx.debug_bounds("github-panel").expect("the body");
            let pane = cx.debug_bounds("github-thread-section").expect("the pane");
            let room = cx.update(|_, cx| appearance::button_ring_room(cx));
            assert!(
                pane.size.height + room * 2. > body.size.height,
                "{at}: the pane {pane:?} with its ring's room is taller than the body {body:?}"
            );
        }
        let mut offsets = (body_scroll.offset().y, list_scroll.offset().y);
        let mut wrapped = false;
        let mut list_moves = 0;
        for stop in 0..60 {
            cx.simulate_keystrokes("tab");
            for _ in 0..3 {
                crate::width_walk::frame(cx);
            }
            let part = cx.update(|window, _| {
                window
                    .context_stack()
                    .iter()
                    .rev()
                    .find_map(|context| context.get(review::PART).cloned())
            });
            let now = (body_scroll.offset().y, list_scroll.offset().y);
            let ends = (-body_scroll.max_offset().y, -list_scroll.max_offset().y);
            let here = format!("{at}, stop {stop} in {part:?}");
            if now.0 != offsets.0 && now.0 > ends.0 + px(0.5) {
                let body = cx.debug_bounds("github-panel").expect("the body");
                let cut = lines_cut_at_top(cx, body);
                assert!(
                    cut.is_empty(),
                    "{here}: the body's top edge {body:?} cuts {cut:?}"
                );
            }
            if now.1 != offsets.1 {
                list_moves += 1;
                let list = cx.debug_bounds("github-threads").expect("the list");
                let cut = lines_cut_at_top(cx, list);
                if now.1 > ends.1 + px(0.5) {
                    assert!(
                        cut.is_empty(),
                        "{here}: the list's top edge {list:?} cuts {cut:?}"
                    );
                }
            }
            offsets = now;
            if part.as_ref().is_some_and(|part| part.as_ref() == "banner") {
                assert_eq!(
                    now.0,
                    px(0.),
                    "{here}: the wrap returns the body to its top"
                );
                wrapped = true;
                break;
            }
        }
        assert!(wrapped, "{at}: Tab wraps to the banner");
        assert!(list_moves > 0, "{at}: Tab scrolls the conversation list");
        // Each stop's ring, Tab round from the pane.
        show_overview(&panel, &pull, sizes, cx);
        let mut failures = Vec::new();
        sweep::walk(&app, cx, &at, interface, &mut failures);
        rings.extend(failures);
    }
    sweep::assert_whole_except(
        rings,
        &[
            (
                "13 pt in 461 × 490 at 13 pt, stop 21 by Tab (",
                "a clip cuts the right, bottom, left",
            ),
            (
                "18 pt in 461 × 490 at 18 pt, stop 21 by Tab (",
                "a clip cuts the right, bottom, left",
            ),
        ],
    );
}

/// Closing the panel with Escape after Tab has scrolled a PR's Overview and a click has put
/// focus on the conversations pane, and opening it again, restores focus to the pane, which
/// draws its keyboard ring on its edge with its top edge drawn inside the body's clip, the
/// room a ring takes clear of it: in a 461 × 490 window, at 13 and 18 pt, the pane is
/// taller than the body, its top above the body's top as the panel closes, and once showed
/// its bottom with its top above the clip. In a 1,480 × 800 window the pane fits, and its
/// ring is whole. The click moves nothing. Closed with Tab's focus on the first
/// conversation's Reply and the body then scrolled until Reply lies outside it, the panel
/// holds no control and reopens onto Overview's first stop, the pane, its ring's top edge
/// drawn the same way. Closed on Reply in view, the panel once gave focus to the pane only
/// because the Button's handle went with the closed dialog's frame; it now gives it back to
/// Reply (`reopening_gives_focus_back_to_a_body_button`).
#[gpui::test]
async fn a_reopened_prs_conversations_pane_draws_its_rings_top_edge(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    let (section, scroll) = cx.read(|cx| {
        let panel = panel.read(cx);
        (
            panel.review.section_focus.clone(),
            panel.review.body_scroll.clone(),
        )
    });
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let mut fell_back = 0;
    for sizes in REVEAL_SIZES {
        // Held on the pane, and held on nothing, reopened with a key as the last input and
        // by a click on the header's Pull requests, where only the reopen's own reveal
        // shows the pane: its parts reveal focus after a key alone.
        for (fallback, clicked) in [(false, false), (true, false), (true, true)] {
            let (interface, width, height) = sizes;
            let at = format!(
                "{interface} pt in {width} × {height}{}{}",
                if fallback { ", Reply out of view" } else { "" },
                if clicked { ", reopened by a click" } else { "" }
            );
            show_overview(&panel, &pull, sizes, cx);
            // Into the conversation list, scrolling the body down to it.
            cx.simulate_keystrokes("tab tab");
            for _ in 0..3 {
                crate::width_walk::frame(cx);
            }
            let body = cx.debug_bounds("github-panel").expect("the body");
            if fallback {
                // The body moves until the conversation list, the part holding Reply,
                // which holds focus, lies outside it, so closing holds no control.
                let list = cx
                    .debug_bounds("github-part-conversation-list")
                    .expect("the conversation list");
                let outside = |part: Bounds<Pixels>| {
                    part.bottom() <= body.top() || part.top() >= body.bottom()
                };
                let y = scroll.offset().y;
                let Some(target) = [px(0.), -scroll.max_offset().y]
                    .into_iter()
                    .find(|target| outside(list + point(px(0.), *target - y)))
                else {
                    // The body shows the list wherever it scrolls.
                    assert!(
                        width > 1000.,
                        "{at}: the body can move the list out of view"
                    );
                    continue;
                };
                scroll.set_offset(point(px(0.), target));
                for _ in 0..3 {
                    crate::width_walk::frame(cx);
                }
                let list = cx
                    .debug_bounds("github-part-conversation-list")
                    .expect("the conversation list");
                assert!(
                    outside(list),
                    "{at}: the list {list:?} lies outside the body {body:?}"
                );
                fell_back += 1;
            } else {
                if width < 1000. {
                    // On past the pane's top, which Tab left 96 px inside the body at 13 pt:
                    // the pane this test is for has its top above the body as it closes.
                    scroll.set_offset(point(
                        px(0.),
                        (scroll.offset().y - px(120.)).max(-scroll.max_offset().y),
                    ));
                    for _ in 0..3 {
                        crate::width_walk::frame(cx);
                    }
                }
                let pane = cx.debug_bounds("github-thread-section").expect("the pane");
                if width < 1000. {
                    assert!(
                        pane.top() < body.top(),
                        "{at}: the pane's top {pane:?} lies above the body's {body:?}"
                    );
                }
                // A click on the pane's edge, beside the list, puts focus on the pane and
                // moves nothing: only the keyboard reveals.
                let offset = scroll.offset().y;
                let (top, bottom) = (pane.top().max(body.top()), pane.bottom().min(body.bottom()));
                cx.simulate_click(
                    point(pane.left() + px(2.), (top + bottom) / 2.),
                    Modifiers::default(),
                );
                crate::width_walk::frame(cx);
                assert!(
                    cx.update(|window, _| section.is_focused(window)),
                    "{at}: the click puts focus on the pane"
                );
                assert_eq!(scroll.offset().y, offset, "{at}: the click moves nothing");
                let moved = cx.debug_bounds("github-thread-section").expect("the pane");
                assert_eq!(moved, pane, "{at}: the click leaves the pane where it was");
            }
            escape(cx);
            assert!(
                !cx.update(|window, cx| window.has_active_dialog(cx)),
                "{at}: Escape closes the panel"
            );
            if clicked {
                crate::copy_feedback::tests::click(cx, "pull-requests");
                settle_panel(&app, cx).await;
                assert!(
                    cx.update(|window, _| !window.last_input_was_keyboard()),
                    "{at}: a pointer press is the last input"
                );
            } else {
                cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
            }
            for _ in 0..4 {
                crate::width_walk::frame(cx);
            }
            assert!(
                cx.update(|window, _| section.is_focused(window)),
                "{at}: the reopened panel restores focus to the conversations pane"
            );
            let (body, pane) = (
                cx.debug_bounds("github-panel").expect("the body"),
                cx.debug_bounds("github-thread-section").expect("the pane"),
            );
            let accent: Hsla = cx.read(|cx| rgb(palette(cx).accent).into());
            let rings: Vec<_> = crate::focus_ring::painted_outlines(cx, accent)
                .into_iter()
                .filter(|ring| near(ring.bounds, pane))
                .collect();
            let [ring] = rings[..] else {
                panic!("{at}: one ring on the pane's edge {pane:?}: {rings:?}");
            };
            assert!(
                ring.sides[0] && pane.top() >= body.top() + room - px(0.5),
                "{at}: the ring's top edge lies inside the body {body:?}, its room clear: \
                 {ring:?}"
            );
            // The case the narrow window is here for: a pane taller than the body, which a
            // taller body would otherwise turn into a pane that fits without failing.
            if width < 1000. {
                assert!(
                    pane.size.height + room * 2. > body.size.height,
                    "{at}: the pane {pane:?} is taller than the body {body:?}"
                );
            }
            if pane.size.height + room * 2. <= body.size.height {
                assert!(
                    ring.whole,
                    "{at}: the pane fits, and its ring is whole: {ring:?}"
                );
            }
            if width > 1000. {
                assert!(
                    ring.whole,
                    "{at}: the wide window fits the pane whole: {ring:?}"
                );
            }
        }
    }
    assert!(
        fell_back >= 2,
        "the narrow windows move the conversation list out of the body"
    );
}

/// The panel closed with its body scrolled to its end reopens onto its destination field
/// with the body back at its top, at 13 and 18 pt in a 461 × 490 window: the field whole
/// with its ring and the banner above it in view, rather than at the offset it closed at:
/// at 13 pt it reopened 93 px down, the field just inside the body's top edge and the
/// banner above it hidden, since the field alone was whole and nothing revealed more.
#[gpui::test]
async fn reopening_after_scrolling_returns_the_body_to_its_top(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, cx) = notice_panel(cx);
    let (scroll, field) = cx.read(|cx| {
        let panel = panel.read(cx);
        (
            panel.review.body_scroll.clone(),
            panel.destination.read(cx).focus_handle(cx),
        )
    });
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let mut scrolled = 0;
    for interface in [13, 18] {
        let at = format!("{interface} pt");
        open_notice_panel(&app, &panel, (interface, 461., 490.), cx).await;
        if scroll.max_offset().y <= px(0.) {
            escape(cx);
            continue;
        }
        scrolled += 1;
        scroll.set_offset(point(px(0.), -scroll.max_offset().y));
        draw(cx);
        draw(cx);
        escape(cx);
        cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
        settle_panel(&app, cx).await;
        for _ in 0..3 {
            draw(cx);
        }
        assert!(
            cx.update(|window, _| field.is_focused(window)),
            "{at}: the panel reopens onto its destination field"
        );
        assert_eq!(
            scroll.offset().y,
            px(0.),
            "{at}: the body is back at its top"
        );
        let body = cx.debug_bounds("github-panel").expect("the body");
        let destination = cx
            .debug_bounds("github-destination")
            .expect("the destination field");
        let banner = cx.debug_bounds("github-fixture-mode").expect("the banner");
        assert!(
            destination.top() - room >= body.top()
                && destination.bottom() + room <= body.bottom()
                && banner.top() >= body.top(),
            "{at}: the field {destination:?} with its ring and the banner {banner:?} lie in \
             view in {body:?}"
        );
        escape(cx);
    }
    assert!(scrolled > 0, "some size scrolls the body");
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// With no PR open, a Button of the body that held focus as Escape closed the panel takes
/// it back as a click on the header's Pull requests reopens it, the body where it closed:
/// Refresh PRs and Connect GitHub CLI account, each reached by Tab and the body then
/// scrolled on as far as keeps the Button whole with its ring's room, at 13 and 18 pt in a
/// 461 × 490 window. Every frame the reopened panel draws shows the Button whole with its
/// ring's room, and the last draws its ring. The reopen took the body back to its top,
/// as it does for its destination field, before it restored the Button: at 13 pt Refresh
/// PRs, closed with the body 32.5 px down, came back with the body at its top. A window
/// shortened while the panel is closed can leave the Button wholly out of view; the focus
/// that falls to the destination field then shows the body from its top.
#[gpui::test]
async fn reopening_onto_a_held_button_with_no_pr_keeps_the_body_where_it_closed(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::draw;
    let (_fixture, app, cx) = repository_window(cx);
    // Tab's bindings, the installed focus ring and motion at rest.
    crate::focus_ring::sweep::prepare(&app, cx);
    let panel = cx.update(|window, cx| {
        let repo = app.read(cx).repository.clone().unwrap();
        let panel = cx.new(|cx| Panel::new(app.downgrade(), repo, "main".into(), window, cx));
        panel.update(cx, |panel, cx| panel.close(window, cx));
        panel
    });
    let scroll = panel.read_with(cx, |panel, _| panel.review.body_scroll.clone());
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let whole = |part: Bounds<Pixels>, view: Bounds<Pixels>| {
        part.top() - room >= view.top() - px(0.5) && part.bottom() + room <= view.bottom() + px(0.5)
    };
    let focused = |cx: &mut VisualTestContext, id: &'static str| {
        let focus = panel.read_with(cx, |panel, _| panel.review.buttons.kept(id));
        cx.update(|window, _| focus.is_some_and(|focus| focus.is_focused(window)))
    };
    let frames = |cx: &mut VisualTestContext| {
        for _ in 0..4 {
            crate::width_walk::frame(cx);
        }
    };
    let mut scrolled = 0;
    for interface in [13u8, 18] {
        for (id, part) in [("github-refresh", "refresh"), ("github-connect", "connect")] {
            let at = format!("{id} at {interface} pt in 461 × 490");
            cx.update(|window, cx| appearance::apply_text_sizes(interface, 12, window, cx));
            cx.simulate_resize(size(px(461.), px(490.)));
            draw(cx);
            open_panel(&app, cx).await;
            if !panel.read_with(cx, |panel, _| panel.review.connection_open) {
                crate::copy_feedback::tests::click(cx, "github-account-options");
                cx.run_until_parked();
            }
            // Tab from the destination field, the body at its top.
            cx.update(|window, cx| {
                panel.update(cx, |panel, cx| panel.focus_visible_section(window, cx))
            });
            scroll.set_offset(point(px(0.), px(0.)));
            frames(cx);
            let mut stops = 0;
            while !focused(cx, id) {
                stops += 1;
                assert!(stops <= 12, "{at}: Tab reaches the Button");
                cx.simulate_keystrokes("tab");
                frames(cx);
            }
            let body = cx.debug_bounds("github-panel").expect("the body");
            let button = cx.debug_bounds(id).expect(id);
            let y = (scroll.offset().y - (button.top() - room - body.top()))
                .clamp(-scroll.max_offset().y, px(0.));
            scroll.set_offset(point(px(0.), y));
            frames(cx);
            let closed = scroll.offset().y;
            let button = cx.debug_bounds(id).expect(id);
            assert!(
                whole(button, body) && ringed(cx, id),
                "{at}: the body {body:?} shows the Button {button:?} whole with its ring at \
                 {closed:?} as the panel closes"
            );
            if closed < px(0.) {
                scrolled += 1;
            }
            escape(cx);
            assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
            review::BODY_FRAMES.set(Some(Vec::new()));
            crate::copy_feedback::tests::click(cx, "pull-requests");
            settle_panel(&app, cx).await;
            frames(cx);
            let drawn = review::BODY_FRAMES.take().expect("watched");
            assert!(focused(cx, id), "{at}: the Button takes focus back");
            assert!(
                drawn.len() >= 2,
                "{at}: the reopened panel drew {} frames",
                drawn.len()
            );
            for (index, frame) in drawn.iter().enumerate() {
                let (_, shown) = frame
                    .parts
                    .iter()
                    .find(|(name, _)| name == part)
                    .unwrap_or_else(|| panic!("{at}: frame {index} draws {part}: {frame:?}"));
                assert!(
                    whole(*shown, frame.view),
                    "{at}: frame {index} draws the Button {shown:?} whole in {:?}",
                    frame.view
                );
            }
            assert_eq!(
                scroll.offset().y,
                closed,
                "{at}: the body stays where it closed"
            );
            assert!(ringed(cx, id), "{at}: the Button draws its ring");
            escape(cx);
        }
    }
    assert!(scrolled > 0, "some case closes with the body scrolled");

    // A Button the window's shortening puts wholly below the body cannot be revealed, so
    // focus falls to the destination field, and the body is at its top whatever offset it
    // closed at: at 13 pt, the offline fixture's banner above the field, Copy sign-in command
    // held with the body scrolled as far as keeps the field whole with its ring, and the
    // window going from 490 to 420 px while the panel is closed. The field needed no reveal
    // where the body closed, so the body stayed there, the banner above it out of view.
    // (Without the banner the field is the body's first part, and revealing it reaches the
    // top by itself.)
    let id = "github-sign-in-help";
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    cx.simulate_resize(size(px(461.), px(490.)));
    draw(cx);
    open_panel(&app, cx).await;
    panel.update(cx, |panel, cx| {
        panel.review.fixture = true;
        panel.review.connection_open = true;
        cx.notify();
    });
    scroll.set_offset(point(px(0.), px(0.)));
    frames(cx);
    let held = panel
        .read_with(cx, |panel, _| panel.review.buttons.kept(id))
        .expect("the panel keeps the Button's handle");
    cx.update(|window, cx| held.focus(window, cx));
    frames(cx);
    let body = cx.debug_bounds("github-panel").expect("the body");
    let field = cx.debug_bounds("github-destination").expect("the field");
    let closed = scroll.offset().y - (field.top() - room - body.top());
    assert!(closed < px(0.), "the banner lies above the field");
    scroll.set_offset(point(px(0.), closed));
    frames(cx);
    assert_eq!(scroll.offset().y, closed, "the body scrolls that far");
    let field = cx.debug_bounds("github-destination").expect("the field");
    let button = cx.debug_bounds(id).expect(id);
    assert!(
        whole(field, body) && button.top() < body.bottom() && button.bottom() > body.top(),
        "the body {body:?} shows the field {field:?} whole and the Button {button:?}"
    );
    escape(cx);
    assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
    cx.simulate_resize(size(px(461.), px(420.)));
    frames(cx);
    crate::copy_feedback::tests::click(cx, "pull-requests");
    settle_panel(&app, cx).await;
    frames(cx);
    let destination = panel.read_with(cx, |panel, cx| panel.destination.read(cx).focus_handle(cx));
    assert!(
        cx.update(|window, _| destination.is_focused(window)),
        "focus falls to the destination field"
    );
    assert_eq!(
        scroll.offset().y,
        px(0.),
        "the body, closed at {closed:?}, is at its top"
    );
    let body = cx.debug_bounds("github-panel").expect("the body");
    let field = cx.debug_bounds("github-destination").expect("the field");
    let banner = cx.debug_bounds("github-fixture-mode").expect("the banner");
    let accent: Hsla = cx.read(|cx| rgb(palette(cx).accent).into());
    let ring = crate::focus_ring::painted_outlines(cx, accent)
        .into_iter()
        .any(|ring| ring.whole && ring.bounds.contains(&field.center()));
    assert!(
        whole(field, body) && ring && banner.top() >= body.top(),
        "the field {field:?} is whole with its ring and the banner {banner:?} in view in \
         {body:?}"
    );
    escape(cx);
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// The destination field that held focus inside the body's view as Escape closed the panel
/// takes it back as the panel reopens, with the body at its top though it closed a little
/// scrolled and the field's ring whole, at 13 and 18 pt in a 461 × 490 window: the reopen
/// lands on the body's first part, as it does with nothing held
/// (`reopening_after_scrolling_returns_the_body_to_its_top`).
#[gpui::test]
async fn reopening_onto_the_held_destination_field_returns_the_body_to_its_top(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, cx) = notice_panel(cx);
    crate::focus_ring::sweep::prepare(&app, cx);
    let (scroll, field) = cx.read(|cx| {
        let panel = panel.read(cx);
        (
            panel.review.body_scroll.clone(),
            panel.destination.read(cx).focus_handle(cx),
        )
    });
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    let accent: Hsla = cx.read(|cx| rgb(palette(cx).accent).into());
    for interface in [13, 18] {
        let at = format!("{interface} pt");
        open_notice_panel(&app, &panel, (interface, 461., 490.), cx).await;
        assert!(
            cx.update(|window, _| field.is_focused(window)),
            "{at}: the panel opens onto its destination field"
        );
        assert!(scroll.max_offset().y > px(12.), "{at}: the body scrolls");
        scroll.set_offset(point(px(0.), px(-12.)));
        draw(cx);
        draw(cx);
        let body = cx.debug_bounds("github-panel").expect("the body");
        let shown = cx.debug_bounds("github-destination").expect("the field");
        assert!(
            shown.top() < body.bottom() && shown.bottom() > body.top(),
            "{at}: the field {shown:?} is in view in {body:?} as the panel closes"
        );
        escape(cx);
        assert!(
            panel.read_with(cx, |panel, _| panel
                .review
                .held
                .as_ref()
                .and_then(|held| held.upgrade())
                .is_some_and(|held| held == field)),
            "{at}: closing holds the field"
        );
        cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
        settle_panel(&app, cx).await;
        for _ in 0..3 {
            draw(cx);
        }
        assert!(
            cx.update(|window, _| field.is_focused(window)),
            "{at}: the field takes focus back"
        );
        assert_eq!(
            scroll.offset().y,
            px(0.),
            "{at}: the body is back at its top"
        );
        let body = cx.debug_bounds("github-panel").expect("the body");
        let shown = cx.debug_bounds("github-destination").expect("the field");
        let ring = crate::focus_ring::painted_outlines(cx, accent)
            .into_iter()
            .any(|ring| ring.whole && ring.bounds.contains(&shown.center()));
        assert!(
            ring && shown.top() - room >= body.top() - px(0.5)
                && shown.bottom() + room <= body.bottom() + px(0.5),
            "{at}: the field {shown:?} is whole with its ring in the body {body:?}"
        );
        escape(cx);
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Reopening the panel onto its destination field keeps the body at its top wherever the
/// field is whole there with its ring, as at 13 and 18 pt in a 461 × 490 window, so the
/// banner and its Move fixture head stay in view, whether a key or the pointer came last.
/// At 18 pt it scrolled the body down, by 129.5 px the field's row to its top, and the
/// banner out of view: the field kept a line's room clear of the body's edges rather than
/// its ring's, which alone scrolled 112 px, and after a key its row, taller than the body,
/// revealed itself rather than the field. In a 461 × 360 window, where the field is not
/// whole at the body's top, reopening scrolls the body until it is. A PR's Review reopens
/// onto its summary, a field too: where the body shows it whole with its ring, at 13 pt in
/// a 461 × 490 window and 18 pt in a 1,480 × 800 one, the body stays where it was, where a
/// line's room clear of its edges scrolled it on.
#[gpui::test]
async fn reopening_onto_a_whole_field_keeps_the_body_at_its_top(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, cx) = notice_panel(cx);
    let (scroll, field) = cx.read(|cx| {
        let panel = panel.read(cx);
        (
            panel.review.body_scroll.clone(),
            panel.destination.read(cx).focus_handle(cx),
        )
    });
    let room = cx.update(|_, cx| appearance::button_ring_room(cx));
    for (interface, width, height) in [(13, 461., 490.), (18, 461., 490.), (18, 461., 360.)] {
        for pointer in [false, true] {
            let at = format!(
                "{interface} pt in {width} × {height}, reopened after the {}",
                if pointer { "pointer" } else { "keyboard" }
            );
            cx.update(|window, cx| appearance::apply_text_sizes(interface, 12, window, cx));
            cx.simulate_resize(size(px(width), px(height)));
            draw(cx);
            cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
            settle_panel(&app, cx).await;
            escape(cx);
            assert!(
                !cx.update(|window, cx| window.has_active_dialog(cx)),
                "{at}: Escape closes the panel"
            );
            // The body at its top, as a panel opens that nothing has scrolled.
            scroll.set_offset(point(px(0.), px(0.)));
            if pointer {
                cx.simulate_mouse_move(point(px(4.), px(4.)), None, Modifiers::default());
            }
            cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
            settle_panel(&app, cx).await;
            for _ in 0..3 {
                crate::width_walk::frame(cx);
            }
            assert!(
                cx.update(|window, _| field.is_focused(window)),
                "{at}: the panel reopens onto the destination field"
            );
            let offset = scroll.offset().y;
            let body = cx.debug_bounds("github-panel").expect("the body");
            let shown = cx.debug_bounds("github-destination").expect("the field");
            assert!(
                shown.top() - room >= body.top() - px(0.5)
                    && shown.bottom() + room <= body.bottom() + px(0.5),
                "{at}: the field {shown:?} is whole with its ring in the body {body:?}"
            );
            // Where the field lies with the body at its top.
            let (top, bottom) = (shown.top() - offset, shown.bottom() - offset);
            let whole_at_top =
                top - room >= body.top() - px(0.5) && bottom + room <= body.bottom() + px(0.5);
            assert_eq!(
                whole_at_top,
                height > 480.,
                "{at}: the field is whole at the body's top in the taller window only"
            );
            if whole_at_top {
                assert_eq!(offset, px(0.), "{at}: the body stays at its top");
                let banner = cx
                    .debug_bounds("github-fixture-move")
                    .expect("Move fixture head");
                assert!(
                    banner.top() >= body.top() && banner.bottom() <= body.bottom(),
                    "{at}: Move fixture head {banner:?} stays in view in {body:?}"
                );
            } else {
                assert!(offset < px(0.), "{at}: the body scrolls to the field");
            }
            escape(cx);
        }
    }

    // A PR's Review, reopened onto its summary where the body shows it whole with its
    // ring and less than a line's room below it.
    let summary = cx.read(|cx| panel.read(cx).body.read(cx).focus_handle(cx));
    cx.update(|_, cx| {
        panel.update(cx, |panel, _| {
            panel.pull = Some(github::review::fixture_pull(false));
            panel.review.section = Section::Review;
            panel.review.show_list = false;
        })
    });
    // Opened and closed once, so the draft status the destination's close left ("Draft
    // not saved: choose a pull request…", three lines at 13 pt in 461 × 490) gives way to
    // the PR's own, and nothing above the summary moves across the reopens below: the
    // status shrank by 39 px across the first one and took the summary out of the place
    // that leaves it less than a line's room.
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    settle_panel(&app, cx).await;
    escape(cx);
    for (interface, width, height) in [(13, 461., 490.), (18, 1480., 800.)] {
        for pointer in [false, true] {
            let at = format!(
                "Review at {interface} pt in {width} × {height}, reopened after the {}",
                if pointer { "pointer" } else { "keyboard" }
            );
            cx.update(|window, cx| appearance::apply_text_sizes(interface, 12, window, cx));
            cx.simulate_resize(size(px(width), px(height)));
            draw(cx);
            cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
            settle_panel(&app, cx).await;
            for _ in 0..3 {
                crate::width_walk::frame(cx);
            }
            let body = cx.debug_bounds("github-panel").expect("the body");
            let shown = cx
                .debug_bounds("github-review-summary")
                .expect("the summary");
            let line = cx.update(|window, _| window.rem_size()) + px(2.);
            let placed = (scroll.offset().y + (body.bottom() - room - px(1.) - shown.bottom()))
                .clamp(-scroll.max_offset().y, px(0.));
            scroll.set_offset(point(px(0.), placed));
            draw(cx);
            draw(cx);
            let shown = cx
                .debug_bounds("github-review-summary")
                .expect("the summary");
            assert!(
                shown.top() - room >= body.top()
                    && shown.bottom() + room <= body.bottom()
                    && shown.bottom() + line > body.bottom(),
                "{at}: the summary {shown:?} is whole with its ring in the body {body:?}, \
                 with less than a line's room below it"
            );
            escape(cx);
            if pointer {
                cx.simulate_mouse_move(point(px(4.), px(4.)), None, Modifiers::default());
            }
            cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
            settle_panel(&app, cx).await;
            for _ in 0..3 {
                crate::width_walk::frame(cx);
            }
            assert!(
                cx.update(|window, _| summary.is_focused(window)),
                "{at}: the panel reopens onto the summary"
            );
            assert_eq!(
                scroll.offset().y,
                placed,
                "{at}: the body stays where it was"
            );
            assert_eq!(
                cx.debug_bounds("github-review-summary"),
                Some(shown),
                "{at}: the summary stays where it was placed"
            );
            escape(cx);
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Switching a PR's section moves nothing already drawn: the body keeps its scrollbar's
/// gutter whether or not the section overflows, so the content's right edge, where the
/// Buttons and the draft status at the panel's right end, and the tabs stay put. At 13 pt
/// in a 1,480 × 980 window Overview overflows and Files fits, and the right edge moved
/// 19 px between them, the gutter's track and the ring's room.
#[gpui::test]
async fn switching_a_prs_section_moves_nothing(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    let captured = pull.capture(Repository::parse("gitturtle-fixture/native-review").unwrap());
    let files = Client(UiTransport::Fixture { moved: false })
        .files(&captured, 1, &OperationControl::default())
        .unwrap()
        .items;
    let scroll = cx.read(|cx| panel.read(cx).review.body_scroll.clone());
    // Whether some window showed one section overflowing and another fitting.
    let mut mixed = false;
    for (interface, width, height) in [
        (13, 1480., 980.),
        (18, 1480., 980.),
        (13, 1000., 680.),
        (18, 1000., 680.),
        (13, 461., 490.),
        (18, 461., 490.),
    ] {
        let at = format!("{interface} pt in {width} × {height}");
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(width), px(height)));
        cx.executor()
            .advance_clock(*gpui_kit::component::dialog::ANIMATION_DURATION);
        let mut drawn = Vec::new();
        for section in [
            Section::Overview,
            Section::Files,
            Section::Review,
            Section::Overview,
        ] {
            cx.update(|window, cx| {
                panel.update(cx, |panel, cx| {
                    panel.pull = Some(pull.clone());
                    panel.review.files = files.clone();
                    panel.review.show_list = false;
                    panel.change_section(section, window, cx);
                })
            });
            scroll.set_offset(point(px(0.), px(0.)));
            settle_panel(&app, cx).await;
            for _ in 0..2 {
                crate::width_walk::frame(cx);
            }
            let content = cx
                .debug_bounds("github-panel-content")
                .expect("the content");
            let tab = cx
                .debug_bounds("github-section-0")
                .expect("the Overview tab");
            drawn.push((
                section,
                content.right(),
                tab,
                scroll.max_offset().y > px(0.),
            ));
        }
        let overflows = drawn
            .iter()
            .filter(|(_, _, _, overflows)| *overflows)
            .count();
        mixed |= overflows > 0 && overflows < drawn.len();
        let (_, right, tab, _) = drawn[0];
        assert!(
            drawn
                .iter()
                .all(|(_, other, place, _)| *other == right && *place == tab),
            "{at}: switching sections moved the content's right edge or the tabs: {drawn:?}"
        );
    }
    assert!(
        mixed,
        "some window shows one section overflowing the body and another fitting it"
    );
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
}

/// Opening a PR from the list, by the keyboard, at 13 and 18 pt in a 461 × 490 window shows
/// it from its title: the title whole in the body with Overview, the tab it opens to and its
/// first stop, whole below it, and at 13 pt its captured identities too, where the PR once
/// opened showing only its title, the tabs below the fold (Overview's top at 464 px against
/// a body ending at 355.5 px at 13 pt). At 18 pt the tabs wrap, and Review's row lies below
/// the fold. In a 1,480 × 800
/// window, which shows all of that as it is, the body stays at its top, the controls and
/// notices above the PR in view.
#[gpui::test]
async fn opening_a_pr_shows_it_from_its_title(cx: &mut TestAppContext) {
    let (_fixture, app, panel, pull, cx) = fixture_panel(cx).await;
    let body_scroll = cx.read(|cx| panel.read(cx).review.body_scroll.clone());
    for (interface, width, height) in REVEAL_SIZES {
        let at = format!("{interface} pt in {width} × {height}");
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(width), px(height)));
        cx.update(|window, cx| {
            panel.update(cx, |panel, cx| {
                panel.pull = None;
                panel.review.show_list = true;
                panel.review.body_scroll.set_offset(point(px(0.), px(0.)));
                panel.focus_visible_section(window, cx);
                cx.notify();
            })
        });
        crate::width_walk::frame(cx);
        // The keyboard drives, as Return on a PR row does: focus reveals.
        cx.simulate_keystrokes("tab");
        crate::width_walk::frame(cx);
        body_scroll.set_offset(point(px(0.), px(0.)));
        cx.update(|window, cx| {
            panel.update(cx, |panel, cx| panel.inspect(pull.clone(), window, cx))
        });
        settle_panel(&app, cx).await;
        for _ in 0..3 {
            crate::width_walk::frame(cx);
        }
        assert!(
            cx.read(|cx| panel.read(cx).pull.is_some() && !panel.read(cx).review.show_list),
            "{at}: the PR opened"
        );
        let body = cx.debug_bounds("github-panel").expect("the body");
        let inside = |bounds: Bounds<Pixels>| {
            bounds.top() >= body.top() - px(0.5) && bounds.bottom() <= body.bottom() + px(0.5)
        };
        let title = cx.debug_bounds("github-pull-title").expect("the title");
        assert!(
            inside(title),
            "{at}: the title {title:?} lies whole in the body {body:?}"
        );
        let overview = cx
            .debug_bounds("github-section-0")
            .expect("the Overview tab");
        assert!(
            inside(overview),
            "{at}: Overview {overview:?}, the PR's first stop, lies whole in the body \
             {body:?}, below the title {title:?} and the branches {:?}",
            cx.debug_bounds("github-branch-context")
        );
        if interface == 13 {
            // And the summary of what the PR compares, below the tabs.
            let identities = cx
                .debug_bounds("github-captured-identities")
                .expect("the captured identities");
            assert!(
                inside(identities),
                "{at}: the captured identities {identities:?} lie whole in the body {body:?}"
            );
        }
        if width > 1000. {
            assert_eq!(
                body_scroll.offset().y,
                px(0.),
                "{at}: the wide window shows the PR without scrolling"
            );
        }
    }
}

/// Escape, the frame after the dialog closes, and the app's repair of
/// modal focus 300 ms later.
fn escape(cx: &mut VisualTestContext) {
    cx.simulate_keystrokes("escape");
    crate::tags::tests::draw(cx);
    crate::copy_feedback::tests::wait(cx, Duration::from_millis(400));
    crate::tags::tests::draw(cx);
}

/// The last frame's quads with their bounds in logical pixels.
fn quads(cx: &mut VisualTestContext) -> Vec<(Bounds<Pixels>, gpui_kit::Quad)> {
    cx.update(|window, _| {
        let scale = window.scale_factor();
        window
            .painted_quads()
            .into_iter()
            .map(|quad| {
                let b = quad.bounds;
                let bounds = Bounds::from_corners(
                    point(px(b.left().as_f32() / scale), px(b.top().as_f32() / scale)),
                    point(
                        px(b.right().as_f32() / scale),
                        px(b.bottom().as_f32() / scale),
                    ),
                );
                (bounds, quad)
            })
            .collect()
    })
}

/// The open panel's dialog frame as the last frame painted it, the smallest edged quad
/// around the body and the footer, with its cap's foot: [`DIALOG_MARGIN`] above the
/// status bar's top edge, where [`appearance::dialog_max_height`] ends a dialog.
///
/// [`DIALOG_MARGIN`]: appearance::DIALOG_MARGIN
pub(super) fn dialog_frame(cx: &mut VisualTestContext) -> (Bounds<Pixels>, Pixels) {
    let body = cx.debug_bounds("github-panel").expect("the body");
    let close = cx.debug_bounds("github-close").expect("Back to repository");
    let foot = cx.update(|window, _| {
        crate::theme_editor::status_bar_top(window) - appearance::DIALOG_MARGIN
    });
    let dialog = quads(cx)
        .into_iter()
        .filter(|(bounds, quad)| {
            let widths = quad.border_widths;
            [widths.top, widths.right, widths.bottom, widths.left]
                .iter()
                .all(|width| width.as_f32() > 0.)
                && bounds.top() < body.top()
                && bounds.bottom() > close.bottom()
                && bounds.left() < body.left()
                && bounds.right() > body.right()
        })
        .map(|(bounds, _)| bounds)
        .min_by(|a, b| a.size.height.partial_cmp(&b.size.height).unwrap())
        .expect("the dialog's frame");
    (dialog, foot)
}

fn near(a: Bounds<Pixels>, b: Bounds<Pixels>) -> bool {
    [
        (a.left(), b.left()),
        (a.top(), b.top()),
        (a.right(), b.right()),
        (a.bottom(), b.bottom()),
    ]
    .into_iter()
    .all(|(a, b)| (a - b).abs() < px(0.01))
}

/// The window painted the installed Button focus ring around `selector`.
fn ringed(cx: &mut VisualTestContext, selector: &'static str) -> bool {
    let control = cx.debug_bounds(selector).expect(selector);
    let (ring, color, scale) = cx.update(|window, cx| {
        let theme = gpui_kit::component::Theme::global(cx);
        let ring = theme.button_focus_ring;
        (ring, theme.ring.alpha(ring.opacity), window.scale_factor())
    });
    assert_eq!(ring, appearance::BUTTON_FOCUS_RING);
    let around = control.dilate(ring.gap + ring.width);
    quads(cx).into_iter().any(|(bounds, quad)| {
        quad.background.is_transparent()
            && quad.border_color == color
            && quad.border_widths.top.as_f32() == ring.width.as_f32() * scale
            && near(bounds, around)
    })
}

/// `selector` painted its 1 px keyboard-focus outline in the accent.
fn outlined(cx: &mut VisualTestContext, selector: &'static str) -> bool {
    let pane = cx.debug_bounds(selector).expect(selector);
    let (accent, scale) =
        cx.update(|window, cx| (Hsla::from(rgb(palette(cx).accent)), window.scale_factor()));
    quads(cx).into_iter().any(|(bounds, quad)| {
        quad.border_color == accent
            && quad.border_widths.top.as_f32() == scale
            && near(bounds, pane)
    })
}

/// The panel opened from the active repository's update, as command
/// palette activation opens it, with its local reads drained.
async fn open_panel(app: &Entity<GitTurtle>, cx: &mut VisualTestContext) {
    cx.update(|window, cx| {
        // This is the same parent-entity update boundary as command-palette
        // activation. The previous constructor synchronously reborrowed it.
        app.update(cx, |app, cx| app.open_github(window, cx));
        assert!(window.has_active_dialog(cx));
    });
    settle_panel(app, cx).await;
}

/// A closed panel whose local read has yet to run, for tests that reopen it.
fn closed_panel(app: &Entity<GitTurtle>, cx: &mut VisualTestContext) -> Entity<Panel> {
    cx.update(|window, cx| {
        let repo = app.read(cx).repository.clone().unwrap();
        let panel = cx.new(|cx| Panel::new(app.downgrade(), repo, "main".into(), window, cx));
        panel.update(cx, |panel, cx| panel.close(window, cx));
        panel
    })
}

/// A press of Pull requests while a cancelled read still drains opens the panel at once,
/// its own local read waiting behind the drain, and the button is neither dimmed nor
/// announced unavailable. The press once did nothing, with nothing said, until the drain
/// had ended.
#[gpui::test]
async fn pull_requests_opens_at_once_over_a_cancelled_read_still_draining(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    use crate::workspace::refusals;
    let (_fixture, app, cx) = repository_window(cx);
    let panel = closed_panel(&app, cx);
    draw(cx);
    for kind in [
        RequestKind::Load,
        RequestKind::Compare,
        RequestKind::Templates,
    ] {
        app.update(cx, |app, _| app.operation_busy = Some(kind.label()));
        draw(cx);
        let refusal = refusals::get("pull-requests").expect("the button is built");
        assert!(
            !refusal.announced && !refusal.dimmed,
            "{kind:?}: {refusal:?}"
        );
    }
    // The cancelled read, draining: it holds the executor and the busy spell.
    let held = app.update(cx, |app, _| app.operations.hold());
    app.update(cx, |app, _| {
        app.operation_busy = Some(RequestKind::Load.label())
    });
    draw(cx);
    crate::copy_feedback::tests::click(cx, "pull-requests");
    draw(cx);
    assert!(
        cx.update(|window, cx| window.has_active_dialog(cx)),
        "the panel opens at once"
    );
    panel.read_with(cx, |panel, _| {
        assert!(
            panel.local_loading && !panel.local_loaded,
            "its local read waits behind the drain"
        );
    });

    app.update(cx, |app, _| app.operation_busy = None);
    drop(held);
    settle_panel(&app, cx).await;
    assert!(
        panel.read_with(cx, |panel, _| panel.local_loaded),
        "and runs once the drain has ended"
    );
}

/// A press of Pull requests the panel cannot answer, while a Git write, an outbound action
/// or an account change runs, leaves things as they are and says why in the status line
/// and its live region, again for each press; and the panel never opens later by itself
/// once the work has ended and the person has moved on.
#[gpui::test]
async fn a_press_of_pull_requests_a_write_refuses_says_why_and_never_opens_later(
    cx: &mut TestAppContext,
) {
    use crate::native_accessibility::written;
    use crate::tags::tests::draw;
    use crate::workspace::{BUSY_REASON, refusals};
    let (_fixture, app, cx) = repository_window(cx);
    let opener = app.read_with(cx, |app, _| app.pull_requests_focus.clone());
    cx.update(|window, cx| window.focus(&opener, cx));
    draw(cx);
    let press = |cx: &mut VisualTestContext| {
        cx.update(|window, cx| app.update(cx, |app, cx| app.open_github_from_header(window, cx)));
        draw(cx);
    };
    let line = |cx: &mut VisualTestContext| {
        cx.update(|window, cx| app.update(cx, |app, cx| app.status_line_drawn(window, cx)))
    };
    let heard = || written::announced_from("github-open-refused");
    for (label, reason) in [
        ("Committing…", BUSY_REASON),
        (RequestKind::Send.label(), RequestKind::Send.reason()),
        (RequestKind::Connect.label(), RequestKind::Connect.reason()),
        (
            RequestKind::Disconnect.label(),
            RequestKind::Disconnect.reason(),
        ),
    ] {
        app.update(cx, |app, _| app.operation_busy = Some(label));
        draw(cx);
        assert!(
            refusals::get("pull-requests")
                .expect("the button")
                .announced,
            "{label}: announced unavailable"
        );
        press(cx);
        assert!(
            !cx.update(|window, cx| window.has_active_dialog(cx)),
            "{label}: stays refused"
        );
        let sentence = open_refused_sentence(reason);
        assert_eq!(line(cx), sentence, "{label}: the status line says why");
        let said = heard();
        assert_eq!(said.len(), 1, "{label}: {said:?}");
        assert_eq!(said[0].1.live, gpui::accesskit::Live::Polite, "{label}");
        assert_eq!(
            written::get(&said[0].0).and_then(|node| node.node.label().map(str::to_owned)),
            Some(sentence.to_string()),
            "{label}: spoken in full"
        );
        assert!(
            cx.update(|window, _| opener.is_focused(window)),
            "{label}: focus stays on the button"
        );
        let first = said[0].0.clone();
        press(cx);
        let again = heard();
        assert_eq!(again.len(), 1, "{label}: {again:?}");
        assert_ne!(again[0].0, first, "{label}: a fresh node for each press");
    }

    app.update(cx, |app, _| app.operation_busy = None);
    cx.executor()
        .advance_clock(crate::copy_feedback::RESTORE_AFTER + std::time::Duration::from_millis(50));
    draw(cx);
    assert!(
        !cx.update(|window, cx| window.has_active_dialog(cx)),
        "nothing opens once the work has ended"
    );
    assert!(heard().is_empty(), "the note goes as it lapses");
}

/// A press of Pull requests a write refuses is answered for the whole busy spell, by a
/// click and by Enter, once the button looks refused as before it; the button stays a Tab
/// stop and its tooltip gives the reason in both phases. Drawn `.disabled`, the kit's
/// Button dropped both presses 200 ms into a Fetch, so a keyboard or Orca user got nothing
/// for the rest of it, and Tab stepped over it.
#[gpui::test]
async fn a_refused_press_of_pull_requests_is_answered_for_the_whole_busy_spell(
    cx: &mut TestAppContext,
) {
    use crate::native_accessibility::written;
    use crate::tags::tests::draw;
    use crate::workspace::{BUSY_LOOK_DELAY, BUSY_REASON, refusals};
    let (_fixture, app, cx) = repository_window(cx);
    draw(cx);
    let opener = app.read_with(cx, |app, _| app.pull_requests_focus.clone());
    let heard = || written::announced_from("github-open-refused");
    // Says the press was answered: the panel stays shut, the line gives the reason and a
    // fresh live region, the only one, speaks it.
    let answered = |cx: &mut VisualTestContext, phase: &str, last: Option<String>| {
        draw(cx);
        assert!(
            !cx.update(|window, cx| window.has_active_dialog(cx)),
            "{phase}: stays refused"
        );
        assert_eq!(
            cx.update(|window, cx| app.update(cx, |app, cx| app.status_line_drawn(window, cx))),
            open_refused_sentence(BUSY_REASON),
            "{phase}: the status line says why"
        );
        let said = heard();
        assert_eq!(said.len(), 1, "{phase}: {said:?}");
        assert_eq!(said[0].1.live, gpui::accesskit::Live::Polite, "{phase}");
        assert_ne!(Some(&said[0].0), last.as_ref(), "{phase}: a fresh node");
        said[0].0.clone()
    };
    const TOOLTIP: &str =
        "pull-requests/tooltip/Pull requests: wait for the current Git operation to finish";
    let tooltip_shows = |cx: &mut VisualTestContext| {
        let button = cx.debug_bounds("pull-requests").expect("the button");
        cx.simulate_mouse_move(button.center(), None, Modifiers::default());
        cx.executor().advance_clock(Duration::from_millis(500));
        draw(cx);
        let shown = cx.debug_bounds(TOOLTIP).is_some();
        cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
        draw(cx);
        shown
    };

    app.update(cx, |app, _| app.operation_busy = Some("Fetching…"));
    draw(cx);
    assert_eq!(
        refusals::get("pull-requests"),
        Some(refusals::Refusal {
            announced: true,
            dimmed: false
        }),
        "refused at once, the look waiting"
    );
    assert!(tooltip_shows(cx), "the reason before the busy look");
    crate::copy_feedback::tests::click(cx, "pull-requests");
    let first = answered(cx, "a click before the busy look", None);

    cx.executor().advance_clock(BUSY_LOOK_DELAY);
    cx.run_until_parked();
    draw(cx);
    assert!(
        app.read_with(cx, |app, _| app.operation_shown().is_some()),
        "past the delay the spell looks busy"
    );
    assert_eq!(
        refusals::get("pull-requests"),
        Some(refusals::Refusal {
            announced: true,
            dimmed: true
        }),
        "announced and dimmed"
    );
    assert!(tooltip_shows(cx), "the reason once it looks busy");
    crate::copy_feedback::tests::click(cx, "pull-requests");
    let clicked = answered(cx, "a click once it looks busy", Some(first));

    // A Tab stop still: met going forward from the stop before it.
    cx.update(|window, cx| window.focus(&opener, cx));
    draw(cx);
    cx.simulate_keystrokes("shift-tab");
    draw(cx);
    assert!(
        !cx.update(|window, _| opener.is_focused(window)),
        "Shift+Tab leaves it"
    );
    cx.simulate_keystrokes("tab");
    draw(cx);
    assert!(
        cx.update(|window, _| opener.is_focused(window)),
        "Tab meets it while it looks busy"
    );
    let keystroke = gpui::Keystroke::parse("enter").unwrap();
    cx.simulate_event(gpui::KeyDownEvent {
        keystroke: keystroke.clone(),
        is_held: false,
        prefer_character_input: false,
    });
    cx.simulate_event(gpui::KeyUpEvent { keystroke });
    answered(cx, "Enter once it looks busy", Some(clicked));
    assert!(
        cx.update(|window, _| opener.is_focused(window)),
        "focus stays on the button"
    );
}

/// A refused press answers on the button too: its tooltip, resting there as the press lands,
/// stays through the press and reads the reason with its subject; the status line keeps it
/// for speech and history only while the panel is still refused, never after the write has
/// ended. It once hid with the press, and the reason stood 900 px away at the window's foot.
#[gpui::test]
async fn a_refused_press_of_pull_requests_answers_on_the_button(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    use crate::workspace::BUSY_REASON;
    let (_fixture, app, cx) = repository_window(cx);
    draw(cx);
    const TOOLTIP: &str =
        "pull-requests/tooltip/Pull requests: wait for the current Git operation to finish";
    let line = |cx: &mut VisualTestContext| {
        cx.update(|window, cx| app.update(cx, |app, cx| app.status_line_drawn(window, cx)))
    };
    app.update(cx, |app, _| app.operation_busy = Some("Fetching…"));
    draw(cx);

    let button = cx.debug_bounds("pull-requests").expect("the button");
    cx.simulate_mouse_move(button.center(), None, Modifiers::default());
    cx.executor().advance_clock(Duration::from_millis(500));
    draw(cx);
    assert!(cx.debug_bounds(TOOLTIP).is_some(), "the reason on hover");

    cx.simulate_click(button.center(), Modifiers::default());
    draw(cx);
    assert!(
        cx.debug_bounds(TOOLTIP).is_some(),
        "still shown after the press"
    );
    assert_eq!(
        line(cx),
        open_refused_sentence(BUSY_REASON),
        "the status line says it too, while the write runs"
    );

    // The write ends with the note still fresh: nothing goes on saying to wait for it.
    app.update(cx, |app, _| app.operation_busy = None);
    draw(cx);
    let idle = line(cx);
    assert_ne!(
        idle,
        open_refused_sentence(BUSY_REASON),
        "a stale refusal never outlasts the write"
    );
}

fn key_down(cx: &mut VisualTestContext, key: &str, is_held: bool) {
    cx.simulate_event(gpui::KeyDownEvent {
        keystroke: gpui::Keystroke::parse_with_os(key, crate::shortcuts::host_os()).unwrap(),
        is_held,
        prefer_character_input: false,
    });
}

fn key_up(cx: &mut VisualTestContext, key: &str) {
    cx.simulate_event(gpui::KeyUpEvent {
        keystroke: gpui::Keystroke::parse_with_os(key, crate::shortcuts::host_os()).unwrap(),
    });
}

/// The live regions that have said why a press of Pull requests could not open the panel.
fn refusals_heard() -> Vec<String> {
    crate::native_accessibility::written::announced_from("github-open-refused")
        .into_iter()
        .map(|(id, _)| id)
        .collect()
}

const REFUSED_SENTENCE: &str = "Pull requests: wait for the current Git operation to finish";
/// The text of Pull requests' tooltip as it says why the panel cannot open, the pointer's
/// and a keyboard press's answer alike.
const REFUSED_TOOLTIP: &str =
    "pull-requests/tooltip/Pull requests: wait for the current Git operation to finish";

/// The window with Pull requests reached by Tab and a write running, the window active, so
/// focus changes are reported and a blur heard.
fn refused_by_tab(
    cx: &mut TestAppContext,
) -> (
    tempfile::TempDir,
    Entity<GitTurtle>,
    FocusHandle,
    &mut VisualTestContext,
) {
    use crate::tags::tests::draw;
    let (fixture, app, cx) = repository_window(cx);
    cx.update(|window, _| window.activate_window());
    draw(cx);
    let opener = app.read_with(cx, |app, _| app.pull_requests_focus.clone());
    cx.update(|window, cx| window.focus(&opener, cx));
    draw(cx);
    cx.simulate_keystrokes("shift-tab");
    draw(cx);
    cx.simulate_keystrokes("tab");
    draw(cx);
    assert!(
        cx.update(|window, _| opener.is_focused(window)),
        "Tab reaches Pull requests"
    );
    app.update(cx, |app, cx| {
        app.operation_busy = Some("Fetching…");
        cx.notify();
    });
    draw(cx);
    (fixture, app, opener, cx)
}

/// Whether the answer a keyboard press of Pull requests stands at the button is drawn.
fn answer_drawn(cx: &mut VisualTestContext) -> bool {
    cx.debug_bounds("pull-requests-answer").is_some()
}

/// The kit's tooltip popups the last frame drew, in the window's logical pixels: the fill
/// each tooltip draws, in the kit's popover fill with the theme's rounded corners, its 1 px
/// border drawn inside it, so its bounds are the popup's drawn edge, wherever it stands and
/// on as many lines as it takes. The window's raised surfaces share the fill but are square.
fn kit_tooltip_popups(cx: &mut VisualTestContext) -> Vec<Bounds<Pixels>> {
    let popover = cx.read(|cx| {
        gpui_kit::Background::from(gpui_kit::component::Theme::global(cx).tokens.popover)
    });
    cx.update(|window, _| {
        let scale = window.scale_factor();
        let logical = |value: gpui::ScaledPixels| px(value.as_f32() / scale);
        window
            .painted_quads()
            .into_iter()
            .filter(|quad| {
                quad.background == popover && logical(quad.corner_radii.top_left) > px(0.)
            })
            .map(|quad| {
                Bounds::from_corners(
                    point(logical(quad.bounds.left()), logical(quad.bounds.top())),
                    point(logical(quad.bounds.right()), logical(quad.bounds.bottom())),
                )
            })
            .collect()
    })
}

/// The popups that say why Pull requests is refused, the pointer's tooltip and a keyboard
/// press's answer alike, at their drawn edges: each a kit tooltip popup
/// ([`kit_tooltip_popups`]) the popup's padding and its 1 px border larger than the reason's
/// text on every side, so a popup above the button or below it, wrapped at 18 pt, is
/// counted, and two that say it are both counted wherever each stands. Kept only where
/// wholly above the button and under 60 px tall, a popup below the button or wrapped went
/// uncounted.
fn tooltip_popups(cx: &mut VisualTestContext) -> Vec<Bounds<Pixels>> {
    let Some(text) = cx.debug_bounds(REFUSED_TOOLTIP) else {
        return Vec::new();
    };
    // The kit's tooltip popup: `px_2` and `py_0p5` inside its 1 px border.
    let (across, down) = cx.update(|window, _| {
        let rem = window.rem_size();
        (rem * 0.5 + px(1.), rem * 0.125 + px(1.))
    });
    let near = |a: Pixels, b: Pixels| (a - b).abs() <= px(1.);
    kit_tooltip_popups(cx)
        .into_iter()
        .filter(|popup| {
            near(popup.size.width, text.size.width + across * 2.)
                && near(popup.size.height, text.size.height + down * 2.)
        })
        .collect()
}

/// Asserts that the answer a keyboard press stands at Pull requests is one popup, the one
/// the answer's own element holds inside the kit's margin around the popup, whole in the
/// window 4 px clear of its edges, just above or just below the button, its drawn edge,
/// not its text, clear of the button's focus ring by the ring's room, and centred on the
/// button unless a side of the window holds it in. Returns the popup.
fn assert_answer_beside_button(cx: &mut VisualTestContext, at: &str) -> Bounds<Pixels> {
    let (room, window, margin) = cx.update(|window, cx| {
        (
            appearance::button_ring_room(cx),
            window.viewport_size(),
            // The popup's own margin inside the element the kit's positioner places.
            window.rem_size() * 0.75,
        )
    });
    let button = cx.debug_bounds("pull-requests").expect("the button");
    let popups = tooltip_popups(cx);
    assert_eq!(popups.len(), 1, "{at}: one popup says why: {popups:?}");
    let popup = popups[0];
    let held = cx
        .debug_bounds("pull-requests-answer")
        .unwrap_or_else(|| panic!("{at}: the answer is drawn"));
    let inside = Bounds::from_corners(
        held.origin + point(margin, margin),
        held.bottom_right() - point(margin, margin),
    );
    assert!(
        (inside.origin.x - popup.origin.x).abs() <= px(0.5)
            && (inside.origin.y - popup.origin.y).abs() <= px(0.5)
            && (inside.size.width - popup.size.width).abs() <= px(0.5)
            && (inside.size.height - popup.size.height).abs() <= px(0.5),
        "{at}: the popup {popup:?} is the answer's, inside its element {held:?}"
    );
    let above =
        popup.bottom() + room <= button.top() - room && popup.bottom() >= button.top() - px(32.);
    let below =
        popup.top() - room >= button.bottom() + room && popup.top() <= button.bottom() + px(32.);
    assert!(
        above || below,
        "{at}: the answer {popup:?} stands just above or just below the button {button:?}, \
         its drawn edge clear of the ring by the ring's {room:?}"
    );
    assert!(
        popup.left() >= px(4.)
            && popup.top() >= px(4.)
            && popup.right() <= window.width - px(4.)
            && popup.bottom() <= window.height - px(4.),
        "{at}: the answer {popup:?} lies whole in the {window:?} window"
    );
    let centred = (popup.center().x - button.center().x).abs() <= px(0.5);
    let side = px(4.) + margin + px(0.5);
    let held_in = popup.left() <= side || popup.right() >= window.width - side;
    assert!(
        centred || held_in,
        "{at}: the answer {popup:?} is centred on the button {button:?}"
    );
    popup
}

/// Return and Space on the focused Pull requests answer a refused press at the button, as a
/// click is answered under the pointer: reached by Tab, a write running, each pressed and
/// released before the spell looks busy and once it does, the reason stands in the button's
/// tooltip above it, clear of its ring, as the key goes down and through its release, focus
/// staying on the button; a fresh live region speaks it once for each press, and the key-up
/// says nothing more. The status line's note lapses after its 1.5 s and the answer stays,
/// focus still on the button, until Escape takes it away; that Escape does nothing else,
/// and the next goes on to the window's, which takes focus back to History. Return once
/// answered only in the status line at the window's foot, 900 px away, and then at the
/// button only for the status line's 1.5 s, too briefly to read.
#[gpui::test]
async fn a_refused_keyboard_press_of_pull_requests_answers_on_the_button(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    use crate::workspace::BUSY_LOOK_DELAY;
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    // Escape as the app binds it across the window, ahead of any key-down listener.
    cx.update(|_, cx| {
        cx.bind_keys([gpui::KeyBinding::new(
            "escape",
            crate::ClearSearch,
            Some("GitTurtle"),
        )])
    });
    let focused = |cx: &mut VisualTestContext| cx.update(|window, _| opener.is_focused(window));
    let mut last: Option<String> = None;
    for phase in ["before the busy look", "once it looks busy"] {
        if phase == "once it looks busy" {
            cx.executor().advance_clock(BUSY_LOOK_DELAY);
            cx.run_until_parked();
            draw(cx);
            assert!(
                app.read_with(cx, |app, _| app.operation_shown().is_some()),
                "past the delay the spell looks busy"
            );
        }
        for key in ["enter", "space"] {
            let at = format!("{key} {phase}");
            assert!(
                !answer_drawn(cx) && cx.debug_bounds(REFUSED_TOOLTIP).is_none(),
                "{at}: nothing stands at the button before the press"
            );
            key_down(cx, key, false);
            draw(cx);
            let button = cx.debug_bounds("pull-requests").expect("the button");
            assert!(answer_drawn(cx), "{at}: the reason stands at the button");
            let answer = assert_answer_beside_button(cx, &at);
            assert!(
                answer.bottom() <= button.top()
                    && (answer.center().x - button.center().x).abs() <= px(0.5),
                "{at}: the reason {answer:?} stands above the button {button:?}, centred on it"
            );
            let said = refusals_heard();
            assert_eq!(said.len(), 1, "{at}: {said:?}");
            assert_ne!(Some(&said[0]), last.as_ref(), "{at}: a fresh node");
            key_up(cx, key);
            draw(cx);
            assert!(
                !cx.update(|window, cx| window.has_active_dialog(cx)),
                "{at}: stays refused"
            );
            assert_eq!(refusals_heard(), said, "{at}: the key-up says nothing more");
            assert!(
                answer_drawn(cx),
                "{at}: the reason stays through the release"
            );
            assert!(focused(cx), "{at}: focus stays on the button");
            last = Some(said[0].clone());

            cx.executor()
                .advance_clock(crate::copy_feedback::RESTORE_AFTER + Duration::from_millis(50));
            draw(cx);
            assert!(
                refusals_heard().is_empty()
                    && app.read_with(cx, |app, _| app.github_refusal_line().is_none()),
                "{at}: the status line's note lapses"
            );
            assert!(
                answer_drawn(cx),
                "{at}: the reason stays at the button past the status line's note"
            );
            assert!(focused(cx), "{at}: focus stays on the button");

            cx.simulate_keystrokes("escape");
            draw(cx);
            assert!(!answer_drawn(cx), "{at}: Escape takes the reason away");
            assert!(focused(cx), "{at}: and does nothing else");
            cx.simulate_keystrokes("escape");
            draw(cx);
            assert!(
                !focused(cx),
                "{at}: the next Escape is the window's, which takes focus to History"
            );
            cx.update(|window, cx| window.focus(&opener, cx));
            draw(cx);
        }
    }
    app.update(cx, |app, _| app.operation_busy = None);
}

/// The answer a keyboard press stands at Pull requests keeps its drawn edge clear of the
/// button's focus ring at both ends of the sizes the app is checked at: at 13 pt in a
/// 1,480 × 973 window and at 18 pt in a 461 × 490 one, where the header wraps, Return on
/// the focused button draws one popup, just above or just below the button, whole in the
/// window, its edge, not its text, the ring's room clear of the ring
/// ([`assert_answer_beside_button`]). Measured at the text, which stands the popup's
/// padding and border inside that edge, a popup over the ring went unseen.
#[gpui::test]
async fn a_keyboard_answer_at_pull_requests_stands_clear_of_its_ring(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
        // Escape as the app binds it across the window, ahead of any key-down listener.
        cx.bind_keys([gpui::KeyBinding::new(
            "escape",
            crate::ClearSearch,
            Some("GitTurtle"),
        )]);
    });
    for (interface, width, height) in [(13, 1480., 973.), (18, 461., 490.)] {
        let at = format!("{interface} pt, {width} × {height}");
        crate::focus_ring::sweep::interface_size(cx, interface);
        cx.simulate_resize(size(px(width), px(height)));
        draw(cx);
        cx.update(|window, cx| window.focus(&opener, cx));
        draw(cx);
        key_down(cx, "enter", false);
        key_up(cx, "enter");
        draw(cx);
        assert_answer_beside_button(cx, &at);
        cx.simulate_keystrokes("escape");
        draw(cx);
        assert!(!answer_drawn(cx), "{at}: Escape ends the answer");
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    app.update(cx, |app, _| app.operation_busy = None);
}

/// `app`'s tab strip holding `count` repository tabs, its own repository's first and folders
/// beside it after, as a restored session holds them.
fn hold_tabs(
    app: &Entity<GitTurtle>,
    root: &std::path::Path,
    count: usize,
    cx: &mut VisualTestContext,
) {
    use crate::repository_tabs::{SavedPath, SavedTab, Session, State};
    app.update(cx, |app, cx| {
        let tabs = (0..count)
            .map(|index| SavedTab {
                path: SavedPath::Text(if index == 0 {
                    root.display().to_string()
                } else {
                    root.join(format!("held-{index}")).display().to_string()
                }),
                bookmark: Default::default(),
                unresolved: false,
                git_directories: None,
            })
            .collect();
        app.repository_tabs = State::from_session(Session {
            version: 1,
            tabs,
            active: 0,
            library: Vec::new(),
            groups: Vec::new(),
        });
        cx.notify();
    });
}

/// The header's and the tab strip's controls besides Pull requests that the last frame
/// drew, by name, each where the tab list's clip leaves it shown.
fn header_controls(cx: &mut VisualTestContext) -> Vec<(String, Bounds<Pixels>)> {
    let list = cx.debug_bounds("repository-tabs");
    let mut names = [
        "page-back",
        "repository-heading",
        "history-tab",
        "changes-tab",
        "cancel-git-operation",
        "projects",
        "profile-button",
        "settings",
        "main-menu",
        "new-repository-tab",
        "repository-workspaces",
    ]
    .map(String::from)
    .to_vec();
    for index in 0..8 {
        names.push(format!("repository-tab-{index}"));
        names.push(format!("repository-tab-close-{index}"));
    }
    names
        .into_iter()
        .filter_map(|name| {
            let bounds = cx.debug_bounds(name.clone().leak())?;
            let bounds = match list.filter(|_| name.starts_with("repository-tab-")) {
                Some(list) => bounds.intersect(&list),
                None => bounds,
            };
            (bounds.size.width > px(0.) && bounds.size.height > px(0.)).then_some((name, bounds))
        })
        .collect()
}

/// The controls in `controls` that `popup` covers by more than a pixel's rounding.
fn covered_by(
    popup: Bounds<Pixels>,
    controls: &[(String, Bounds<Pixels>)],
) -> Vec<(String, Bounds<Pixels>)> {
    controls
        .iter()
        .filter(|(_, control)| {
            let overlap = popup.intersect(control);
            overlap.size.width > px(0.5) && overlap.size.height > px(0.5)
        })
        .cloned()
        .collect()
}

/// The reason a refused press of Pull requests stands at the button covers none of the
/// header's and the tab strip's other controls, above the button where that side covers
/// none: at 13 pt in a 1,480 × 973 window, at 13 pt in a 461 × 490 one and at 18 pt in a
/// 461 × 490 one, where the header wraps, each with one repository tab and with four, Return
/// on the focused button draws the answer, its drawn edge clear of the return action, the
/// repository identity, History, Changes, the write's Cancel, Projects, the profile,
/// Settings, every tab and its close button, Menu, Open repository tab and Workspaces,
/// above the button with one tab at 13 pt in the 1,480 × 973 window and below it in every
/// other case, where above covers a tab or Changes; the pointer resting on the button once
/// Escape has taken the answer away draws its tooltip at exactly the same place, since the
/// kit's positioner places both. Placed above the button wherever it fitted, it covered the
/// tab strip's tabs for the whole write; drawn at a corner the answer computed, it stood
/// half a pixel from the pointer's tooltip.
#[gpui::test]
async fn a_refused_pull_requests_answer_covers_no_other_header_control(cx: &mut TestAppContext) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
        cx.bind_keys([gpui::KeyBinding::new(
            "escape",
            crate::ClearSearch,
            Some("GitTurtle"),
        )]);
    });
    use gpui_kit::base::Placement;
    let away = point(px(1.), px(1.));
    for (interface, width, height) in [(13, 1480., 973.), (13, 461., 490.), (18, 461., 490.)] {
        for tabs in [1, 4] {
            let at = format!("{interface} pt, {width} × {height}, {tabs} tabs");
            let side = if (interface, tabs) == (13, 1) && width == 1480. {
                Placement::Top
            } else {
                Placement::Bottom
            };
            hold_tabs(&app, fixture.path(), tabs, cx);
            crate::focus_ring::sweep::interface_size(cx, interface);
            cx.simulate_resize(size(px(width), px(height)));
            cx.simulate_mouse_move(away, None, Modifiers::default());
            draw(cx);
            cx.update(|window, cx| window.focus(&opener, cx));
            draw(cx);
            key_down(cx, "enter", false);
            key_up(cx, "enter");
            draw(cx);
            let answer = assert_answer_beside_button(cx, &at);
            let covered = covered_by(answer, &header_controls(cx));
            assert!(
                covered.is_empty(),
                "{at}: the answer {answer:?} covers {covered:?}"
            );
            let button = cx.debug_bounds("pull-requests").expect("the button");
            assert!(
                match side {
                    Placement::Top => answer.bottom() <= button.top(),
                    _ => answer.top() >= button.bottom(),
                },
                "{at}: the answer {answer:?} stands on the {side:?} side of the button \
                 {button:?}"
            );
            assert_eq!(
                app.read_with(cx, |app, _| app.github_refusal.side.get()),
                Some(side),
                "{at}: the side the pointer's tooltip takes"
            );

            // The pointer's tooltip there once the answer has gone.
            cx.simulate_keystrokes("escape");
            draw(cx);
            assert!(!answer_drawn(cx), "{at}: Escape ends the answer");
            let button = cx.debug_bounds("pull-requests").expect("the button");
            cx.simulate_mouse_move(button.center(), None, Modifiers::default());
            draw(cx);
            cx.executor().advance_clock(TOOLTIP_DELAY);
            cx.run_until_parked();
            draw(cx);
            cx.executor().advance_clock(Duration::from_millis(160));
            cx.run_until_parked();
            draw(cx);
            let pointer = tooltip_popups(cx);
            assert_eq!(pointer.len(), 1, "{at}: the pointer's tooltip says why");
            assert_eq!(
                pointer[0].origin, answer.origin,
                "{at}: the pointer's tooltip {:?} stands exactly where the answer stood \
                 {answer:?}",
                pointer[0]
            );
            cx.simulate_mouse_move(away, None, Modifiers::default());
            cx.executor().advance_clock(TOOLTIP_DELAY * 2);
            cx.run_until_parked();
            draw(cx);
        }
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    app.update(cx, |app, _| app.operation_busy = None);
}

/// The pointer's tooltip at Pull requests takes the side the reason's popup takes in the
/// frame that chooses it, also where its hover began before the panel was refused: at 13 pt
/// in a 1,480 × 973 window holding four repository tabs, the pointer resting on the button
/// past the kit's 500 ms show delay, its idle tooltip above it, a write that starts then
/// draws, in its first frame, the reason's popup on the side chosen below, where above
/// covers the tab strip's tabs, and the pointer's tooltip there, saying why, wholly below
/// the button; the next frames keep it there. The kit placed the tooltip from the frame its
/// hover began in, so it stayed above, over the tabs, for the whole write, and a hover that
/// began during the write took the side a frame late.
#[gpui::test]
async fn a_pointer_tooltip_shown_before_the_refusal_takes_the_answers_side_at_once(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    use gpui_kit::base::Placement;
    const IDLE: &str = "pull-requests/tooltip/Discover pull requests and review captured changes";
    let (fixture, app, cx) = repository_window(cx);
    cx.update(|window, cx| {
        window.activate_window();
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
    });
    hold_tabs(&app, fixture.path(), 4, cx);
    crate::focus_ring::sweep::interface_size(cx, 13);
    cx.simulate_resize(size(px(1480.), px(973.)));
    draw(cx);
    let button = cx.debug_bounds("pull-requests").expect("the button");
    cx.simulate_mouse_move(button.center(), None, Modifiers::default());
    draw(cx);
    cx.executor()
        .advance_clock(TOOLTIP_DELAY + Duration::from_millis(150));
    cx.run_until_parked();
    draw(cx);
    let idle = cx.debug_bounds(IDLE).expect("the idle tooltip shows");
    assert!(
        idle.bottom() <= button.top(),
        "the idle tooltip {idle:?} stands above the button {button:?}"
    );

    app.update(cx, |app, cx| {
        app.operation_busy = Some("Fetching…");
        cx.notify();
    });
    for frame in 0..3 {
        one_frame(cx);
        let side = app.read_with(cx, |app, _| app.github_refusal.side.get());
        assert_eq!(
            side,
            Some(Placement::Bottom),
            "frame {frame}: the reason's popup takes the side below, clear of the tabs"
        );
        let pointer = tooltip_popups(cx);
        let button = cx.debug_bounds("pull-requests").expect("the button");
        assert_eq!(
            pointer.len(),
            1,
            "frame {frame}: the pointer's tooltip says why"
        );
        assert!(
            pointer[0].top() >= button.bottom(),
            "frame {frame}: the pointer's tooltip {:?} stands below the button {button:?}",
            pointer[0]
        );
        let covered = covered_by(pointer[0], &header_controls(cx));
        assert!(
            covered.is_empty(),
            "frame {frame}: the pointer's tooltip {:?} covers {covered:?}",
            pointer[0]
        );
    }
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    app.update(cx, |app, _| app.operation_busy = None);
}

/// Where both sides of Pull requests would cover another control, the reason's popup takes
/// the side covering less of them, by area: a 200 × 40 popup, its drawn edge 12 px inside
/// at the 16 px rem, beside a 100 × 28 button with a 40 × 10 control under the drawn edge
/// above it and an 80 × 10 one under the drawn edge below it takes the top, and with the
/// two swapped the bottom. Always below, or below on a tie, fails one of these or the
/// cases where nothing is covered above.
#[gpui::test]
async fn the_pull_requests_answer_takes_the_side_covering_less(cx: &mut TestAppContext) {
    use gpui_kit::base::Placement;
    let cx = cx.add_empty_window();
    cx.update(|window, _| {
        window.set_rem_size(px(16.));
        let button = Bounds::new(point(px(400.), px(200.)), size(px(100.), px(28.)));
        let popup = size(px(200.), px(40.));
        // Centred on the button, in the drawn edge's rows above (172-188) or below (240-256).
        let control = |top: f32, width: f32| {
            Bounds::new(
                point(px(450. - width / 2.), px(top)),
                size(px(width), px(10.)),
            )
        };
        assert_eq!(
            pull_requests_answer_side(
                button,
                &[control(175., 40.), control(243., 80.)],
                popup,
                window
            ),
            Placement::Top,
            "less covered above"
        );
        assert_eq!(
            pull_requests_answer_side(
                button,
                &[control(175., 80.), control(243., 40.)],
                popup,
                window
            ),
            Placement::Bottom,
            "less covered below"
        );
    });
}

/// The answer a keyboard press stands at Pull requests hands the kit's tooltip overlay back
/// as it ends: the pointer meeting the button as Return goes down, before the frame that
/// answers the press, and leaving once the button offers no tooltip, then the write ending
/// past the kit's 500 ms show delay, no frame in the next 400 ms draws a popup, the reason
/// or the button's idle sentence. The button's request, left standing in the overlay as an
/// empty view, once drew its idle tooltip as the write ended, at a button the pointer had
/// left.
#[gpui::test]
async fn a_keyboard_answer_at_pull_requests_hands_the_tooltip_overlay_back(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (_fixture, app, _opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
    });
    cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
    draw(cx);
    let button = cx.debug_bounds("pull-requests").expect("the button");
    let at_button = |cx: &mut VisualTestContext| {
        [
            REFUSED_TOOLTIP,
            "pull-requests/tooltip/Discover pull requests and review captured changes",
            "pull-requests/tooltip/Pull requests · Discover pull requests and review captured \
             changes",
        ]
        .into_iter()
        .any(|tooltip| cx.debug_bounds(tooltip).is_some())
    };
    let tick = |cx: &mut VisualTestContext, by: Duration| {
        cx.executor().advance_clock(by);
        cx.run_until_parked();
        one_frame(cx);
    };

    // The pointer meets the button as the key goes down, before any frame answers it, and
    // leaves it once the button offers no tooltip.
    key_down(cx, "enter", false);
    cx.simulate_mouse_move(button.center(), None, Modifiers::default());
    key_up(cx, "enter");
    one_frame(cx);
    draw(cx);
    cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
    draw(cx);
    tick(cx, TOOLTIP_DELAY + Duration::from_millis(150));
    draw(cx);
    assert!(answer_drawn(cx), "the answer stands");
    let popups = kit_tooltip_popups(cx);
    assert_eq!(popups.len(), 1, "the answer's popup alone: {popups:?}");

    // The write ends, and the answer with it.
    app.update(cx, |app, cx| {
        app.operation_busy = None;
        cx.notify();
    });
    one_frame(cx);
    for step in 0..=8 {
        let at = format!("{} ms after the write", step * 50);
        assert!(!answer_drawn(cx), "{at}: the answer has gone");
        assert!(!at_button(cx), "{at}: no tooltip stands at Pull requests");
        let popups = kit_tooltip_popups(cx);
        assert!(popups.is_empty(), "{at}: no popup: {popups:?}");
        tick(cx, Duration::from_millis(50));
    }
}

/// Return going down on the focused Pull requests and the pointer meeting the button at `at`
/// in the answer's first frame, the one that still offers a pointer tooltip, before the next
/// is drawn, then Return coming up. The harness draws a window again and again once it has
/// handled an event, until nothing more asks for a frame, so a move simulated after the key
/// lands on the answer's second frame, as a person's move after the first 16 ms does.
fn meet_in_the_answers_first_frame(cx: &mut VisualTestContext, at: Point<Pixels>) {
    cx.update(|window, cx| {
        window.dispatch_event(
            gpui::PlatformInput::KeyDown(gpui::KeyDownEvent {
                keystroke: gpui::Keystroke::parse("enter").unwrap(),
                is_held: false,
                prefer_character_input: false,
            }),
            cx,
        );
        window.simulate_next_frame(cx);
        window.draw(cx).clear(cx);
        window.dispatch_event(
            gpui::PlatformInput::MouseMove(gpui::MouseMoveEvent {
                position: at,
                modifiers: Modifiers::default(),
                pressed_button: None,
            }),
            cx,
        );
    });
    key_up(cx, "enter");
}

/// The window at 13 pt and 461 × 490, where the header draws its full form wrapped onto two
/// rows, Pull requests and Settings sharing the second; its History and Changes are labelled
/// buttons, which offer no tooltip.
fn wrapped_full_header(cx: &mut VisualTestContext) {
    crate::focus_ring::sweep::interface_size(cx, 13);
    cx.simulate_resize(size(px(461.), px(490.)));
    crate::tags::tests::draw(cx);
    let settings = cx.debug_bounds("settings").expect("Settings");
    let button = cx.debug_bounds("pull-requests").expect("the button");
    assert!(
        settings.top() < button.bottom() && settings.bottom() > button.top(),
        "the wrapped full header's Settings {settings:?} shares Pull requests' row {button:?}"
    );
}

/// The window at 18 pt and 461 × 490, where the header draws its compact form: History and
/// Changes are glyph toggles beside Pull requests, each with its tooltip, its nearest
/// neighbours.
fn compact_form_header(cx: &mut VisualTestContext) {
    crate::focus_ring::sweep::interface_size(cx, 18);
    cx.simulate_resize(size(px(461.), px(490.)));
    crate::tags::tests::draw(cx);
    let toggles = ["history-tab", "changes-tab"].map(|toggle| cx.debug_bounds(toggle));
    let button = cx.debug_bounds("pull-requests").expect("the button");
    assert!(
        toggles.iter().all(|toggle| toggle.is_some_and(|toggle| {
            toggle.size.width == toggle.size.height
                && toggle.top() < button.bottom()
                && toggle.bottom() > button.top()
        })),
        "the compact form's glyph toggles {toggles:?} share Pull requests' row {button:?}"
    );
}

/// A form of the header ([`header_forms`]): its name, the function that lays it out, and the
/// neighbours of Pull requests a test hovers there.
type HeaderForm = (&'static str, fn(&mut VisualTestContext), [&'static str; 2]);

/// The header's two forms beside Pull requests at 461 × 490, each laid out by its function,
/// with the neighbours whose tooltips a test hovers there, a first and a second: the wrapped
/// full header's Settings, on the button's row, at 13 pt, the form a window takes at
/// typical sizes, and the compact form's Changes and History glyph toggles at 18 pt.
fn header_forms() -> [HeaderForm; 2] {
    [
        (
            "the wrapped full header",
            wrapped_full_header,
            ["settings", "settings"],
        ),
        (
            "the compact form",
            compact_form_header,
            ["changes-tab", "history-tab"],
        ),
    ]
}

/// Lays out the header in `form` with a write running again and Pull requests focused, the
/// pointer away from the header and past the kit's grace period, so a test of one form
/// starts as the first did.
fn rearm_in_form(
    app: &Entity<GitTurtle>,
    opener: &FocusHandle,
    form: fn(&mut VisualTestContext),
    cx: &mut VisualTestContext,
) {
    cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
    cx.executor()
        .advance_clock(crate::tags::tests::TOOLTIP_DELAY * 2);
    cx.run_until_parked();
    form(cx);
    cx.update(|window, cx| window.focus(opener, cx));
    app.update(cx, |app, cx| {
        app.operation_busy = Some("Fetching…");
        cx.notify();
    });
    crate::tags::tests::draw(cx);
}

/// The kit tooltip popups the last frame drew besides the ones that say why Pull requests
/// is refused ([`tooltip_popups`]).
fn neighbour_popups(cx: &mut VisualTestContext) -> Vec<Bounds<Pixels>> {
    let answers = tooltip_popups(cx);
    kit_tooltip_popups(cx)
        .into_iter()
        .filter(|popup| !answers.contains(popup))
        .collect()
}

/// Another control's tooltip keeps its own show delay beside a keyboard press's answer at
/// Pull requests and survives the answer's end, in both of the header's forms at 461 × 490
/// ([`header_forms`]): the pointer resting on the button, its tooltip saying why, as Return
/// goes down, resting there past the kit's 500 ms show delay while the answer stands, then
/// moving on to the neighbour, the wrapped full header's Settings at 13 pt or the compact
/// form's Changes glyph toggle at 18 pt, its tooltip shows beside the answer only once its
/// own delay has passed, and stays while the pointer rests there as the write ends and
/// takes the answer away. The button's leaving once hid whatever the kit's overlay held,
/// the neighbour's tooltip with it; an empty tooltip the button offered under the resting
/// pointer brought the neighbour's at once, sliding from Pull requests; and a button that
/// offered no tooltip from the answer's first frame kept the hover GPUI last told it of,
/// which the answer's end then ended, hiding the neighbour's tooltip.
#[gpui::test]
async fn a_neighbours_tooltip_survives_a_keyboard_answer_at_pull_requests(cx: &mut TestAppContext) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
    });
    let tick = |cx: &mut VisualTestContext, by: Duration| {
        cx.executor().advance_clock(by);
        cx.run_until_parked();
        draw(cx);
    };
    for (form, lay_out, [neighbour, _]) in header_forms() {
        rearm_in_form(&app, &opener, lay_out, cx);
        let (button, neighbour) = (
            cx.debug_bounds("pull-requests").expect("the button"),
            cx.debug_bounds(neighbour).expect("the neighbour"),
        );

        // The pointer rests on the button, whose tooltip says why, and Return goes down.
        cx.simulate_mouse_move(button.center(), None, Modifiers::default());
        draw(cx);
        tick(cx, TOOLTIP_DELAY + Duration::from_millis(150));
        assert_eq!(
            tooltip_popups(cx).len(),
            1,
            "{form}: the pointer's tooltip says why"
        );
        key_down(cx, "enter", false);
        key_up(cx, "enter");
        draw(cx);
        assert!(answer_drawn(cx), "{form}: the reason stands at the button");

        // The pointer rests on the button past the show delay and the slide.
        cx.simulate_mouse_move(
            button.center() + point(px(2.), px(0.)),
            None,
            Modifiers::default(),
        );
        draw(cx);
        tick(cx, TOOLTIP_DELAY + Duration::from_millis(150));
        assert_eq!(
            tooltip_popups(cx).len(),
            1,
            "{form}: the answer alone says why"
        );
        let beside = neighbour_popups(cx);
        assert!(
            beside.is_empty(),
            "{form}: nothing stands beside the answer: {beside:?}"
        );

        // On to the neighbour.
        cx.simulate_mouse_move(neighbour.center(), None, Modifiers::default());
        draw(cx);
        tick(cx, TOOLTIP_DELAY - Duration::from_millis(50));
        assert!(answer_drawn(cx), "{form}: the answer stays");
        let beside = neighbour_popups(cx);
        assert!(
            beside.is_empty(),
            "{form}: the neighbour's tooltip waits its show delay: {beside:?}"
        );
        tick(cx, Duration::from_millis(100));
        assert_eq!(
            neighbour_popups(cx).len(),
            1,
            "{form}: then the neighbour's tooltip shows beside the answer"
        );

        // The write ends, and the answer with it.
        app.update(cx, |app, cx| {
            app.operation_busy = None;
            cx.notify();
        });
        draw(cx);
        assert!(!answer_drawn(cx), "{form}: the answer goes with the write");
        for step in 0..=6 {
            tick(cx, Duration::from_millis(100));
            assert_eq!(
                kit_tooltip_popups(cx).len(),
                1,
                "{form}, {} ms after the write: the neighbour's tooltip stays",
                step * 100 + 100
            );
        }
    }
}

/// An answer a keyboard press stands at Pull requests that ends within the kit's show delay
/// of the pointer meeting the button leaves no tooltip there, in both of the header's forms
/// at 461 × 490 ([`header_forms`]): Return on the focused button, the pointer meeting it in
/// the answer's first frame, the one that still offers a tooltip, and leaving it in the
/// next, which offers none, then the write ending 200 ms after the pointer met the button,
/// no frame in the next 600 ms draws a popup, the reason or the button's idle sentence, and
/// a hover on a neighbour then waits out the whole show delay; and in another write, the
/// pointer meeting the button in the answer's first frame and leaving it, the show coming
/// due while the answer stands draws nothing, and a hover on a neighbour still waits out
/// the whole delay. The neighbours are the wrapped full header's Settings at 13 pt, twice,
/// and the compact form's Changes and then History glyph toggles at 18 pt. The show the
/// pointer asked for was still waiting as the answer ended, and once its delay was up drew
/// the button's idle tooltip at a button the pointer had left; built as nothing and kept in
/// the kit's overlay, it let the next hover elsewhere take its tooltip at once.
#[gpui::test]
async fn an_answer_ending_within_the_show_delay_leaves_no_tooltip_at_pull_requests(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
    });
    let away = point(px(1.), px(1.));
    let tick = |cx: &mut VisualTestContext, by: Duration| {
        cx.executor().advance_clock(by);
        cx.run_until_parked();
        one_frame(cx);
    };
    for (form, lay_out, [first, second]) in header_forms() {
        rearm_in_form(&app, &opener, lay_out, cx);
        let (button, first, second) = (
            cx.debug_bounds("pull-requests").expect("the button"),
            cx.debug_bounds(first).expect("the first neighbour"),
            cx.debug_bounds(second).expect("the second neighbour"),
        );

        // The pointer meets the button in the answer's first frame and leaves it in the
        // next.
        meet_in_the_answers_first_frame(cx, button.center());
        assert!(answer_drawn(cx), "{form}: the answer stands");
        cx.simulate_mouse_move(away, None, Modifiers::default());
        one_frame(cx);
        tick(cx, Duration::from_millis(200));
        assert!(answer_drawn(cx), "{form}: the answer stands");

        // The write ends within the show delay of the pointer meeting the button.
        app.update(cx, |app, cx| {
            app.operation_busy = None;
            cx.notify();
        });
        one_frame(cx);
        for step in 0..=12 {
            let at = format!("{form}, {} ms after the write", step * 50);
            assert!(!answer_drawn(cx), "{at}: the answer has gone");
            assert_no_tooltip(cx, &[], &at);
            tick(cx, Duration::from_millis(50));
        }

        // A hover on the first neighbour waits out the show delay.
        cx.simulate_mouse_move(first.center(), None, Modifiers::default());
        draw(cx);
        tick(cx, TOOLTIP_DELAY - Duration::from_millis(50));
        let popups = kit_tooltip_popups(cx);
        assert!(
            popups.is_empty(),
            "{form}: the neighbour's tooltip waits its show delay: {popups:?}"
        );
        tick(cx, Duration::from_millis(100));
        draw(cx);
        assert_eq!(
            kit_tooltip_popups(cx).len(),
            1,
            "{form}: then the neighbour's tooltip shows"
        );

        // Another write, the pointer meeting the button in the answer's first frame and
        // leaving, and the show it asked for coming due while the answer stands: built as
        // nothing, it is hidden at once, so a hover on the second neighbour still waits out
        // the whole show delay.
        cx.simulate_mouse_move(away, None, Modifiers::default());
        tick(cx, TOOLTIP_DELAY * 2);
        app.update(cx, |app, cx| {
            app.operation_busy = Some("Fetching…");
            cx.notify();
        });
        draw(cx);
        meet_in_the_answers_first_frame(cx, button.center());
        assert!(answer_drawn(cx), "{form}: the second answer stands");
        cx.simulate_mouse_move(away, None, Modifiers::default());
        one_frame(cx);
        tick(cx, TOOLTIP_DELAY + Duration::from_millis(150));
        assert_eq!(
            tooltip_popups(cx).len(),
            1,
            "{form}: the answer alone says why"
        );
        cx.simulate_mouse_move(second.center(), None, Modifiers::default());
        draw(cx);
        tick(cx, TOOLTIP_DELAY - Duration::from_millis(50));
        let beside = neighbour_popups(cx);
        assert!(
            beside.is_empty(),
            "{form}: the second neighbour's tooltip waits its show delay: {beside:?}"
        );
        tick(cx, Duration::from_millis(100));
        assert_eq!(
            neighbour_popups(cx).len(),
            1,
            "{form}: then the second neighbour's tooltip shows"
        );
        app.update(cx, |app, cx| {
            app.operation_busy = None;
            cx.notify();
        });
        draw(cx);
    }
}

