/// A pointer that rested on Pull requests beside a keyboard press's answer and then left it
/// for blank space leaves no tooltip there as the write ends: Return on the focused button,
/// the pointer meeting it in the answer's first frame and resting there past the kit's
/// 500 ms show delay, so the kit's overlay holds the button's request, built as nothing,
/// then leaving for blank space, the overlay builds that request no more from the frame the
/// pointer's leaving draws, and where the write ends before the window draws again, the
/// overlay's last build of it draws nothing and hides it; either way no frame in the 600 ms
/// after the write's end draws a popup, the reason or the button's idle sentence, and a
/// hover on Changes, then on History, the compact form's glyph toggles beside the button at
/// 18 pt in a 461 × 490 window, waits out the whole show delay. A pointer that left and came
/// back to rest on the button before the write ends is one that came to it later: no frame
/// in the 600 ms after the write's end draws the button's idle tooltip under it, and a hover
/// on Changes then waits out the whole delay. A tooltip shows only for what the pointer
/// rests on: the request left standing would build the button's idle tooltip as the overlay
/// was built again at the write's end, but for the answer it was asked during, and under a
/// pointer back on the button drew it at once, without the show delay. Whether the overlay
/// still held the request after the pointer left, which only the pointer back on the button
/// shows, is checked once every pass has run, so what a person sees fails first.
#[gpui::test]
async fn a_pointer_that_left_the_answer_for_blank_space_draws_no_tooltip_as_the_write_ends(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
    });
    let away = point(px(1.), px(1.));
    cx.simulate_mouse_move(away, None, Modifiers::default());
    compact_form_header(cx);
    cx.update(|window, cx| window.focus(&opener, cx));
    draw(cx);
    let button = cx.debug_bounds("pull-requests").expect("the button");
    let tick = |cx: &mut VisualTestContext, by: Duration| {
        cx.executor().advance_clock(by);
        cx.run_until_parked();
        one_frame(cx);
    };
    // Each pass that draws frames after the pointer left, and whether the overlay still held
    // the button's request, built as nothing, 100 ms after it left.
    let mut held_after_leaving = Vec::new();
    for (pass, neighbour) in [
        ("frames drawn after the pointer left", "changes-tab"),
        ("no frame drawn after the pointer left", "history-tab"),
        ("the pointer back on the button", "changes-tab"),
    ] {
        let frames_after_leaving = pass != "no frame drawn after the pointer left";
        let back = pass == "the pointer back on the button";
        let neighbour = cx.debug_bounds(neighbour).expect("the neighbour");
        meet_in_the_answers_first_frame(cx, button.center());
        draw(cx);
        tick(cx, TOOLTIP_DELAY + Duration::from_millis(150));
        assert!(answer_drawn(cx), "{pass}: the answer stands");
        assert_eq!(kit_tooltip_popups(cx).len(), 1, "{pass}: the answer alone");
        assert!(
            app.read_with(cx, |app, _| app.github_refusal.built_empty.get()),
            "{pass}: the overlay built the button's request as nothing"
        );

        // The pointer leaves for blank space, and the write ends: later, or before the
        // window draws again, the move and the write's end handled in one pass.
        let leave = gpui::MouseMoveEvent {
            position: away,
            modifiers: Modifiers::default(),
            pressed_button: None,
        };
        if frames_after_leaving {
            cx.simulate_event(leave);
            draw(cx);
            tick(cx, Duration::from_millis(100));
            held_after_leaving.push((
                pass,
                app.read_with(cx, |app, _| app.github_refusal.built_empty.get()),
            ));
            if back {
                cx.simulate_mouse_move(
                    button.center() + point(px(2.), px(0.)),
                    None,
                    Modifiers::default(),
                );
                draw(cx);
                tick(cx, Duration::from_millis(100));
                assert!(answer_drawn(cx), "{pass}: the answer stands");
            }
            app.update(cx, |app, cx| {
                app.operation_busy = None;
                cx.notify();
            });
        } else {
            cx.update(|window, cx| {
                window.dispatch_event(gpui::PlatformInput::MouseMove(leave), cx);
                app.update(cx, |app, cx| {
                    app.operation_busy = None;
                    cx.notify();
                });
            });
        }
        one_frame(cx);
        for step in 0..=12 {
            let at = format!("{pass}, {} ms after the write", step * 50);
            assert!(!answer_drawn(cx), "{at}: the answer has gone");
            let popups = kit_tooltip_popups(cx);
            assert!(popups.is_empty(), "{at}: no popup: {popups:?}");
            for idle in [
                "pull-requests/tooltip/Discover pull requests and review captured changes",
                "pull-requests/tooltip/Pull requests · Discover pull requests and review \
                 captured changes",
            ] {
                assert!(
                    cx.debug_bounds(idle).is_none(),
                    "{at}: no idle tooltip at Pull requests"
                );
            }
            tick(cx, Duration::from_millis(50));
        }

        // A hover on the neighbour waits out the show delay.
        cx.simulate_mouse_move(neighbour.center(), None, Modifiers::default());
        draw(cx);
        tick(cx, TOOLTIP_DELAY - Duration::from_millis(50));
        let popups = kit_tooltip_popups(cx);
        assert!(
            popups.is_empty(),
            "{pass}: the neighbour's tooltip waits its show delay: {popups:?}"
        );
        tick(cx, Duration::from_millis(100));
        assert_eq!(
            kit_tooltip_popups(cx).len(),
            1,
            "{pass}: then the neighbour's tooltip shows"
        );

        // The next write.
        cx.simulate_mouse_move(away, None, Modifiers::default());
        tick(cx, TOOLTIP_DELAY * 2);
        app.update(cx, |app, cx| {
            app.operation_busy = Some("Fetching…");
            cx.notify();
        });
        draw(cx);
    }
    app.update(cx, |app, _| app.operation_busy = None);
    assert!(
        held_after_leaving.iter().all(|(_, held)| !held),
        "the overlay holds the button's request no more once the pointer has left: \
         {held_after_leaving:?}"
    );
}

/// Asserts that the last frame drew no tooltip popup, none besides `own`, the popups the
/// page draws of its own ([`own_popups`]), and none of Pull requests' sentences: the reason
/// it is refused for or its idle sentence in either header form.
fn assert_no_tooltip(cx: &mut VisualTestContext, own: &[Bounds<Pixels>], at: &str) {
    let popups: Vec<_> = kit_tooltip_popups(cx)
        .into_iter()
        .filter(|popup| !own.contains(popup))
        .collect();
    assert!(popups.is_empty(), "{at}: no popup: {popups:?}");
    for sentence in [
        REFUSED_TOOLTIP,
        "pull-requests/tooltip/Discover pull requests and review captured changes",
        "pull-requests/tooltip/Pull requests · Discover pull requests and review captured \
         changes",
    ] {
        assert!(
            cx.debug_bounds(sentence).is_none(),
            "{at}: {sentence} is not drawn"
        );
    }
}

/// The popups `page` draws of its own in the kit's popover fill with rounded corners, as a
/// tooltip's popup is drawn ([`kit_tooltip_popups`]), such as Settings' cards: the page
/// opened from the repository with the pointer away from every control and no tooltip
/// shown or waiting, then left for the repository again.
fn own_popups(
    app: &Entity<GitTurtle>,
    page: AppPage,
    cx: &mut VisualTestContext,
) -> Vec<Bounds<Pixels>> {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
    cx.executor().advance_clock(TOOLTIP_DELAY * 2);
    cx.run_until_parked();
    cx.update(|window, cx| {
        app.update(cx, |app, cx| match page {
            AppPage::Settings => app.show_settings(window, cx),
            AppPage::Projects => app.show_projects(window, cx),
            AppPage::Repository => unreachable!("the repository is the page left"),
        })
    });
    draw(cx);
    let own = kit_tooltip_popups(cx);
    cx.update(|window, cx| app.update(cx, |app, cx| app.return_from_page(window, cx)));
    draw(cx);
    assert_eq!(
        app.read_with(cx, |app, _| app.page),
        AppPage::Repository,
        "back on the repository"
    );
    own
}

/// A tooltip Pull requests asked for draws nothing on another page, though the page changes
/// while it still waits out the kit's 500 ms show delay: the pointer meeting the button in
/// the answer's first frame, Settings opened by its shortcut 200 ms later, and the pointer
/// moving 1 px inside the place the button stood, no frame on Settings draws a popup besides
/// Settings' own, the reason or the button's idle sentence, while the write runs, the show
/// coming due 300 ms after the move among them, or in the 600 ms after it ends. The
/// shortcut's key goes down on the Repository page and draws a frame there first, but the
/// button's prepaint, which hands back a request built as nothing, finds none built yet:
/// left waiting across the page change, the show came due on Settings, and the builder,
/// deciding from the last Repository frame, drew the reason over Settings, and the button's
/// idle tooltip once the write had ended. A shortcut pressed after the delay meets a request
/// already built, which that prepaint hands back, so that route drew nothing even without
/// the builder's page check and the page change's hide.
#[gpui::test]
async fn a_tooltip_pull_requests_asked_for_within_its_delay_draws_nothing_on_settings(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        crate::shortcuts::bind_keys(cx);
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
    });
    // Settings' own popups while the write runs and once it has ended, which changes a
    // card's height.
    let settings = own_popups(&app, AppPage::Settings, cx);
    app.update(cx, |app, cx| {
        app.operation_busy = None;
        cx.notify();
    });
    let settings_after = own_popups(&app, AppPage::Settings, cx);
    app.update(cx, |app, cx| {
        app.operation_busy = Some("Fetching…");
        cx.notify();
    });
    cx.update(|window, cx| window.focus(&opener, cx));
    draw(cx);
    let button = cx.debug_bounds("pull-requests").expect("the button");
    let tick = |cx: &mut VisualTestContext, by: Duration| {
        cx.executor().advance_clock(by);
        cx.run_until_parked();
        one_frame(cx);
    };
    meet_in_the_answers_first_frame(cx, button.center());
    draw(cx);
    // 200 ms on, 300 ms before the button's show comes due.
    tick(cx, TOOLTIP_DELAY - Duration::from_millis(300));
    assert!(
        answer_drawn(cx),
        "the answer stands under the resting pointer"
    );
    assert_eq!(
        kit_tooltip_popups(cx).len(),
        1,
        "the answer alone, the button's tooltip still waiting out its delay"
    );

    // Settings by its shortcut within the delay, and the pointer moving 1 px where the
    // button stood.
    cx.simulate_keystrokes("secondary-,");
    one_frame(cx);
    assert_eq!(
        app.read_with(cx, |app, _| app.page),
        AppPage::Settings,
        "the shortcut opens Settings"
    );
    assert_no_tooltip(cx, &settings, "Settings' first frame");
    cx.simulate_mouse_move(
        button.center() + point(px(1.), px(0.)),
        None,
        Modifiers::default(),
    );
    one_frame(cx);
    for step in 0..=6 {
        assert_no_tooltip(cx, &settings, &format!("{} ms after the move", step * 100));
        tick(cx, Duration::from_millis(100));
    }

    // The write ends.
    app.update(cx, |app, cx| {
        app.operation_busy = None;
        cx.notify();
    });
    one_frame(cx);
    for step in 0..=12 {
        assert_no_tooltip(
            cx,
            &settings_after,
            &format!("{} ms after the write", step * 50),
        );
        tick(cx, Duration::from_millis(50));
    }
}

/// A page change hides the tooltip the window shows or waits to show, whatever control asked
/// for it and whatever changed the page, and a hover on the new page waits out its own
/// delay, in both of the header's forms at 461 × 490 ([`header_forms`]): the pointer resting
/// past the kit's 500 ms show delay on the wrapped full header's Settings at 13 pt or the
/// compact form's History at 18 pt, its tooltip drawn, Settings opened by its shortcut draws
/// no popup besides its own in its first frame or in the 600 ms after; back on the
/// repository, the pointer meeting the full header's Projects or the compact form's Changes
/// and Projects opened by its shortcut 200 ms later, the show coming due draws nothing over
/// Projects; and the pointer resting past the delay on a theme card of Settings', scrolled
/// into view, its tooltip drawn, Back's shortcut draws no popup on the repository in its
/// first frame, and the pointer meeting the repository's Back to Projects 150 ms later,
/// within the kit's 300 ms grace after a tooltip goes, draws nothing until that control's
/// own delay has passed, and then its own tooltip. The kit's overlay forgets a tooltip only
/// as its trigger's hover ends, which a control the page no longer draws never ends:
/// History's tooltip stood over Settings, Changes' showed over Projects once its delay was
/// up, and the theme card's stood over the repository.
#[gpui::test]
async fn a_page_change_hides_the_tooltip_shown_or_waiting(cx: &mut TestAppContext) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (_fixture, app, cx) = repository_window(cx);
    cx.update(|window, cx| {
        window.activate_window();
        crate::shortcuts::bind_keys(cx);
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
    });
    let tick = |cx: &mut VisualTestContext, by: Duration| {
        cx.executor().advance_clock(by);
        cx.run_until_parked();
        one_frame(cx);
    };
    let away = point(px(1.), px(1.));
    let back_to_projects = format!(
        "page-back/tooltip/Back to Projects · {}[",
        crate::primary_label()
    );
    // The controls hovered in each form, in `header_forms`' order: one whose tooltip is
    // drawn as Settings opens, and one whose tooltip still waits as Projects opens; the
    // full header's Projects is its labelled return action.
    let hovered = [["settings", "page-back"], ["history-tab", "changes-tab"]];
    for ((form, lay_out, _), [shown, waiting]) in header_forms().into_iter().zip(hovered) {
        cx.simulate_mouse_move(away, None, Modifiers::default());
        tick(cx, TOOLTIP_DELAY * 2);
        lay_out(cx);
        let (settings, projects) = (
            own_popups(&app, AppPage::Settings, cx),
            own_popups(&app, AppPage::Projects, cx),
        );
        let (shown, waiting) = (
            cx.debug_bounds(shown).expect("the control shown"),
            cx.debug_bounds(waiting).expect("the control waiting"),
        );

        // A tooltip shown, and Settings by its shortcut.
        cx.simulate_mouse_move(shown.center(), None, Modifiers::default());
        draw(cx);
        tick(cx, TOOLTIP_DELAY + Duration::from_millis(150));
        assert_eq!(
            kit_tooltip_popups(cx).len(),
            1,
            "{form}: the tooltip is drawn"
        );
        cx.simulate_keystrokes("secondary-,");
        one_frame(cx);
        assert_eq!(
            app.read_with(cx, |app, _| app.page),
            AppPage::Settings,
            "{form}: the shortcut opens Settings"
        );
        for step in 0..=6 {
            assert_no_tooltip(
                cx,
                &settings,
                &format!("{form}: Settings, {} ms after it opened", step * 100),
            );
            tick(cx, Duration::from_millis(100));
        }

        // A tooltip waiting out its delay, and Projects by its shortcut.
        cx.simulate_mouse_move(away, None, Modifiers::default());
        cx.update(|window, cx| app.update(cx, |app, cx| app.return_from_page(window, cx)));
        draw(cx);
        assert_eq!(
            app.read_with(cx, |app, _| app.page),
            AppPage::Repository,
            "{form}: back on the repository"
        );
        tick(cx, TOOLTIP_DELAY * 2);
        cx.simulate_mouse_move(waiting.center(), None, Modifiers::default());
        draw(cx);
        tick(cx, Duration::from_millis(200));
        assert!(
            kit_tooltip_popups(cx).is_empty(),
            "{form}: the tooltip waits out its delay"
        );
        cx.simulate_keystrokes("secondary-shift-o");
        one_frame(cx);
        assert_eq!(
            app.read_with(cx, |app, _| app.page),
            AppPage::Projects,
            "{form}: the shortcut opens Projects"
        );
        for step in 0..=8 {
            assert_no_tooltip(
                cx,
                &projects,
                &format!("{form}: Projects, {} ms after it opened", step * 100),
            );
            tick(cx, Duration::from_millis(100));
        }

        // Back on the repository.
        cx.simulate_mouse_move(away, None, Modifiers::default());
        cx.update(|window, cx| app.update(cx, |app, cx| app.return_from_page(window, cx)));
        draw(cx);

        // A tooltip shown on Settings, and the repository by Back's shortcut.
        tick(cx, TOOLTIP_DELAY * 2);
        cx.simulate_keystrokes("secondary-,");
        draw(cx);
        assert_eq!(
            app.read_with(cx, |app, _| app.page),
            AppPage::Settings,
            "{form}: the shortcut opens Settings again"
        );
        // Settings' first theme card, the page scrolled to put it 160 px down the window.
        let card =
            crate::settings::shown(cx, "settings-theme-0").expect("Settings' first theme card");
        app.update(cx, |app, cx| {
            let page = app.theme_editor.page_scroll();
            let offset = page.offset();
            page.set_offset(point(offset.x, offset.y - (card.top() - px(160.))));
            app.notify_settings_page(cx);
        });
        draw(cx);
        let card =
            crate::settings::shown(cx, "settings-theme-0").expect("Settings' first theme card");
        assert!(
            card.top() > px(100.) && card.bottom() < px(490.),
            "{form}: the card {card:?} stands in the window"
        );
        // What the page draws of its own scrolled so, the pointer away from every control.
        let scrolled = kit_tooltip_popups(cx);
        cx.simulate_mouse_move(card.center(), None, Modifiers::default());
        draw(cx);
        tick(cx, TOOLTIP_DELAY + Duration::from_millis(150));
        let drawn: Vec<_> = kit_tooltip_popups(cx)
            .into_iter()
            .filter(|popup| !scrolled.contains(popup))
            .collect();
        assert_eq!(drawn.len(), 1, "{form}: the theme card's tooltip is drawn");
        cx.simulate_keystrokes("secondary-[");
        one_frame(cx);
        assert_eq!(
            app.read_with(cx, |app, _| app.page),
            AppPage::Repository,
            "{form}: Back's shortcut returns to the repository"
        );
        // The pointer meets the repository's Back to Projects 150 ms after Back's keystroke,
        // within the kit's 300 ms grace after a tooltip goes, in which a hover shows its
        // tooltip at once: nothing is drawn from Back's first frame until that control's own
        // delay has passed, which a hide that left the grace set would not wait out.
        let projects_back = cx
            .debug_bounds("page-back")
            .expect("the repository's Back to Projects");
        let met = Duration::from_millis(150);
        let step = Duration::from_millis(50);
        let mut since_back = Duration::ZERO;
        while since_back < met + TOOLTIP_DELAY {
            if since_back == met {
                cx.simulate_mouse_move(projects_back.center(), None, Modifiers::default());
                one_frame(cx);
            }
            assert_no_tooltip(
                cx,
                &[],
                &format!(
                    "{form}: the repository, {} ms after Back",
                    since_back.as_millis()
                ),
            );
            tick(cx, step);
            since_back += step;
        }
        tick(cx, step);
        assert_eq!(
            kit_tooltip_popups(cx).len(),
            1,
            "{form}: then Back to Projects' tooltip is drawn"
        );
        assert!(
            cx.debug_bounds(back_to_projects.clone().leak()).is_some(),
            "{form}: the tooltip drawn is Back to Projects' own"
        );
    }
}

/// Forgets the side the reason's popup at Pull requests last took and how many times it was
/// laid out to choose one, so a test counts from a frame that chooses it afresh.
fn forget_answer_side(app: &Entity<GitTurtle>, cx: &mut VisualTestContext) {
    app.update(cx, |app, _| app.github_refusal.placed.borrow_mut().take());
    ANSWER_SIDE_LAYOUTS.with(|layouts| layouts.set(0));
}

/// How many times the reason's popup at Pull requests was laid out to choose its side since
/// the count was last taken, which this starts again.
fn answer_side_layouts() -> usize {
    ANSWER_SIDE_LAYOUTS.with(|layouts| layouts.replace(0))
}

/// The side of Pull requests the reason's popup takes chosen afresh, as a keyboard press's
/// answer draws it: with the side remembered forgotten, Return on the focused button draws
/// the answer, laid out as the kit lays the pointer's tooltip out, and Escape then takes it
/// away again.
fn fresh_answer_side(
    app: &Entity<GitTurtle>,
    opener: &FocusHandle,
    cx: &mut VisualTestContext,
) -> gpui_kit::base::Placement {
    use crate::tags::tests::draw;
    forget_answer_side(app, cx);
    cx.update(|window, cx| window.focus(opener, cx));
    key_down(cx, "enter", false);
    key_up(cx, "enter");
    draw(cx);
    assert!(answer_drawn(cx), "the answer stands");
    let side = app
        .read_with(cx, |app, _| app.github_refusal.side.get())
        .expect("the answer takes a side");
    cx.simulate_keystrokes("escape");
    draw(cx);
    assert!(!answer_drawn(cx), "Escape ends the answer");
    side
}

/// The side of Pull requests the reason's popup takes is chosen again only as what it is
/// chosen from changes: at 13 pt in a 461 × 490 window with a write running, the frame after
/// the side was forgotten lays the popup out to choose it, and the next 20 frames lay out
/// none, with no answer kept, where the popup is never drawn, and with one kept; then
/// another repository tab, another reason, a larger interface size, another scale, a wider
/// window, one repository tab, a 1,480 × 973 window and four repository tabs each lay it
/// out again, the side it then remembers, with no answer drawn, is the side a keyboard
/// press's answer takes chosen afresh, above the button and below it among them, and the 20
/// frames after each lay out none. Chosen in every frame, each of a write's steady frames
/// laid out a tooltip view never drawn; a side remembered from inputs that no longer held
/// would leave the pointer's tooltip over controls the fresh side keeps clear.
#[gpui::test]
async fn the_pull_requests_answer_side_is_chosen_only_as_its_inputs_change(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::draw;
    let (fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        cx.bind_keys([gpui::KeyBinding::new(
            "escape",
            crate::ClearSearch,
            Some("GitTurtle"),
        )])
    });
    cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
    wrapped_full_header(cx);
    forget_answer_side(&app, cx);
    one_frame(cx);
    assert_eq!(answer_side_layouts(), 1, "the first frame chooses the side");
    let steady = |cx: &mut VisualTestContext, at: &str| {
        for _ in 0..20 {
            one_frame(cx);
        }
        assert_eq!(
            answer_side_layouts(),
            0,
            "{at}: 20 steady frames lay out none"
        );
    };
    steady(cx, "no answer kept");

    cx.update(|window, cx| window.focus(&opener, cx));
    key_down(cx, "enter", false);
    key_up(cx, "enter");
    draw(cx);
    assert!(answer_drawn(cx), "the answer stands");
    answer_side_layouts();
    steady(cx, "an answer kept");
    cx.simulate_keystrokes("escape");
    draw(cx);
    answer_side_layouts();

    /// A change of one input to the side, named.
    type Change<'a> = (&'a str, Box<dyn Fn(&mut VisualTestContext) + 'a>);
    let changes: [Change; 8] = [
        (
            "another repository tab",
            Box::new(|cx| hold_tabs(&app, fixture.path(), 2, cx)),
        ),
        (
            "another reason",
            Box::new(|cx| {
                app.update(cx, |app, cx| {
                    app.operation_busy = Some(RequestKind::Send.label());
                    cx.notify();
                })
            }),
        ),
        (
            "a larger interface size",
            Box::new(|cx| crate::focus_ring::sweep::interface_size(cx, 15)),
        ),
        (
            "another scale",
            Box::new(|cx| {
                cx.update(|window, _| {
                    let scale = if window.scale_factor() == 2. { 1.5 } else { 2. };
                    window.set_scale_factor(scale)
                })
            }),
        ),
        (
            "a wider window",
            Box::new(|cx| cx.simulate_resize(size(px(520.), px(490.)))),
        ),
        (
            "one repository tab",
            Box::new(|cx| hold_tabs(&app, fixture.path(), 1, cx)),
        ),
        (
            "a 1,480 × 973 window",
            Box::new(|cx| cx.simulate_resize(size(px(1480.), px(973.)))),
        ),
        (
            "four repository tabs",
            Box::new(|cx| hold_tabs(&app, fixture.path(), 4, cx)),
        ),
    ];
    let mut sides = Vec::new();
    for (at, change) in changes {
        change(cx);
        draw(cx);
        assert!(answer_side_layouts() >= 1, "{at}: lays the popup out again");
        assert!(!answer_drawn(cx), "{at}: no answer drawn");
        let remembered = app.read_with(cx, |app, _| app.github_refusal.side.get());
        let fresh = fresh_answer_side(&app, &opener, cx);
        assert_eq!(
            remembered,
            Some(fresh),
            "{at}: the side remembered is the side chosen afresh"
        );
        sides.push(fresh);
        answer_side_layouts();
        steady(cx, at);
    }
    use gpui_kit::base::Placement;
    assert!(
        sides.contains(&Placement::Top) && sides.contains(&Placement::Bottom),
        "the changes take the popup above the button and below it: {sides:?}"
    );
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    app.update(cx, |app, _| app.operation_busy = None);
}

/// The reason's popup at Pull requests, which the status bar holds among its parts, takes no
/// room there, laid out to choose the pointer's side or drawn as a keyboard press's answer:
/// Pull requests focused by Tab, the status line keeps the bounds it had before a write
/// began in the write's first frame and its steady frames, and with the reason standing at
/// the button once the status line's note has lapsed; and at 13 pt in a 639 × 980 window,
/// where a write's status stands in the status bar in the line's place, its progress label
/// and the line holding it keep the room they had in a frame that chose the popup's side
/// afresh, through the answer's frames and past the note. Left in the bar's flow wherever
/// its side held or it was drawn, the popup's empty node took one of the bar's gaps from the
/// status line in each of those frames, and a write's status the bar carried lost its label.
#[gpui::test]
async fn the_pull_requests_answer_takes_no_room_in_the_status_bar(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, cx) = repository_window(cx);
    cx.update(|window, _| window.activate_window());
    draw(cx);
    let opener = app.read_with(cx, |app, _| app.pull_requests_focus.clone());
    cx.update(|window, cx| window.focus(&opener, cx));
    draw(cx);
    cx.simulate_keystrokes("shift-tab");
    draw(cx);
    cx.simulate_keystrokes("tab");
    draw(cx);
    let line = |cx: &mut VisualTestContext| cx.debug_bounds("status-line").expect("the line");
    let rest = line(cx);
    app.update(cx, |app, cx| {
        app.operation_busy = Some("Fetching…");
        cx.notify();
    });
    for frame in 0..4 {
        one_frame(cx);
        assert_eq!(
            line(cx),
            rest,
            "the write's frame {frame}: the line keeps its room"
        );
    }
    key_down(cx, "enter", false);
    key_up(cx, "enter");
    draw(cx);
    assert!(answer_drawn(cx), "the reason stands at the button");
    cx.executor()
        .advance_clock(crate::copy_feedback::RESTORE_AFTER + Duration::from_millis(50));
    draw(cx);
    assert!(
        answer_drawn(cx) && app.read_with(cx, |app, _| app.github_refusal_line().is_none()),
        "the reason stays at the button past the status line's note"
    );
    assert_eq!(line(cx), rest, "beside the reason the line keeps its room");

    // At 13 pt in a 639 × 980 window the write's status stands in the status bar, in the
    // line's place: the line holding it and its label keep the bounds they had before
    // Return, in the answer's frames and once the status line's note has lapsed.
    app.update(cx, |app, cx| {
        app.operation_busy = None;
        cx.notify();
    });
    crate::focus_ring::sweep::interface_size(cx, 13);
    cx.simulate_resize(size(px(639.), px(980.)));
    draw(cx);
    cx.update(|window, cx| window.focus(&opener, cx));
    app.update(cx, |app, cx| {
        app.operation_busy = Some("Fetching…");
        cx.notify();
    });
    draw(cx);
    cx.executor()
        .advance_clock(crate::workspace::BUSY_LOOK_DELAY + Duration::from_millis(50));
    draw(cx);
    // A frame that chooses the side afresh lays the popup out with the frame, out of the
    // flow by the kit's positioner: the label's room with no node of the popup's in the bar.
    forget_answer_side(&app, cx);
    one_frame(cx);
    let bar = cx.debug_bounds("status-bar").expect("the status bar");
    let label = |cx: &mut VisualTestContext| {
        cx.debug_bounds("operation-progress")
            .expect("the write's progress label")
    };
    let (before, holding) = (label(cx), line(cx));
    assert!(
        bar.contains(&before.center()) && before.size.width > px(0.),
        "the write's status {before:?} stands in the status bar {bar:?}"
    );
    assert!(
        holding.contains(&before.center()),
        "the line {holding:?} holds the write's status {before:?}"
    );
    key_down(cx, "enter", false);
    key_up(cx, "enter");
    for frame in 0..4 {
        one_frame(cx);
        assert!(
            answer_drawn(cx),
            "frame {frame}: the reason stands at the button"
        );
        assert_eq!(
            (label(cx), line(cx)),
            (before, holding),
            "frame {frame} of the answer: the progress label and its line keep their room"
        );
    }
    cx.executor()
        .advance_clock(crate::copy_feedback::RESTORE_AFTER + Duration::from_millis(50));
    draw(cx);
    assert!(
        answer_drawn(cx) && app.read_with(cx, |app, _| app.github_refusal_line().is_none()),
        "the reason stays at the button past the status line's note"
    );
    assert_eq!(
        (label(cx), line(cx)),
        (before, holding),
        "past the note the progress label and its line keep their room"
    );
    app.update(cx, |app, _| app.operation_busy = None);
}

/// The answer a keyboard press of Pull requests stands at the button lasts the busy spell
/// while the button keeps focus, and ends with whichever comes first: the write ending,
/// focus leaving by Tab or by a click elsewhere, or the window turning inactive. Each
/// ending takes it away for good: a write that starts later, focus coming back or the
/// window turning active again brings back nothing no key asked for.
#[gpui::test]
async fn a_keyboard_answer_at_pull_requests_lasts_the_spell_on_the_button(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    let focused = |cx: &mut VisualTestContext| cx.update(|window, _| opener.is_focused(window));
    let busy = |cx: &mut VisualTestContext, busy: Option<&'static str>| {
        app.update(cx, |app, cx| {
            app.operation_busy = busy;
            cx.notify();
        });
        draw(cx);
    };
    let answer = |cx: &mut VisualTestContext, at: &str| {
        assert!(focused(cx), "{at}: Pull requests holds focus");
        key_down(cx, "enter", false);
        key_up(cx, "enter");
        draw(cx);
        cx.executor()
            .advance_clock(crate::copy_feedback::RESTORE_AFTER + Duration::from_millis(50));
        draw(cx);
        assert!(answer_drawn(cx), "{at}: the reason stands at the button");
    };

    answer(cx, "the write ending");
    busy(cx, None);
    assert!(!answer_drawn(cx), "the reason goes as the write ends");
    busy(cx, Some("Pushing…"));
    assert!(focused(cx), "focus stays on the button");
    assert!(
        !answer_drawn(cx),
        "a later write brings it back to no press"
    );

    answer(cx, "Tab");
    cx.simulate_keystrokes("tab");
    draw(cx);
    assert!(!focused(cx), "Tab moves on");
    // The button's blur, which the frame that moves focus reports as it ends, takes it in
    // the next, as the pointer's tooltip outlasts the pointer by its grace period.
    draw(cx);
    assert!(!answer_drawn(cx), "the reason goes with focus");
    cx.simulate_keystrokes("shift-tab");
    draw(cx);
    assert!(focused(cx), "Shift+Tab comes back");
    assert!(!answer_drawn(cx), "focus coming back brings nothing back");

    answer(cx, "a click elsewhere");
    let pane = cx.debug_bounds("history-pane").expect("History's pane");
    cx.simulate_click(pane.center(), Modifiers::default());
    draw(cx);
    draw(cx);
    assert!(!focused(cx), "the click takes focus to History");
    assert!(!answer_drawn(cx), "the reason goes with focus");
    cx.update(|window, cx| window.focus(&opener, cx));
    draw(cx);

    answer(cx, "the window turning inactive");
    cx.deactivate_window();
    draw(cx);
    draw(cx);
    assert!(
        !answer_drawn(cx),
        "the reason goes as the window turns inactive"
    );
    cx.update(|window, _| window.activate_window());
    draw(cx);
    draw(cx);
    assert!(focused(cx), "focus comes back with the window");
    assert!(!answer_drawn(cx), "and brings nothing back");
    busy(cx, None);
}

/// The popups the last frame drew, in the window's logical pixels: surfaces in the kit's
/// popover fill that lie inside the window clear of its sides and are no taller than a few
/// lines, as a tooltip's is. The window's raised surfaces, the header's and its panes',
/// share the fill, laid against a side of the window or taller.
fn popover_popups(cx: &mut VisualTestContext) -> Vec<Bounds<Pixels>> {
    let popover = cx.read(|cx| {
        gpui_kit::Background::from(gpui_kit::component::Theme::global(cx).tokens.popover)
    });
    cx.update(|window, _| {
        let (scale, width) = (window.scale_factor(), window.viewport_size().width);
        let logical = |value: gpui::ScaledPixels| px(value.as_f32() / scale);
        window
            .painted_quads()
            .into_iter()
            .filter(|quad| quad.background == popover)
            .map(|quad| {
                Bounds::from_corners(
                    point(logical(quad.bounds.left()), logical(quad.bounds.top())),
                    point(logical(quad.bounds.right()), logical(quad.bounds.bottom())),
                )
            })
            .filter(|popup| {
                popup.left() > px(0.5)
                    && popup.right() < width - px(0.5)
                    && popup.size.height < px(160.)
            })
            .collect()
    })
}

/// Draws one frame, as the window draws after an event, where [`crate::tags::tests::draw`]
/// draws three.
fn one_frame(cx: &mut VisualTestContext) {
    cx.update(|window, cx| {
        window.simulate_next_frame(cx);
        window.draw(cx).clear(cx);
    });
}

/// A keyboard press's answer at Pull requests stays drawn wherever the pointer goes, and
/// the button offers no tooltip of its own meanwhile, which would say the same sentence:
/// the pointer meeting the button before the frame that answers the press, crossing the
/// button a frame at each step, resting on it past the kit's 500 ms show delay and its
/// 150 ms slide, and leaving it, every frame draws the answer and one popup that says why.
/// The pointer resting there once took the answer away and drew the button's tooltip in
/// its place only after that delay and slide, so for up to 0.65 s nothing said why.
#[gpui::test]
async fn a_keyboard_answer_at_pull_requests_stays_drawn_under_the_pointer(cx: &mut TestAppContext) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        appearance::ThemeChoice::Midnight.apply(None, cx);
        cx.set_reduce_motion(true);
    });
    cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
    draw(cx);
    let button = cx.debug_bounds("pull-requests").expect("the button");
    let says_why = |cx: &mut VisualTestContext, at: &str| {
        assert!(answer_drawn(cx), "{at}: the answer is drawn");
        assert_eq!(
            tooltip_popups(cx).len(),
            1,
            "{at}: one popup says why, among {:?}",
            popover_popups(cx)
        );
    };

    // The pointer meets the button as the key goes down, before any frame answers it.
    key_down(cx, "enter", false);
    cx.simulate_mouse_move(button.center(), None, Modifiers::default());
    key_up(cx, "enter");
    one_frame(cx);
    says_why(cx, "the frame that answers the press");
    draw(cx);
    cx.executor()
        .advance_clock(TOOLTIP_DELAY + Duration::from_millis(150));
    draw(cx);
    says_why(
        cx,
        "past the show delay of a pointer that met the button first",
    );

    // Across the button, a frame at each step, from outside its left edge to past its right.
    cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
    draw(cx);
    let steps = 8;
    for step in 0..=steps {
        let x =
            button.left() - px(8.) + (button.size.width + px(16.)) * (step as f32 / steps as f32);
        cx.simulate_mouse_move(point(x, button.center().y), None, Modifiers::default());
        one_frame(cx);
        says_why(cx, &format!("crossing it at {x:?}"));
    }

    // Resting on it, a frame every 50 ms past the show delay and the slide.
    cx.simulate_mouse_move(button.center(), None, Modifiers::default());
    one_frame(cx);
    says_why(cx, "coming to rest on it");
    for tick in 1..=16 {
        cx.executor().advance_clock(Duration::from_millis(50));
        cx.executor().run_until_parked();
        one_frame(cx);
        says_why(cx, &format!("resting on it for {} ms", tick * 50));
    }

    // Leaving it.
    cx.simulate_mouse_move(point(px(1.), px(1.)), None, Modifiers::default());
    one_frame(cx);
    says_why(cx, "leaving it");
    cx.executor()
        .advance_clock(TOOLTIP_DELAY + Duration::from_millis(150));
    draw(cx);
    says_why(cx, "once it has left");
    assert!(
        cx.update(|window, _| opener.is_focused(window)),
        "focus stays on the button"
    );
    app.update(cx, |app, _| app.operation_busy = None);
}

/// The answer a keyboard press stands at Pull requests says the reason that refuses the
/// panel now: a write giving way to an outbound action mid-spell builds it again in the
/// action's words, the status line dropping the write's sentence rather than go on saying
/// it for up to 1.5 s, and it goes once nothing refuses the panel. It once kept the words of
/// the spell it began in.
#[gpui::test]
async fn a_keyboard_answer_at_pull_requests_follows_a_changed_reason(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    key_down(cx, "enter", false);
    key_up(cx, "enter");
    draw(cx);
    assert!(
        cx.debug_bounds(REFUSED_TOOLTIP).is_some(),
        "the answer says to wait for the write"
    );
    app.update(cx, |app, cx| {
        app.operation_busy = Some(RequestKind::Send.label());
        cx.notify();
    });
    draw(cx);
    let sending: &'static str = format!(
        "pull-requests/tooltip/{}",
        open_refused_sentence(RequestKind::Send.reason())
    )
    .leak();
    assert!(answer_drawn(cx), "the answer stays as the reason changes");
    assert!(
        app.read_with(cx, |app, _| app.github_refusal_line().is_none())
            && refusals_heard().is_empty(),
        "the status line and its live region drop the write's sentence"
    );
    assert!(
        cx.debug_bounds(sending).is_some() && cx.debug_bounds(REFUSED_TOOLTIP).is_none(),
        "it says the outbound action's reason alone"
    );
    assert!(
        cx.update(|window, _| opener.is_focused(window)),
        "focus stays on the button"
    );
    // The write's reason coming back within the note's 1.5 s brings back no sentence.
    app.update(cx, |app, cx| {
        app.operation_busy = Some("Fetching…");
        cx.notify();
    });
    draw(cx);
    assert!(
        app.read_with(cx, |app, _| app.github_refusal_line().is_none())
            && refusals_heard().is_empty(),
        "the status line and its live region keep the write's sentence dropped"
    );
    app.update(cx, |app, cx| {
        app.operation_busy = None;
        cx.notify();
    });
    draw(cx);
    assert!(
        !answer_drawn(cx) && cx.debug_bounds(sending).is_none(),
        "it goes once nothing refuses the panel"
    );
}

/// Escape on Pull requests with the pointer resting on it ends the answer a keyboard press
/// stands there, which is drawn there, and does nothing else; the next Escape is the
/// window's. Kept but not drawn under the pointer, the answer once took an Escape that
/// changed nothing visible.
#[gpui::test]
async fn escape_ends_the_answer_at_pull_requests_under_a_resting_pointer(cx: &mut TestAppContext) {
    use crate::tags::tests::{TOOLTIP_DELAY, draw};
    let (_fixture, app, opener, cx) = refused_by_tab(cx);
    cx.update(|_, cx| {
        cx.bind_keys([gpui::KeyBinding::new(
            "escape",
            crate::ClearSearch,
            Some("GitTurtle"),
        )])
    });
    let focused = |cx: &mut VisualTestContext| cx.update(|window, _| opener.is_focused(window));
    let button = cx.debug_bounds("pull-requests").expect("the button");
    key_down(cx, "enter", false);
    key_up(cx, "enter");
    draw(cx);
    cx.simulate_mouse_move(button.center(), None, Modifiers::default());
    draw(cx);
    cx.executor()
        .advance_clock(TOOLTIP_DELAY + Duration::from_millis(150));
    draw(cx);
    assert!(
        answer_drawn(cx),
        "the answer stands under the resting pointer"
    );

    cx.simulate_keystrokes("escape");
    draw(cx);
    assert!(!answer_drawn(cx), "Escape ends it");
    assert!(focused(cx), "and does nothing else");
    cx.simulate_keystrokes("escape");
    draw(cx);
    assert!(!focused(cx), "the next Escape is the window's");
    app.update(cx, |app, _| app.operation_busy = None);
}

/// A keyboard press's answer at Pull requests is said once, by the status line and its
/// live region: the tooltip drawn at the button, the kit's tooltip node with it, is out
/// of the accessibility tree, so the sentence reaches an assistive technology in the
/// status line's text and the live region only. Drawn in the tree, the tooltip node, a
/// third with the sentence, could be read again as it appeared.
#[gpui::test]
async fn a_keyboard_answer_at_pull_requests_is_spoken_by_the_live_region_alone(
    cx: &mut TestAppContext,
) {
    use crate::native_accessibility::{reachable, written};
    use crate::tags::tests::draw;
    let (_fixture, app, _opener, cx) = refused_by_tab(cx);
    key_down(cx, "enter", false);
    key_up(cx, "enter");
    draw(cx);
    assert!(answer_drawn(cx), "the reason stands at the button");
    written::forget();
    draw(cx);
    let size = cx.update(|window, _| window.viewport_size());
    let window = physical_rect(cx, Bounds::new(point(px(0.), px(0.)), size));
    // The kit's tooltip writes a node of its own, named by its text, inside the element
    // that holds it, as GPUI writes it: only the app's own wrappers record theirs.
    let mut popup = gpui::accesskit::Node::new(Role::Tooltip);
    popup.set_label(REFUSED_SENTENCE);
    let holder = written::get("pull-requests-answer").map(|_| "pull-requests-answer");
    let tree = written::Assembly::default()
        .everything(None)
        .node("tooltip-popup", popup, holder)
        .tree(window, None);
    let saying: Vec<Role> = reachable(tree)
        .into_iter()
        .filter(|node| node.name.as_deref() == Some(REFUSED_SENTENCE))
        .map(|node| node.role)
        .collect();
    assert_eq!(
        saying,
        [Role::Label, Role::Status],
        "the sentence reaches assistive technology in the status line and its live region"
    );
    app.update(cx, |app, _| app.operation_busy = None);
}

/// A held Return or Space on a refused Pull requests answers once and opens nothing as the
/// write ends: its repeats, marked held as Wayland and macOS send them or sent as fresh
/// presses with no key-up between them as X11 sends them, before and after the write ends,
/// say nothing more, and its key-up once the write has ended opens no panel; the next press
/// opens it at once. GPUI arms a Button's press on any Enter or Space key-down and makes it
/// as the key comes up, so that key-up opened the panel the press had been refused.
#[gpui::test]
async fn a_held_refused_press_of_pull_requests_answers_once_and_opens_nothing(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::draw;
    let (_fixture, app, cx) = repository_window(cx);
    let panel = closed_panel(&app, cx);
    draw(cx);
    let opener = app.read_with(cx, |app, _| app.pull_requests_focus.clone());
    let open = |cx: &mut VisualTestContext| cx.update(|window, cx| window.has_active_dialog(cx));
    for key in ["enter", "space"] {
        cx.update(|window, cx| window.focus(&opener, cx));
        app.update(cx, |app, _| app.operation_busy = Some("Fetching…"));
        draw(cx);
        key_down(cx, key, false);
        draw(cx);
        let said = refusals_heard();
        assert_eq!(said.len(), 1, "{key}: answered as it goes down");
        for is_held in [true, true, false, false] {
            key_down(cx, key, is_held);
            draw(cx);
        }
        assert_eq!(
            refusals_heard(),
            said,
            "{key}: its repeats say nothing more"
        );

        app.update(cx, |app, _| app.operation_busy = None);
        draw(cx);
        for is_held in [true, false] {
            key_down(cx, key, is_held);
            draw(cx);
        }
        key_up(cx, key);
        draw(cx);
        cx.run_until_parked();
        assert!(!open(cx), "{key}: its key-up after the write opens nothing");
        assert_eq!(refusals_heard(), said, "{key}: nor says anything more");
        assert!(
            cx.update(|window, _| opener.is_focused(window)),
            "{key}: focus stays on the button"
        );

        key_down(cx, key, false);
        key_up(cx, key);
        draw(cx);
        assert!(open(cx), "{key}: the next press opens the panel at once");
        cx.update(|window, cx| panel.update(cx, |panel, cx| panel.close(window, cx)));
        settle_panel(&app, cx).await;
        draw(cx);
        assert!(!open(cx), "{key}: closed again");
    }
}

/// A refused Return held on Pull requests while Space is pressed and released, the write
/// ending before Return comes up, opens nothing: the refused key-downs never arm the
/// button's press, which GPUI arms on any Enter or Space key-down and makes as the key
/// comes up, and Space took the latch that would have caught Return's key-up. Armed by
/// Return going down, that key-up opened the panel the press had been refused. The next
/// press opens it at once.
#[gpui::test]
async fn a_refused_return_held_across_a_space_opens_nothing(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, cx) = repository_window(cx);
    let panel = closed_panel(&app, cx);
    draw(cx);
    let opener = app.read_with(cx, |app, _| app.pull_requests_focus.clone());
    let open = |cx: &mut VisualTestContext| cx.update(|window, cx| window.has_active_dialog(cx));
    cx.update(|window, cx| window.focus(&opener, cx));
    app.update(cx, |app, _| app.operation_busy = Some("Fetching…"));
    draw(cx);
    key_down(cx, "enter", false);
    draw(cx);
    key_down(cx, "space", false);
    draw(cx);
    key_up(cx, "space");
    draw(cx);
    assert_eq!(refusals_heard().len(), 1, "each press is answered");
    app.update(cx, |app, _| app.operation_busy = None);
    draw(cx);
    key_up(cx, "enter");
    draw(cx);
    cx.run_until_parked();
    assert!(!open(cx), "Return's key-up after the write opens nothing");
    assert!(
        cx.update(|window, _| opener.is_focused(window)),
        "focus stays on the button"
    );

    key_down(cx, "enter", false);
    key_up(cx, "enter");
    draw(cx);
    assert!(open(cx), "the next press opens the panel at once");
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.close(window, cx)));
    settle_panel(&app, cx).await;
}

/// Return that goes down on Pull requests while the panel can open and comes up once a write
/// has started is a press the write refuses: it opens nothing and is answered at the button
/// and in the status line, as one refused as it goes down is, focus staying on the button.
/// The button's press, armed as the key went down, would otherwise open the panel over
/// the write that refuses it.
#[gpui::test]
async fn a_return_released_after_a_write_starts_answers_at_the_button(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, cx) = repository_window(cx);
    let _panel = closed_panel(&app, cx);
    cx.update(|window, _| window.activate_window());
    draw(cx);
    let opener = app.read_with(cx, |app, _| app.pull_requests_focus.clone());
    cx.update(|window, cx| window.focus(&opener, cx));
    draw(cx);
    key_down(cx, "enter", false);
    draw(cx);
    assert!(
        refusals_heard().is_empty(),
        "nothing refuses it as it goes down"
    );
    app.update(cx, |app, cx| {
        app.operation_busy = Some("Fetching…");
        cx.notify();
    });
    draw(cx);
    key_up(cx, "enter");
    draw(cx);
    cx.run_until_parked();
    assert!(
        !cx.update(|window, cx| window.has_active_dialog(cx)),
        "the press opens nothing"
    );
    assert!(answer_drawn(cx), "the reason stands at the button");
    assert_eq!(refusals_heard().len(), 1, "and is spoken once");
    assert!(
        cx.update(|window, _| opener.is_focused(window)),
        "focus stays on the button"
    );
    app.update(cx, |app, _| app.operation_busy = None);
}

/// A real cancelled read under a reopened panel: the read is submitted, the close cancels
/// it, the panel reopens over its drain, and a Send refused by that drain stays to be sent.
/// The reopened panel, the refused confirmation and the drain's own `operation_busy` all
/// survive the drain's end; the tests beside this one set the busy spell by hand.
#[gpui::test]
async fn a_refused_send_under_a_reopened_panel_survives_the_drain(cx: &mut TestAppContext) {
    use crate::views::tests::draw;
    let (_fixture, app, panel, cx) = busy_fixture_panel(cx).await;
    // Opened at rest, so a click lands where the last frame drew its button.
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.close(window, cx)));
    settle_panel(&app, cx).await;
    let pull = local_pull(&app, cx);
    cx.update(|_, cx| {
        cx.set_reduce_motion(true);
        panel.update(cx, |panel, _| panel.pull = Some(pull.clone()));
    });
    open_notice_panel(&app, &panel, (13, 1480., 980.), cx).await;

    // Changes, held as a large comparison holds it.
    let held = app.update(cx, |app, _| app.operations.hold());
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.changes(window, cx)));
    draw(cx);
    let running = RequestKind::Compare.label();
    let busy = |cx: &mut VisualTestContext| app.read_with(cx, |app, _| app.operation_busy);
    assert_eq!(busy(cx), Some(running), "the read runs");

    // Closing cancels it, and its drain still holds the busy spell.
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.close(window, cx)));
    draw(cx);
    assert_eq!(busy(cx), Some(running), "the cancelled read still drains");
    assert!(
        !cx.update(|window, cx| window.has_active_dialog(cx)),
        "the panel is closed"
    );

    // Pull requests opens the panel again at once, over that drain.
    crate::copy_feedback::tests::click(cx, "pull-requests");
    draw(cx);
    assert!(
        cx.update(|window, cx| window.has_active_dialog(cx)),
        "the panel reopens at once"
    );

    // A Send the drain refuses says why and stays to be sent.
    cx.update(|window, cx| {
        panel.update(cx, |panel, cx| {
            panel.confirm = Some(confirmed_comment());
            panel.submit(window, cx);
        })
    });
    draw(cx);
    panel.read_with(cx, |panel, _| {
        assert!(!panel.pending, "nothing is sent");
        assert!(panel.confirm.is_some(), "the confirmation stays");
        assert_eq!(
            panel.error.as_deref(),
            Some("Wait for the pull request comparison to finish, then try again.")
        );
    });
    assert_eq!(busy(cx), Some(running), "nothing clobbers the drain");

    // The drain ends: the panel survives, its refusal with it.
    drop(held);
    app.read_with(cx, |app, _| app.operations.drain());
    settle_panel(&app, cx).await;
    draw(cx);
    assert_eq!(busy(cx), None, "the drain has ended");
    assert!(
        cx.update(|window, cx| window.has_active_dialog(cx)),
        "the reopened panel survives"
    );
    panel.read_with(cx, |panel, _| {
        assert!(!panel.closed, "still open");
        assert!(panel.confirm.is_some(), "the refused confirmation stays");
    });
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.close(window, cx)));
    settle_panel(&app, cx).await;
}

/// Pressing Pull requests at rest opens the panel and takes its tooltip with it. Kept
/// through every press, "Discover pull requests…" could stay over the opened panel: only
/// a refused press, which opens nothing, answers in the tooltip.
#[gpui::test]
async fn the_idle_pull_requests_tooltip_goes_as_the_panel_opens(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, cx) = repository_window(cx);
    let _panel = closed_panel(&app, cx);
    draw(cx);
    const TOOLTIP: &str =
        "pull-requests/tooltip/Discover pull requests and review captured changes";
    let button = cx.debug_bounds("pull-requests").expect("the button");
    cx.simulate_mouse_move(button.center(), None, Modifiers::default());
    cx.executor().advance_clock(Duration::from_millis(500));
    draw(cx);
    assert!(cx.debug_bounds(TOOLTIP).is_some(), "shown on hover");

    cx.simulate_click(button.center(), Modifiers::default());
    draw(cx);
    assert!(
        cx.update(|window, cx| window.has_active_dialog(cx)),
        "the panel opens"
    );
    assert!(
        cx.debug_bounds(TOOLTIP).is_none(),
        "its tooltip goes in the frame the panel opens"
    );
    cx.executor().advance_clock(Duration::from_millis(500));
    draw(cx);
    assert!(
        cx.debug_bounds(TOOLTIP).is_none(),
        "and does not come back over it"
    );
    settle_panel(&app, cx).await;
}

/// The status strip names the keys of the panel's control that holds focus where it has
/// its own, Escape by the panel's footer button, and nothing for a control with none,
/// such as a field. The panel registered no control, so the strip stayed empty on its
/// lists as on everything else.
#[gpui::test]
async fn the_status_strip_names_only_the_focused_controls_own_keys(cx: &mut TestAppContext) {
    use crate::shortcuts::DialogKeys;
    let (_fixture, app, cx) = repository_window(cx);
    let panel = cx.update(|window, cx| {
        let repo = app.read(cx).repository.clone().unwrap();
        let panel = cx.new(|cx| Panel::new(app.downgrade(), repo, "main".into(), window, cx));
        panel.update(cx, |panel, cx| panel.close(window, cx));
        panel
    });
    crate::tags::tests::draw(cx);
    open_panel(&app, cx).await;
    let hints = |cx: &mut VisualTestContext| {
        cx.update(|window, cx| app.update(cx, |app, cx| app.status_hints(window, cx)))
    };
    let (files, lines, confirmation, field) = panel.read_with(cx, |panel, cx| {
        (
            panel.review.file_focus.clone(),
            panel.review.line_focus.clone(),
            panel.conversations.confirm_focus.clone(),
            panel.destination.read(cx).focus_handle(cx),
        )
    });
    for (focus, keys, name) in [
        (files, DialogKeys::GithubFiles, "the changed files"),
        (lines, DialogKeys::GithubPatch, "the patch"),
        (
            confirmation,
            DialogKeys::GithubConfirmation,
            "the confirmation",
        ),
    ] {
        cx.update(|window, cx| window.focus(&focus, cx));
        let named = hints(cx).unwrap_or_else(|| panic!("{name} name their keys"));
        assert_eq!(named, keys.key_hints().whole(), "{name}");
        assert!(named.contains("Esc Back to repository"), "{name}: {named}");
    }
    cx.update(|window, cx| window.focus(&field, cx));
    assert_eq!(hints(cx), None, "a field has no keys of its own to name");
}

/// A pull request `fixture/repo` lists: `number`, open, from `head` (`owner:branch`) onto
/// `base`.
fn listed_pull(number: u64, head: &str, base: &str) -> PullRequest {
    let branch = head.split_once(':').map_or(head, |(_, branch)| branch);
    serde_json::from_value(serde_json::json!({
        "number": number, "title": format!("Listed pull request {number}"), "state": "open",
        "draft": false, "user": {"login": "fixture-author"},
        "head": {"sha": "1".repeat(40), "ref": branch, "label": head},
        "base": {"sha": "2".repeat(40), "ref": base, "label": format!("fixture:{base}")},
    }))
    .expect("a listed pull request")
}

/// A window on an empty repository and the panel over it, signed in as the script's
/// account with `rows` listed for `fixture/repo` and its New pull request form filled for
/// `head` onto `main`: closed and warm, for [`send_creation`], with the draft its close
/// saved in the store. The window's writer saves it on a thread of its own, and a save
/// reads the store and replaces it whole ([`drafts::save_batch`]), so the panel is handed
/// back once that save has landed: a test may then write the store itself
/// ([`drafts::save`]). Handed back sooner, a test that saved three drafts next lost the
/// second to the close's save, which had read the store before that draft was in it and
/// replaced the store after: once among some hundred runs beside the other creation
/// tests, whose load alone made the writer's thread that late. Every request it sends is
/// answered from the returned script, never by GitHub. Keep the directory until the test
/// ends.
fn creation_panel<'a>(
    cx: &'a mut TestAppContext,
    rows: Vec<PullRequest>,
    head: &str,
) -> (
    tempfile::TempDir,
    Entity<GitTurtle>,
    Entity<Panel>,
    github::Scripted,
    &'a mut VisualTestContext,
) {
    let (fixture, app, cx) = repository_window(cx);
    let script = github::Scripted::default();
    let scripted = script.clone();
    cx.update(|_, cx| cx.set_reduce_motion(true));
    let panel = cx.update(|window, cx| {
        let repo = app.read(cx).repository.clone().unwrap();
        let panel = cx.new(|cx| Panel::new(app.downgrade(), repo, "main".into(), window, cx));
        panel.update(cx, |panel, cx| {
            panel.scripted = Some(scripted);
            panel.account = Some(github::Scripted::LOGIN.into());
            panel.notice = None;
            // Listed by Refresh PRs, as rows are.
            panel.listed = (!rows.is_empty()).then(|| Repository::parse("fixture/repo").unwrap());
            panel.rows = rows;
            panel.create = true;
            for (input, value) in [
                (&panel.destination, "fixture/repo"),
                (&panel.title, "Keep the review's place"),
                (&panel.head, head),
                (&panel.base, "main"),
            ] {
                input.update(cx, |input, cx| input.set_value(value, window, cx));
            }
            panel.body.update(cx, |input, cx| {
                input.set_value("Typed description", window, cx)
            });
            panel.close(window, cx);
        });
        panel
    });
    // The store is at rest: the close's save has landed.
    app.read_with(cx, |app, _| app.preferences_writer.drain());
    (fixture, app, panel, script, cx)
}

/// Return going down and coming up on whatever holds focus.
fn press_return(cx: &mut VisualTestContext) {
    let keystroke = gpui::Keystroke::parse("enter").unwrap();
    cx.simulate_event(gpui::KeyDownEvent {
        keystroke: keystroke.clone(),
        is_held: false,
        prefer_character_input: false,
    });
    cx.simulate_event(gpui::KeyUpEvent { keystroke });
}

/// Opens [`creation_panel`]'s panel in a `width` × `height` window at `interface` pt, the
/// window resized first, and sends its form by its own presses: Return on Review
/// submission…, the script answering the head's and the base's identities, then Return on
/// Send to GitHub, the script answering the two rechecks and then the creation with `body`
/// under `status`.
async fn send_creation(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    script: &github::Scripted,
    at: (u8, f32, f32),
    answer: (u16, &str),
    cx: &mut VisualTestContext,
) {
    use crate::tags::tests::draw;
    let send = review_creation(app, panel, script, at, answer, false, cx).await;
    cx.update(|window, cx| send.focus(window, cx));
    draw(cx);
    press_return(cx);
    settle_panel(app, cx).await;
    draw(cx);
    draw(cx);
    assert_eq!(script.asked("POST", "/pulls"), 1, "one creation was sent");
}

/// [`send_creation`] with Send to GitHub pressed by a click, which leaves no Return going
/// down or coming up behind it.
async fn click_creation(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    script: &github::Scripted,
    at: (u8, f32, f32),
    answer: (u16, &str),
    cx: &mut VisualTestContext,
) {
    use crate::tags::tests::draw;
    review_creation(app, panel, script, at, answer, false, cx).await;
    let send = whole_in_body(cx, "github-confirm-send", "Send to GitHub");
    cx.simulate_click(send.center(), Modifiers::none());
    settle_panel(app, cx).await;
    draw(cx);
    assert_eq!(script.asked("POST", "/pulls"), 1, "one creation was sent");
}

/// The first part of [`send_creation`], up to the confirmation, with the script holding
/// the answers Send to GitHub then gets; Send's focus handle. With `by_click`, Review
/// submission… is pressed by a click, so the test's next Return is the window's first.
async fn review_creation(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    script: &github::Scripted,
    (interface, width, height): (u8, f32, f32),
    (status, body): (u16, &str),
    by_click: bool,
    cx: &mut VisualTestContext,
) -> FocusHandle {
    use crate::tags::tests::draw;
    cx.simulate_resize(size(px(width), px(height)));
    cx.update(|window, cx| appearance::apply_text_sizes(interface, 12, window, cx));
    draw(cx);
    cx.update(|window, _| {
        assert_eq!(window.scale_factor(), 2., "the test window's scale");
        assert_eq!(window.viewport_size(), size(px(width), px(height)));
    });
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    settle_panel(app, cx).await;
    draw(cx);
    let identities = |script: &github::Scripted| {
        script.answer(200, format!(r#"{{"sha":"{}"}}"#, "1".repeat(40)));
        script.answer(200, format!(r#"{{"sha":"{}"}}"#, "2".repeat(40)));
    };
    identities(script);
    let review = panel
        .read_with(cx, |panel, _| {
            panel.review.buttons.kept("github-review-submit")
        })
        .expect("Review submission…");
    if by_click {
        let review = whole_in_body(cx, "github-review-submit", "Review submission…");
        cx.simulate_click(review.center(), Modifiers::none());
    } else {
        cx.update(|window, cx| review.focus(window, cx));
        draw(cx);
        press_return(cx);
    }
    settle_panel(app, cx).await;
    draw(cx);
    assert!(
        panel.read_with(cx, |panel, _| panel.confirm.is_some()),
        "the creation is reviewed: {:?}",
        panel.read_with(cx, |panel, _| panel.error.clone())
    );
    identities(script);
    script.answer(status, body);
    panel
        .read_with(cx, |panel, _| {
            panel.review.buttons.kept("github-confirm-send")
        })
        .expect("Send to GitHub")
}

/// `selector`'s bounds, drawn whole inside the body's view.
fn whole_in_body(cx: &mut VisualTestContext, selector: &'static str, at: &str) -> Bounds<Pixels> {
    let body = cx.debug_bounds("github-panel").expect("the body");
    let drawn = cx
        .debug_bounds(selector)
        .unwrap_or_else(|| panic!("{at}: {selector} is drawn"));
    assert!(
        drawn.size.width > px(0.)
            && drawn.size.height > px(0.)
            && drawn.top() >= body.top()
            && drawn.bottom() <= body.bottom()
            && drawn.left() >= body.left()
            && drawn.right() <= body.right(),
        "{at}: {selector} at {drawn:?} is whole in the body's view {body:?}"
    );
    drawn
}

/// What the New pull request form holds: its title, its description and whether Draft is
/// chosen.
fn form(panel: &Entity<Panel>, cx: &mut VisualTestContext) -> (String, String, bool) {
    panel.read_with(cx, |panel, cx| {
        (
            panel.title.read(cx).value().to_string(),
            panel.body.read(cx).value().to_string(),
            panel.draft,
        )
    })
}

/// The creation drafts `saved` holds, each as [`form`] gives one.
fn creations(saved: &[Draft]) -> Vec<(String, String, bool)> {
    saved
        .iter()
        .filter_map(|draft| match draft {
            Draft::Pull(pull) => Some((pull.title.clone(), pull.body.clone(), pull.draft)),
            _ => None,
        })
        .collect()
}

/// Asserts that the draft store on disk and the panel's Recover drafts each hold `form`
/// as their one creation draft.
fn assert_one_creation_saved(
    panel: &Entity<Panel>,
    form: &(String, String, bool),
    when: &str,
    cx: &mut VisualTestContext,
) {
    let stored = creations(&drafts::load().expect("the draft store"));
    let one = std::slice::from_ref(form);
    assert_eq!(stored, one, "{when}: the draft store");
    let listed = panel.read_with(cx, |panel, _| creations(&panel.saved));
    assert_eq!(listed, one, "{when}: Recover drafts");
}

/// A pointer's click on `selector`, drawn whole in the body's view, and what follows it.
async fn click_in_body(
    app: &Entity<GitTurtle>,
    selector: &'static str,
    cx: &mut VisualTestContext,
) {
    let control = whole_in_body(cx, selector, "before its click");
    cx.simulate_click(control.center(), Modifiers::none());
    settle_panel(app, cx).await;
    crate::tags::tests::draw(cx);
}

/// [`creation_panel`]'s panel open at 13 pt in a 1,480 × 973 window, with `typed` typed
/// into its form's title and into its description.
async fn typed_form<'a>(
    cx: &'a mut TestAppContext,
    rows: Vec<PullRequest>,
    typed: &str,
) -> (
    tempfile::TempDir,
    Entity<GitTurtle>,
    Entity<Panel>,
    github::Scripted,
    &'a mut VisualTestContext,
) {
    use crate::tags::tests::draw;
    let (fixture, app, panel, script, cx) = creation_panel(cx, rows, "feature");
    cx.simulate_resize(size(px(1480.), px(973.)));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    draw(cx);
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    settle_panel(&app, cx).await;
    draw(cx);
    let before = form(&panel, cx);
    for description in [false, true] {
        cx.update(|window, cx| {
            let panel = panel.read(cx);
            let field = if description {
                panel.body.read(cx).focus_handle(cx)
            } else {
                panel.title.read(cx).focus_handle(cx)
            };
            field.focus(window, cx)
        });
        draw(cx);
        cx.simulate_input(typed);
        draw(cx);
    }
    let after = form(&panel, cx);
    for (before, after) in [(&before.0, &after.0), (&before.1, &after.1)] {
        assert!(
            after.len() == before.len() + typed.len() && after.contains(typed),
            "typing reaches the title and the description: {after:?}"
        );
    }
    (fixture, app, panel, script, cx)
}

/// A new pull request's description outlasts leaving its form and coming back: with a
/// title and a description typed, Pull requests saves the draft and shows the list, and
/// New pull request opens the form on what it held, the store and Recover drafts holding
/// that draft once. Opening the form cleared the description, which is the review body's
/// field too, and then saved the title with no description over the draft it had just
/// saved: the text was gone from the form and from the store.
#[gpui::test]
async fn a_description_outlasts_leaving_the_form_and_coming_back(cx: &mut TestAppContext) {
    let (_fixture, app, panel, _script, cx) = typed_form(cx, Vec::new(), " typed").await;
    let typed = form(&panel, cx);
    click_in_body(&app, "github-create-back", cx).await;
    assert!(
        panel.read_with(cx, |panel, _| !panel.create),
        "Pull requests shows the list"
    );
    assert_one_creation_saved(&panel, &typed, "back at the list", cx);
    click_in_body(&app, "github-create", cx).await;
    assert!(
        panel.read_with(cx, |panel, _| panel.create),
        "New pull request opens the form"
    );
    assert_eq!(form(&panel, cx), typed, "the form holds what was typed");
    assert_one_creation_saved(&panel, &typed, "back in the form", cx);
}

/// The form opens on its saved draft once a pull request was opened in between: opening
/// one puts its review's text, here none, in the field the description shares, so the
/// description comes back from the draft saved as the form was left.
#[gpui::test]
async fn a_description_outlasts_a_pull_request_opened_in_between(cx: &mut TestAppContext) {
    let (_fixture, app, panel, script, cx) = typed_form(cx, rows_holding_seven(), " typed").await;
    let typed = form(&panel, cx);
    click_in_body(&app, "github-create-back", cx).await;
    answer_opening(&script);
    click_in_body(&app, "github-pr-7", cx).await;
    assert_eq!(
        panel.read_with(cx, |panel, cx| {
            let opened = panel.pull.as_ref().map(|pull| pull.number);
            (opened, panel.body.read(cx).value().to_string())
        }),
        (Some(7), String::new()),
        "the opened pull request's review has no text: {:?}",
        panel.read_with(cx, |panel, _| panel.error.clone())
    );
    click_in_body(&app, "github-create", cx).await;
    assert!(panel.read_with(cx, |panel, _| panel.create && panel.pull.is_none()));
    assert_eq!(form(&panel, cx), typed, "the form holds what was typed");
    assert_one_creation_saved(&panel, &typed, "back in the form", cx);
}

/// A form that could not be saved keeps its text through Pull requests and New pull
/// request: with a destination that names no repository the draft is not saved, as its
/// status says, and the window is all that holds what was typed since.
#[gpui::test]
async fn a_form_that_could_not_be_saved_keeps_its_description(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, _script, cx) = typed_form(cx, Vec::new(), " typed").await;
    let before = form(&panel, cx);
    // What the store took while the destination named a repository.
    let stored = creations(&drafts::load().expect("the draft store"));
    assert_eq!(stored.len(), 1);
    cx.update(|window, cx| {
        let destination = panel.read(cx).destination.clone();
        destination.update(cx, |input, cx| input.set_value("nowhere", window, cx));
        let description = panel.read(cx).body.read(cx).focus_handle(cx);
        description.focus(window, cx)
    });
    settle_panel(&app, cx).await;
    draw(cx);
    cx.simulate_input(" more");
    draw(cx);
    let typed = form(&panel, cx);
    assert_eq!(typed.1.len(), before.1.len() + " more".len());
    click_in_body(&app, "github-create-back", cx).await;
    assert!(panel.read_with(cx, |panel, _| !panel.create));
    click_in_body(&app, "github-create", cx).await;
    assert!(panel.read_with(cx, |panel, _| panel.create));
    assert_eq!(form(&panel, cx), typed, "the form holds what was typed");
    assert_eq!(
        creations(&drafts::load().expect("the draft store")),
        stored,
        "the store keeps the draft it took"
    );
}

/// The draft a store saved in an earlier run holds for `feature` onto `main` in
/// `fixture/repo`, as [`form`] gives one: Ready, with a title and a description.
fn stored_form() -> (String, String, bool) {
    ("Saved title".into(), "Saved description".into(), false)
}

/// A window on an empty repository whose draft store holds [`stored_form`], and a new
/// panel over it for `destination` with `head` as its branch, nothing typed: closed and
/// warm at 13 pt in a 1,480 × 973 window.
fn stored_panel<'a>(
    cx: &'a mut TestAppContext,
    destination: &str,
    head: &str,
) -> (
    tempfile::TempDir,
    Entity<GitTurtle>,
    Entity<Panel>,
    &'a mut VisualTestContext,
) {
    let (fixture, app, cx) = repository_window(cx);
    let (title, body, draft) = stored_form();
    drafts::save(Draft::Pull(NewPull {
        repository: Repository::parse("fixture/repo").unwrap(),
        title,
        body,
        head: "feature".into(),
        base: "main".into(),
        draft,
        expected_head: None,
        expected_base: None,
    }))
    .expect("the draft store");
    cx.update(|_, cx| cx.set_reduce_motion(true));
    let panel = cx.update(|window, cx| {
        let repo = app.read(cx).repository.clone().unwrap();
        let panel = cx.new(|cx| Panel::new(app.downgrade(), repo, head.into(), window, cx));
        panel.update(cx, |panel, cx| {
            panel.scripted = Some(github::Scripted::default());
            panel.account = Some(github::Scripted::LOGIN.into());
            panel.notice = None;
            panel
                .destination
                .update(cx, |input, cx| input.set_value(destination, window, cx));
            panel.close(window, cx);
        });
        panel
    });
    cx.simulate_resize(size(px(1480.), px(973.)));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    crate::tags::tests::draw(cx);
    (fixture, app, panel, cx)
}

/// A new panel opens the form on the draft saved for its head and base, whole: its
/// title, its description and Ready, with the store and Recover drafts holding it once.
/// It opened empty, and the first title typed was saved with no description over it.
#[gpui::test]
async fn a_new_panel_opens_the_form_on_its_saved_draft_whole(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, cx) = stored_panel(cx, "fixture/repo", "feature");
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    settle_panel(&app, cx).await;
    draw(cx);
    assert_eq!(form(&panel, cx), (String::new(), String::new(), true));
    click_in_body(&app, "github-create", cx).await;
    assert!(panel.read_with(cx, |panel, _| panel.create));
    assert_eq!(form(&panel, cx), stored_form(), "the saved draft, whole");
    assert_one_creation_saved(&panel, &stored_form(), "in the form", cx);
}

/// A form left for one repository opens for another on that repository's saved draft,
/// whole, both drafts kept: what it held is saved under the key it was left with, so the
/// form shows the draft of the key it has now rather than writing the other's text over
/// it. The title alone was saved over the second repository's draft.
#[gpui::test]
async fn a_form_reopened_for_another_repository_shows_the_draft_saved_for_it(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, cx) = stored_panel(cx, "fixture/other", "feature");
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    settle_panel(&app, cx).await;
    draw(cx);
    click_in_body(&app, "github-create", cx).await;
    for description in [false, true] {
        cx.update(|window, cx| {
            let panel = panel.read(cx);
            let field = if description {
                panel.body.read(cx).focus_handle(cx)
            } else {
                panel.title.read(cx).focus_handle(cx)
            };
            field.focus(window, cx)
        });
        draw(cx);
        cx.simulate_input("Typed for another");
        draw(cx);
    }
    let typed = form(&panel, cx);
    assert_eq!(typed.1, "Typed for another");
    click_in_body(&app, "github-create-back", cx).await;
    cx.update(|window, cx| {
        let destination = panel.read(cx).destination.clone();
        destination.update(cx, |input, cx| input.set_value("fixture/repo", window, cx));
    });
    draw(cx);
    click_in_body(&app, "github-create", cx).await;
    assert_eq!(form(&panel, cx), stored_form(), "the saved draft, whole");
    let stored = creations(&drafts::load().expect("the draft store"));
    assert!(
        stored.len() == 2 && stored.contains(&typed) && stored.contains(&stored_form()),
        "both drafts stay in the store: {stored:?}"
    );
}

/// A form opened before the saved drafts are read takes its draft as they land: the
/// panel's local read waits behind other work, the form opens with nothing in it, and
/// the read's landing fills it, where nothing was typed meanwhile.
#[gpui::test]
async fn a_form_opened_before_the_drafts_are_read_takes_its_draft_as_they_land(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, cx) = stored_panel(cx, "fixture/repo", "feature");
    let reading = app.read_with(cx, |app, _| app.operations.hold());
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    draw(cx);
    let create = whole_in_body(cx, "github-create", "New pull request");
    cx.simulate_click(create.center(), Modifiers::none());
    draw(cx);
    assert!(panel.read_with(cx, |panel, _| panel.create && panel.saved.is_empty()));
    assert_eq!(form(&panel, cx), (String::new(), String::new(), true));
    drop(reading);
    settle_panel(&app, cx).await;
    draw(cx);
    settle_panel(&app, cx).await;
    assert_eq!(form(&panel, cx), stored_form(), "the saved draft, whole");
    assert_one_creation_saved(&panel, &stored_form(), "in the form", cx);
}

/// An edit of the head or of the destination that brings the open form to a saved
/// draft's key shows that draft whole once the edited field is left, with its Ready, and
/// never saves an emptier draft over it: a form holding nothing takes it, and so does one
/// with a title typed for another head, whose title is saved under the key it was typed
/// for, since a form is never filled from two drafts. Nothing is taken while the field
/// keeps focus. A title typed while the destination named no repository has no key, so
/// it stays in the form and the saved draft stays in the store. The typed title was once
/// saved with no description over the saved draft; and later the form kept the typed
/// title over the saved description, and that was saved, the saved title gone.
async fn assert_an_edit_onto_a_saved_draft_takes_it(
    cx: &mut TestAppContext,
    destination: bool,
    titled: bool,
) {
    use crate::tags::tests::draw;
    // The field the edit types into starts with nothing in it.
    let (first, head) = if destination {
        ("", "feature")
    } else {
        ("fixture/repo", "")
    };
    let (_fixture, app, panel, cx) = stored_panel(cx, first, head);
    // An active window, as one typed in is: an inactive one reports no field left.
    cx.update(|window, cx| {
        window.activate_window();
        app.update(cx, |app, cx| app.open_github(window, cx))
    });
    settle_panel(&app, cx).await;
    draw(cx);
    click_in_body(&app, "github-create", cx).await;
    assert_eq!(form(&panel, cx), (String::new(), String::new(), true));
    if titled {
        cx.update(|window, cx| {
            let title = panel.read(cx).title.read(cx).focus_handle(cx);
            title.focus(window, cx)
        });
        draw(cx);
        cx.simulate_input("Typed title");
        draw(cx);
    }
    let typed = form(&panel, cx);
    cx.update(|window, cx| {
        let panel = panel.read(cx);
        let field = if destination {
            &panel.destination
        } else {
            &panel.head
        };
        field.read(cx).focus_handle(cx).focus(window, cx)
    });
    draw(cx);
    cx.simulate_input(if destination {
        "fixture/repo"
    } else {
        "feature"
    });
    settle_panel(&app, cx).await;
    draw(cx);
    assert_eq!(
        form(&panel, cx),
        typed,
        "nothing is taken while the field keeps focus"
    );
    leave_for_title(&app, &panel, cx).await;
    let expected = if titled && destination {
        typed.clone()
    } else {
        stored_form()
    };
    assert_eq!(
        form(&panel, cx),
        expected,
        "the form once the field is left"
    );
    // Pull requests saves what the form holds.
    click_in_body(&app, "github-create-back", cx).await;
    let stored = creations(&drafts::load().expect("the draft store"));
    let kept = if titled && !destination {
        vec![stored_form(), typed]
    } else {
        vec![stored_form()]
    };
    assert_eq!(
        stored, kept,
        "the saved draft stays whole in the store, beside a title typed for another head"
    );
}

#[gpui::test]
async fn a_head_edited_onto_a_saved_draft_shows_it_whole(cx: &mut TestAppContext) {
    assert_an_edit_onto_a_saved_draft_takes_it(cx, false, false).await;
}

#[gpui::test]
async fn a_head_edited_onto_a_saved_draft_keeps_its_description(cx: &mut TestAppContext) {
    assert_an_edit_onto_a_saved_draft_takes_it(cx, false, true).await;
}

#[gpui::test]
async fn a_destination_edited_onto_a_saved_draft_keeps_its_description(cx: &mut TestAppContext) {
    assert_an_edit_onto_a_saved_draft_takes_it(cx, true, true).await;
}

/// The draft a store holds for `head` onto `main` in `repository`: Ready, its title and
/// its description naming both, so a test tells whose text a form or a key holds.
fn keyed(repository: &str, head: &str) -> Draft {
    let (title, body, draft) = shows(repository, head);
    Draft::Pull(NewPull {
        repository: Repository::parse(repository).unwrap(),
        title,
        body,
        head: head.into(),
        base: "main".into(),
        draft,
        expected_head: None,
        expected_base: None,
    })
}

/// What [`form`] gives for a form that shows [`keyed`]'s draft whole.
fn shows(repository: &str, head: &str) -> (String, String, bool) {
    (
        format!("Title of {head} in {repository}"),
        format!("Description of {head} in {repository}"),
        false,
    )
}

/// The creation drafts `saved` holds, each as its key, title, description and Draft, in
/// the keys' order.
fn by_key(saved: &[Draft]) -> Vec<(String, String, String, bool)> {
    let mut kept: Vec<_> = saved
        .iter()
        .filter_map(|draft| match draft {
            Draft::Pull(pull) => Some((
                draft.key(),
                pull.title.clone(),
                pull.body.clone(),
                pull.draft,
            )),
            _ => None,
        })
        .collect();
    kept.sort();
    kept
}

/// One of [`by_key`]'s entries: `text`, as [`form`] gives it, kept for `head` onto `main`
/// in `repository`.
fn under(
    repository: &str,
    head: &str,
    (title, body, draft): (String, String, bool),
) -> (String, String, String, bool) {
    (
        format!("create:{repository}:{head}:main"),
        title,
        body,
        draft,
    )
}

/// Asserts that the draft store on disk and Recover drafts each hold exactly `expected`,
/// every key once, with the saves queued so far landed.
async fn assert_kept(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    expected: &[(String, String, String, bool)],
    when: &str,
    cx: &mut VisualTestContext,
) {
    settle_panel(app, cx).await;
    let mut expected = expected.to_vec();
    expected.sort();
    assert_eq!(
        by_key(&drafts::load().expect("the draft store")),
        expected,
        "{when}: the draft store"
    );
    assert_eq!(
        panel.read_with(cx, |panel, _| by_key(&panel.saved)),
        expected,
        "{when}: Recover drafts lists each draft once"
    );
}

/// A window on an empty repository whose draft store holds `stored`, and a new panel over
/// it for `destination` with `head` as its branch, open at 13 pt in a 1,480 × 973 window
/// with New pull request chosen by a click. Its requests are answered from the script.
async fn keyed_form<'a>(
    cx: &'a mut TestAppContext,
    destination: &str,
    head: &str,
    stored: &[Draft],
) -> (
    tempfile::TempDir,
    Entity<GitTurtle>,
    Entity<Panel>,
    github::Scripted,
    &'a mut VisualTestContext,
) {
    use crate::tags::tests::draw;
    let (fixture, app, cx) = repository_window(cx);
    for draft in stored {
        drafts::save(draft.clone()).expect("the draft store");
    }
    let script = github::Scripted::default();
    let scripted = script.clone();
    cx.update(|_, cx| cx.set_reduce_motion(true));
    let panel = cx.update(|window, cx| {
        let repo = app.read(cx).repository.clone().unwrap();
        let panel = cx.new(|cx| Panel::new(app.downgrade(), repo, head.into(), window, cx));
        panel.update(cx, |panel, cx| {
            panel.scripted = Some(scripted);
            panel.account = Some(github::Scripted::LOGIN.into());
            panel.notice = None;
            panel
                .destination
                .update(cx, |input, cx| input.set_value(destination, window, cx));
            panel.close(window, cx);
        });
        panel
    });
    cx.simulate_resize(size(px(1480.), px(973.)));
    cx.update(|window, cx| appearance::apply_text_sizes(13, 12, window, cx));
    draw(cx);
    // An active window, as one typed in is: an inactive one reports no field left.
    cx.update(|window, cx| {
        window.activate_window();
        app.update(cx, |app, cx| app.open_github(window, cx))
    });
    settle_panel(&app, cx).await;
    draw(cx);
    click_in_body(&app, "github-create", cx).await;
    assert!(
        panel.read_with(cx, |panel, _| panel.create),
        "New pull request opens the form"
    );
    (fixture, app, panel, script, cx)
}

/// A field of the form that names its draft's key.
#[derive(Clone, Copy, Debug)]
enum Names {
    Destination,
    Head,
}

/// Types `text` at the end of what `field` holds, after `erased` Backspaces there, each
/// one keystroke of the view's own: focus stays in the field.
fn retype(
    panel: &Entity<Panel>,
    field: Names,
    erased: usize,
    text: &str,
    cx: &mut VisualTestContext,
) {
    use crate::tags::tests::draw;
    cx.update(|window, cx| {
        let panel = panel.read(cx);
        let field = match field {
            Names::Destination => &panel.destination,
            Names::Head => &panel.head,
        };
        field.read(cx).focus_handle(cx).focus(window, cx)
    });
    draw(cx);
    cx.simulate_keystrokes("end");
    for _ in 0..erased {
        cx.simulate_keystrokes("backspace");
    }
    cx.simulate_input(text);
    draw(cx);
}

/// Types `text` into the form's title, at its end, and leaves focus there.
fn title_typed(panel: &Entity<Panel>, text: &str, cx: &mut VisualTestContext) {
    use crate::tags::tests::draw;
    cx.update(|window, cx| {
        let title = panel.read(cx).title.read(cx).focus_handle(cx);
        title.focus(window, cx)
    });
    draw(cx);
    cx.simulate_keystrokes("end");
    cx.simulate_input(text);
    draw(cx);
}

/// Focus leaves the field it is in for the form's title, as a click on the title takes
/// it, and the frames and saves that follow land: an edit of the field has settled.
async fn leave_for_title(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    cx: &mut VisualTestContext,
) {
    title_typed(panel, "", cx);
    settle_panel(app, cx).await;
    crate::tags::tests::draw(cx);
}

/// What the form's save status reads.
fn status(panel: &Entity<Panel>, cx: &mut VisualTestContext) -> String {
    panel.read_with(cx, |panel, _| panel.save_status.to_string())
}

/// Route (a): a name typed through another draft's key takes nothing there and saves
/// nothing there. With drafts saved for a short name and for a longer one that begins with
/// it, an empty form whose `field` is typed to the longer one, a key at a time, passes
/// through the shorter one's key with nothing taken; the quiet period then passes with
/// focus still in the field and nothing is saved; and once the field is left the form
/// shows the longer one's draft whole, and says it restored it. The store and Recover
/// drafts hold both drafts as they were throughout, each once. At the shorter name the
/// form took that draft, at the longer one, no longer empty, it took nothing, and the
/// save that followed wrote the shorter one's text over the longer one's draft.
async fn assert_a_name_typed_through_a_drafts_key_takes_nothing_there(
    cx: &mut TestAppContext,
    field: Names,
) {
    use crate::tags::tests::draw;
    let (destination, head, short, long, stored) = match field {
        Names::Head => (
            "acme/app",
            "",
            "fix",
            "fix-2",
            [keyed("acme/app", "fix"), keyed("acme/app", "fix-2")],
        ),
        Names::Destination => (
            "",
            "fix",
            "acme/app",
            "acme/app-web",
            [keyed("acme/app", "fix"), keyed("acme/app-web", "fix")],
        ),
    };
    let longer = match field {
        Names::Head => shows("acme/app", "fix-2"),
        Names::Destination => shows("acme/app-web", "fix"),
    };
    let all = by_key(&stored);
    let (_fixture, app, panel, _script, cx) = keyed_form(cx, destination, head, &stored).await;
    let empty = (String::new(), String::new(), true);
    assert_eq!(form(&panel, cx), empty, "the form opens empty");
    retype(&panel, field, 0, short, cx);
    settle_panel(&app, cx).await;
    draw(cx);
    assert_eq!(
        form(&panel, cx),
        empty,
        "{field:?} typed as far as {short}: the form takes nothing of that key's draft"
    );
    retype(&panel, field, 0, &long[short.len()..], cx);
    cx.executor().advance_clock(DRAFT_QUIET_PERIOD * 2);
    settle_panel(&app, cx).await;
    draw(cx);
    assert_eq!(
        form(&panel, cx),
        empty,
        "{field:?} typed to {long}, focus still in it: nothing is taken yet"
    );
    assert_kept(&app, &panel, &all, "typed, the quiet period over", cx).await;
    leave_for_title(&app, &panel, cx).await;
    assert_eq!(
        form(&panel, cx),
        longer,
        "{field:?} left at {long}: the form shows that key's draft whole"
    );
    assert_eq!(status(&panel, cx), "Draft restored locally", "{field:?}");
    assert_kept(&app, &panel, &all, "the field left", cx).await;
    // Pull requests saves what the form holds.
    click_in_body(&app, "github-create-back", cx).await;
    assert_kept(&app, &panel, &all, "after Pull requests", cx).await;
}

#[gpui::test]
async fn a_head_typed_through_a_drafts_key_takes_nothing_there(cx: &mut TestAppContext) {
    assert_a_name_typed_through_a_drafts_key_takes_nothing_there(cx, Names::Head).await;
}

#[gpui::test]
async fn a_destination_typed_through_a_drafts_key_takes_nothing_there(cx: &mut TestAppContext) {
    assert_a_name_typed_through_a_drafts_key_takes_nothing_there(cx, Names::Destination).await;
}

/// Route (b), and back and forth: a form that opened on one head's saved draft and has
/// its head edited to another's shows the other's draft whole, and edited back shows the
/// first one's again, three times over, the store and Recover drafts holding both drafts
/// as they were each time. Text then typed into the title under the second head is that
/// head's: it is saved under that key as the head is edited away, the first head's draft
/// comes back as it was, and the second head shows what was typed. A saved copy counted
/// only as the form opened, so nothing was taken at the second head and the first head's
/// text was saved over the second one's draft.
#[gpui::test]
async fn a_head_edited_between_two_drafts_shows_each_whole(cx: &mut TestAppContext) {
    let stored = [keyed("acme/app", "alpha"), keyed("acme/app", "beta")];
    let all = by_key(&stored);
    let (_fixture, app, panel, _script, cx) = keyed_form(cx, "acme/app", "alpha", &stored).await;
    let (alpha, beta) = (shows("acme/app", "alpha"), shows("acme/app", "beta"));
    assert_eq!(form(&panel, cx), alpha, "the form opens on alpha's draft");
    assert_eq!(status(&panel, cx), "Draft restored locally", "as it opens");
    for turn in 0..3 {
        retype(&panel, Names::Head, "alpha".len(), "beta", cx);
        leave_for_title(&app, &panel, cx).await;
        assert_eq!(form(&panel, cx), beta, "turn {turn}: beta's draft, whole");
        assert_eq!(status(&panel, cx), "Draft restored locally", "turn {turn}");
        assert_kept(&app, &panel, &all, &format!("turn {turn}, at beta"), cx).await;
        retype(&panel, Names::Head, "beta".len(), "alpha", cx);
        leave_for_title(&app, &panel, cx).await;
        assert_eq!(form(&panel, cx), alpha, "turn {turn}: alpha's draft, whole");
        assert_kept(&app, &panel, &all, &format!("turn {turn}, at alpha"), cx).await;
    }
    retype(&panel, Names::Head, "alpha".len(), "beta", cx);
    title_typed(&panel, " and more", cx);
    assert_ne!(status(&panel, cx), "Draft restored locally", "edited");
    let edited = (format!("{} and more", beta.0), beta.1.clone(), beta.2);
    assert_eq!(form(&panel, cx), edited, "typed under beta");
    retype(&panel, Names::Head, "beta".len(), "alpha", cx);
    leave_for_title(&app, &panel, cx).await;
    assert_eq!(form(&panel, cx), alpha, "alpha's draft is as it was");
    let kept = [
        under("acme/app", "alpha", alpha),
        under("acme/app", "beta", edited.clone()),
    ];
    assert_kept(&app, &panel, &kept, "beta edited, back at alpha", cx).await;
    retype(&panel, Names::Head, "alpha".len(), "beta", cx);
    leave_for_title(&app, &panel, cx).await;
    assert_eq!(
        form(&panel, cx),
        edited,
        "beta shows what was typed under it"
    );
    click_in_body(&app, "github-create-back", cx).await;
    assert_kept(&app, &panel, &kept, "after Pull requests", cx).await;
}

/// Route (c): a form that holds a title and no description, its head edited onto one with
/// a saved title and description, shows that draft whole, and the title it held is saved
/// under the head it was typed for. The form became its own title over the other draft's
/// description and was saved so under the other head, whose title was gone.
#[gpui::test]
async fn a_titled_form_edited_onto_a_draft_shows_that_draft_whole(cx: &mut TestAppContext) {
    let stored = [keyed("acme/app", "beta")];
    let (_fixture, app, panel, _script, cx) = keyed_form(cx, "acme/app", "alpha", &stored).await;
    assert_eq!(form(&panel, cx), (String::new(), String::new(), true));
    title_typed(&panel, "Typed title", cx);
    let beta = shows("acme/app", "beta");
    let kept = [
        under(
            "acme/app",
            "alpha",
            ("Typed title".into(), String::new(), true),
        ),
        under("acme/app", "beta", beta.clone()),
    ];
    // The edit's first keystroke saves the title under the head it was typed for, with
    // no quiet period waited out and the field not yet left.
    retype(&panel, Names::Head, 0, "-", cx);
    assert_kept(&app, &panel, &kept, "one keystroke into the edit", cx).await;
    retype(&panel, Names::Head, "alpha-".len(), "beta", cx);
    leave_for_title(&app, &panel, cx).await;
    assert_eq!(
        form(&panel, cx),
        beta,
        "the form is never filled from two drafts"
    );
    assert_eq!(status(&panel, cx), "Draft restored locally");
    assert_kept(&app, &panel, &kept, "the head left at beta", cx).await;
    click_in_body(&app, "github-create-back", cx).await;
    assert_kept(&app, &panel, &kept, "after Pull requests", cx).await;
}

/// The review step shows exactly what the form shows: with the head typed onto a saved
/// draft's and Review submission… clicked from there, the click itself settling the
/// edit, the confirmation holds that draft's title, description and Ready for that head,
/// which is what the form shows. It reviewed the form's own title over the other draft's
/// description.
#[gpui::test]
async fn a_review_after_a_head_edit_shows_what_the_form_shows(cx: &mut TestAppContext) {
    let stored = [keyed("acme/app", "beta")];
    let (_fixture, app, panel, script, cx) = keyed_form(cx, "acme/app", "alpha", &stored).await;
    title_typed(&panel, "Typed title", cx);
    retype(&panel, Names::Head, "alpha".len(), "beta", cx);
    script.answer(200, format!(r#"{{"sha":"{}"}}"#, "1".repeat(40)));
    script.answer(200, format!(r#"{{"sha":"{}"}}"#, "2".repeat(40)));
    click_in_body(&app, "github-review-submit", cx).await;
    let reviewed = panel.read_with(cx, |panel, _| match &panel.confirm {
        Some(Confirmation {
            action: Action::Create(pull),
            ..
        }) => Some((
            pull.head.clone(),
            (pull.title.clone(), pull.body.clone(), pull.draft),
        )),
        _ => None,
    });
    let beta = shows("acme/app", "beta");
    assert_eq!(
        reviewed,
        Some(("beta".to_string(), beta.clone())),
        "the creation reviewed: {:?}",
        panel.read_with(cx, |panel, _| panel.error.clone())
    );
    assert_eq!(form(&panel, cx), beta, "the form shows what is reviewed");
    assert_eq!(
        status(&panel, cx),
        "Draft restored locally",
        "the review saves nothing of a draft just restored"
    );
    assert_eq!(script.asked("POST", "/pulls"), 0, "nothing is sent");
}

/// Text that has no key takes no other draft's place: typed while the destination names
/// no repository it is saved nowhere, and with the destination then typed onto a
/// repository that has a draft saved for the form's head and base, the form keeps what
/// was typed, the saved draft stays in the store and in Recover drafts, and the status
/// says the text is not saved and why. The form took the saved description under the
/// typed title, and that was saved over the saved draft.
#[gpui::test]
async fn text_typed_with_no_key_takes_no_saved_drafts_place(cx: &mut TestAppContext) {
    let stored = [keyed("acme/app", "fix")];
    let all = by_key(&stored);
    let (_fixture, app, panel, _script, cx) = keyed_form(cx, "", "fix", &stored).await;
    title_typed(&panel, "Typed title", cx);
    retype(&panel, Names::Destination, 0, "acme/app", cx);
    leave_for_title(&app, &panel, cx).await;
    let typed = ("Typed title".to_string(), String::new(), true);
    assert_eq!(form(&panel, cx), typed, "the form keeps what was typed");
    assert_eq!(status(&panel, cx), DRAFT_HELD);
    assert_kept(&app, &panel, &all, "the destination left", cx).await;
    click_in_body(&app, "github-create-back", cx).await;
    assert_kept(&app, &panel, &all, "after Pull requests", cx).await;
    click_in_body(&app, "github-create", cx).await;
    assert_eq!(
        form(&panel, cx),
        typed,
        "the form still holds what was typed"
    );
    // Discarded in Recover drafts, the saved draft gives its key up to the form's text.
    let saved = panel.read_with(cx, |panel, _| panel.saved[0].clone());
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.discard_draft(saved, window, cx)));
    for _ in 0..2 {
        settle_panel(&app, cx).await;
        crate::tags::tests::draw(cx);
    }
    let kept = [under("acme/app", "fix", typed.clone())];
    assert_kept(&app, &panel, &kept, "the saved draft discarded", cx).await;
    assert_eq!(form(&panel, cx), typed);
}

/// The saved drafts' read follows the same rule: a form opened before they are read, a
/// title typed into it meanwhile and saved nowhere yet, keeps that title as the read
/// lands with a draft saved for its key, which stays in the store and in Recover drafts.
/// The form took the saved description under the typed title.
#[gpui::test]
async fn text_typed_before_the_drafts_are_read_takes_no_saved_drafts_place(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, cx) = stored_panel(cx, "fixture/repo", "feature");
    let reading = app.read_with(cx, |app, _| app.operations.hold());
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    draw(cx);
    let create = whole_in_body(cx, "github-create", "New pull request");
    cx.simulate_click(create.center(), Modifiers::none());
    draw(cx);
    assert!(panel.read_with(cx, |panel, _| panel.create && panel.saved.is_empty()));
    title_typed(&panel, "Typed title", cx);
    drop(reading);
    for _ in 0..2 {
        settle_panel(&app, cx).await;
        draw(cx);
    }
    let typed = ("Typed title".to_string(), String::new(), true);
    assert_eq!(form(&panel, cx), typed, "the form keeps what was typed");
    assert_eq!(status(&panel, cx), DRAFT_HELD);
    assert_one_creation_saved(&panel, &stored_form(), "the read landed", cx);
}

/// What [`held_form`] types into the form, as [`form`] gives it.
fn held_text() -> (String, String, bool) {
    ("Typed title".into(), "Typed description".into(), true)
}

/// The one creation draft [`held_form`]'s store holds, as [`by_key`] gives it.
fn held_out() -> Vec<(String, String, String, bool)> {
    by_key(&[keyed("acme/app", "fix")])
}

/// A form whose text is saved nowhere: with a draft stored for `fix` onto `main` in
/// `acme/app`, and `beside` it, the form opens with no destination, a title and a
/// description are typed into it, and the destination is typed to `acme/app` and left.
/// The form keeps what was typed, the store keeps its draft, and the status says that
/// the text is not saved and that keeping the window open keeps it ([`assert_held`]).
async fn held_form(
    cx: &mut TestAppContext,
    beside: Option<Draft>,
) -> (
    tempfile::TempDir,
    Entity<GitTurtle>,
    Entity<Panel>,
    github::Scripted,
    &mut VisualTestContext,
) {
    use crate::tags::tests::draw;
    let stored: Vec<_> = [keyed("acme/app", "fix")]
        .into_iter()
        .chain(beside)
        .collect();
    let (fixture, app, panel, script, cx) = keyed_form(cx, "", "fix", &stored).await;
    let (title, description, _) = held_text();
    title_typed(&panel, &title, cx);
    cx.update(|window, cx| {
        let field = panel.read(cx).body.read(cx).focus_handle(cx);
        field.focus(window, cx)
    });
    draw(cx);
    cx.simulate_input(&description);
    draw(cx);
    retype(&panel, Names::Destination, 0, "acme/app", cx);
    leave_for_title(&app, &panel, cx).await;
    assert_held(&app, &panel, "the destination left", cx).await;
    (fixture, app, panel, script, cx)
}

/// Asserts that the form is shown holding [`held_text`] whole, that its status says the
/// text is not saved, and that the store and Recover drafts hold the stored draft alone,
/// as it was.
async fn assert_held(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    when: &str,
    cx: &mut VisualTestContext,
) {
    assert!(
        panel.read_with(cx, |panel, _| panel.create),
        "{when}: the form is shown"
    );
    assert_eq!(form(panel, cx), held_text(), "{when}: the form, whole");
    assert_eq!(status(panel, cx), DRAFT_HELD, "{when}: the status");
    assert_kept(app, panel, &held_out(), when, cx).await;
}

/// The form is left and a pull request opened, each press a click answered from the
/// script: Pull requests shows the list, Refresh PRs lists pull request 7 and its row
/// opens it, which gives the description's field to its review.
async fn open_seven_from_the_form(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    script: &github::Scripted,
    cx: &mut VisualTestContext,
) {
    click_in_body(app, "github-create-back", cx).await;
    assert!(
        panel.read_with(cx, |panel, _| !panel.create),
        "Pull requests shows the list"
    );
    let listed = serde_json::json!([listed_pull(7, "fixture:feature", "main")]);
    script.answer(200, listed.to_string());
    click_in_body(app, "github-refresh", cx).await;
    answer_opening(script);
    click_in_body(app, "github-pr-7", cx).await;
    assert_eq!(
        panel.read_with(cx, |panel, _| panel.pull.as_ref().map(|pull| pull.number)),
        Some(7),
        "pull request 7 is open: {:?}",
        panel.read_with(cx, |panel, _| panel.error.clone())
    );
}

/// What the description's field holds, the form's or an open pull request's review's.
fn shared_field(panel: &Entity<Panel>, cx: &mut VisualTestContext) -> String {
    panel.read_with(cx, |panel, cx| panel.body.read(cx).value().to_string())
}

/// Text the form holds unsaved is not lost while the window lives: with the status
/// saying that keeping the window open keeps it, Pull requests, Refresh PRs and a pull
/// request's opening, which empties the field the description shares, are followed by
/// New pull request, and the form holds the title, the description and Draft as they
/// were typed, its status says again that they are not saved, and the store holds its
/// one draft as it was. The form came back with its title and no description, which was
/// nowhere.
#[gpui::test]
async fn text_held_unsaved_outlasts_a_pull_request_opened_in_between(cx: &mut TestAppContext) {
    let (_fixture, app, panel, script, cx) = held_form(cx, None).await;
    open_seven_from_the_form(&app, &panel, &script, cx).await;
    assert_eq!(shared_field(&panel, cx), "", "the review has no text yet");
    assert_kept(&app, &panel, &held_out(), "the pull request open", cx).await;
    click_in_body(&app, "github-create", cx).await;
    assert_held(&app, &panel, "back in the form", cx).await;
}

/// The same with a review's saved text taking the description's place: the opened pull
/// request's review is restored into the shared field, and New pull request gives the
/// form its own text back, none of the review's, whose draft stays as it was.
#[gpui::test]
async fn text_held_unsaved_outlasts_a_review_taking_its_place(cx: &mut TestAppContext) {
    let review = Draft::Review(ReviewDraft {
        pull: listed_pull(7, "fixture:feature", "main")
            .capture(Repository::parse("acme/app").unwrap()),
        body: "Review text".into(),
        event: ReviewEvent::Comment,
        comments: vec![],
        composing: None,
        discussion: true,
    });
    let (_fixture, app, panel, script, cx) = held_form(cx, Some(review)).await;
    open_seven_from_the_form(&app, &panel, &script, cx).await;
    assert_eq!(
        shared_field(&panel, cx),
        "Review text",
        "the review's text takes the description's place"
    );
    click_in_body(&app, "github-create", cx).await;
    assert_held(&app, &panel, "back in the form", cx).await;
    let reviews: Vec<_> = drafts::load()
        .expect("the draft store")
        .iter()
        .filter(|draft| matches!(draft, Draft::Review(_)))
        .map(|draft| draft.text().to_string())
        .collect();
    assert_eq!(
        reviews,
        ["Review text"],
        "the review's draft stays as it was"
    );
}

/// The panel is closed and `app` opens it again.
async fn close_and_open(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    cx: &mut VisualTestContext,
) {
    use crate::tags::tests::draw;
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.close(window, cx)));
    settle_panel(app, cx).await;
    draw(cx);
    assert!(panel.read_with(cx, |panel, _| panel.closed), "closed");
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    settle_panel(app, cx).await;
    draw(cx);
    assert!(panel.read_with(cx, |panel, _| !panel.closed), "open again");
}

/// The same with the panel closed and opened again, on the form and then on the pull
/// request opened in between: the panel reopens on the form whole, its status as it
/// was, and what it keeps of the form while a pull request is shown outlasts its close.
#[gpui::test]
async fn text_held_unsaved_outlasts_the_panel_closed_and_opened_again(cx: &mut TestAppContext) {
    let (_fixture, app, panel, script, cx) = held_form(cx, None).await;
    close_and_open(&app, &panel, cx).await;
    assert_held(&app, &panel, "the panel reopened on the form", cx).await;
    open_seven_from_the_form(&app, &panel, &script, cx).await;
    close_and_open(&app, &panel, cx).await;
    assert_eq!(
        panel.read_with(cx, |panel, _| panel.pull.as_ref().map(|pull| pull.number)),
        Some(7),
        "the panel reopens on the pull request"
    );
    assert_kept(
        &app,
        &panel,
        &held_out(),
        "reopened on the pull request",
        cx,
    )
    .await;
    click_in_body(&app, "github-create", cx).await;
    assert_held(&app, &panel, "back in the form", cx).await;
}

/// A closed panel whose form holds text saved nowhere outlasts the warm cache's bound:
/// with nine other panels closed after it, one more than the cache keeps, the same panel
/// opens again on the form whole, its status as it was. The oldest closed panel went
/// with the ninth, and the next opening built a new, empty one in the same window.
#[gpui::test]
async fn text_held_unsaved_outlasts_the_warm_caches_bound(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, _script, cx) = held_form(cx, None).await;
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.close(window, cx)));
    settle_panel(&app, cx).await;
    draw(cx);
    let kept = cx.update(|_, cx| {
        let warm = cx.default_global::<WarmPanels>();
        for other in 0..9 {
            warm.retain(WarmPanel {
                owner: app.entity_id(),
                worktree: format!("/another/worktree/{other}").into(),
                panel: panel.clone(),
                bytes: 0,
                unsaved: false,
            });
        }
        warm.0.len()
    });
    assert_eq!(kept, 8, "the cache keeps eight panels");
    cx.update(|window, cx| app.update(cx, |app, cx| app.open_github(window, cx)));
    settle_panel(&app, cx).await;
    draw(cx);
    assert!(
        panel.read_with(cx, |panel, _| !panel.closed),
        "the panel that holds the text opens again"
    );
    assert_held(&app, &panel, "the panel reopened", cx).await;
}

/// Held text gains its key once the draft that held it is discarded, and is then saved
/// whole: discarded in Recover drafts while a pull request is shown, the saved draft is
/// gone from the store, and New pull request opens the form on the title and the
/// description as they were typed and saves them under the key its fields name.
#[gpui::test]
async fn text_held_unsaved_is_saved_once_the_other_draft_is_discarded(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, script, cx) = held_form(cx, None).await;
    open_seven_from_the_form(&app, &panel, &script, cx).await;
    let saved = panel.read_with(cx, |panel, _| panel.saved[0].clone());
    assert_eq!(by_key(std::slice::from_ref(&saved)), held_out());
    cx.update(|window, cx| panel.update(cx, |panel, cx| panel.discard_draft(saved, window, cx)));
    for _ in 0..2 {
        settle_panel(&app, cx).await;
        draw(cx);
    }
    assert_kept(&app, &panel, &[], "the saved draft discarded", cx).await;
    click_in_body(&app, "github-create", cx).await;
    assert_eq!(form(&panel, cx), held_text(), "the form, whole");
    let kept = [under("acme/app", "fix", held_text())];
    assert_kept(&app, &panel, &kept, "back in the form", cx).await;
    assert_eq!(status(&panel, cx), "Draft saved locally");
}

/// A creation confirmed from held text uses up no draft but its own, which is the text
/// that was sent and nothing in the store: after a pull request opened in between, the
/// review step shows the title and the description as they were typed, for the
/// destination, head and base the form names; once the answer names the pull request,
/// the draft saved for that key, never sent, is still in the store and in Recover drafts
/// as it was, and New pull request opens on it whole, the sent text gone with its
/// creation.
#[gpui::test]
async fn a_creation_confirmed_from_text_held_unsaved_uses_up_no_saved_draft(
    cx: &mut TestAppContext,
) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, script, cx) = held_form(cx, None).await;
    open_seven_from_the_form(&app, &panel, &script, cx).await;
    click_in_body(&app, "github-create", cx).await;
    // The head's and the base's commits, which the review step reads and Send reads again.
    let identities = |script: &github::Scripted| {
        script.answer(200, format!(r#"{{"sha":"{}"}}"#, "1".repeat(40)));
        script.answer(200, format!(r#"{{"sha":"{}"}}"#, "2".repeat(40)));
    };
    identities(&script);
    click_in_body(&app, "github-review-submit", cx).await;
    let reviewed = panel.read_with(cx, |panel, _| match &panel.confirm {
        Some(Confirmation {
            action: Action::Create(pull),
            ..
        }) => Some((
            Draft::Pull(pull.clone()).key(),
            (pull.title.clone(), pull.body.clone(), pull.draft),
        )),
        _ => None,
    });
    assert_eq!(
        reviewed,
        Some(("create:acme/app:fix:main".to_string(), held_text())),
        "the creation reviewed: {:?}",
        panel.read_with(cx, |panel, _| panel.error.clone())
    );
    identities(&script);
    script.answer(201, r#"{"number":203}"#);
    let send = whole_in_body(cx, "github-confirm-send", "Send to GitHub");
    cx.simulate_click(send.center(), Modifiers::none());
    for _ in 0..2 {
        settle_panel(&app, cx).await;
        draw(cx);
    }
    assert_eq!(
        script.asked("POST", "/pulls"),
        1,
        "one creation was sent: {:?}",
        panel.read_with(cx, |panel, _| panel.error.clone())
    );
    assert_eq!(
        panel
            .read_with(cx, |panel, _| panel.notice.clone())
            .as_deref(),
        Some("Pull request #203 created. Refresh PRs to open it.")
    );
    assert_kept(&app, &panel, &held_out(), "the creation confirmed", cx).await;
    click_in_body(&app, "github-create", cx).await;
    assert_eq!(
        form(&panel, cx),
        shows("acme/app", "fix"),
        "the form opens on the draft saved for its key, the sent text gone"
    );
    assert_eq!(status(&panel, cx), "Draft restored locally");
    assert_kept(&app, &panel, &held_out(), "back in the form", cx).await;
}

/// The draft [`creation_panel`]'s form holds, as [`form`] gives one.
fn sent_form() -> (String, String, bool) {
    (
        "Keep the review's place".into(),
        "Typed description".into(),
        true,
    )
}

/// What a creation's end leaves of its draft, once the saves it queued have landed: the
/// New pull request form, chosen again by a click where the end closed it, then the
/// creation drafts of the store on disk and of Recover drafts, each as [`form`] gives one.
async fn left_of_the_draft(
    app: &Entity<GitTurtle>,
    panel: &Entity<Panel>,
    cx: &mut VisualTestContext,
) -> [Vec<(String, String, bool)>; 3] {
    use crate::tags::tests::draw;
    for _ in 0..2 {
        settle_panel(app, cx).await;
        draw(cx);
    }
    if !panel.read_with(cx, |panel, _| panel.create) {
        click_in_body(app, "github-create", cx).await;
        settle_panel(app, cx).await;
        draw(cx);
    }
    assert!(
        panel.read_with(cx, |panel, _| panel.create),
        "New pull request opens the form"
    );
    [
        vec![form(panel, cx)],
        creations(&drafts::load().expect("the draft store")),
        panel.read_with(cx, |panel, _| creations(&panel.saved)),
    ]
}

/// A creation GitHub confirms uses up its draft: once the answer names the pull request,
/// by the whole pull request or by its number alone (`answer`), New pull request opens
/// the form empty for that head and base, the store on disk holds the draft no more and
/// Recover drafts no longer counts it; the notice names the pull request and says nothing
/// of a draft. The form reopened on the title and the description just sent, the store
/// and Recover drafts still holding them, and sending them again could only be refused.
async fn assert_a_confirmed_creation_uses_up_its_draft(cx: &mut TestAppContext, answer: &str) {
    let (_fixture, app, panel, script, cx) = creation_panel(cx, Vec::new(), "feature");
    let at = (13, 1480., 973.);
    send_creation(&app, &panel, &script, at, (201, answer), cx).await;
    let notice = panel
        .read_with(cx, |panel, _| panel.notice.clone())
        .expect("the creation's notice");
    assert!(
        notice.contains("ull request #203 created.") && !notice.contains("draft remains"),
        "the notice names the pull request and no draft: {notice}"
    );
    let counted = panel.read_with(cx, |panel, _| panel.saved.len());
    let [form, stored, listed] = left_of_the_draft(&app, &panel, cx).await;
    assert_eq!(
        (counted, form, stored, listed),
        (
            0,
            vec![(String::new(), String::new(), true)],
            Vec::new(),
            Vec::new()
        ),
        "what Recover drafts counts as the creation lands, then the reopened form, the \
         draft store and Recover drafts"
    );
    assert_eq!(script.asked("POST", "/pulls"), 1, "one creation was sent");
}

#[gpui::test]
async fn a_confirmed_creation_uses_up_its_draft(cx: &mut TestAppContext) {
    assert_a_confirmed_creation_uses_up_its_draft(cx, &made(true).to_string()).await;
}

#[gpui::test]
async fn a_creation_confirmed_by_its_number_uses_up_its_draft(cx: &mut TestAppContext) {
    assert_a_confirmed_creation_uses_up_its_draft(cx, r#"{"number":203}"#).await;
}

/// A creation that fails keeps its draft whole, whatever the failure: after each of
/// [`FAILED_CREATIONS`], sent from the form the one before left, the form still holds the
/// title and the description, and the store and Recover drafts hold that draft once. An
/// uncertain outcome's text is the person's to send again or to keep.
#[gpui::test]
async fn a_creation_that_fails_keeps_its_draft(cx: &mut TestAppContext) {
    use crate::tags::tests::draw;
    let (_fixture, app, panel, script, cx) = creation_panel(cx, Vec::new(), "feature");
    open_creation(&app, (13, 1480., 973.), cx).await;
    for (kind, status, said) in FAILED_CREATIONS {
        let send = review_failing_creation(&app, &panel, &script, status, cx).await;
        cx.update(|window, cx| send.focus(window, cx));
        draw(cx);
        press_return(cx);
        settle_panel(&app, cx).await;
        draw(cx);
        assert_eq!(
            panel
                .read_with(cx, |panel, _| panel.error.clone())
                .as_deref(),
            Some(said),
            "{kind}"
        );
        let [form, stored, listed] = left_of_the_draft(&app, &panel, cx).await;
        for (kept, held) in [
            (form, "form"),
            (stored, "store"),
            (listed, "Recover drafts"),
        ] {
            assert_eq!(kept, [sent_form()], "{kind}: the {held} keeps the draft");
        }
    }
}

/// A creation refused because its branch already has a pull request keeps its draft
